window.__D("text/torat-shmuel/c058",{"p":[[2001910444,"<b>קיצור</b> וא\"ו), והנה נודע כי המתברר עולה למעלה מן המברר, ולכן בירורי הניצוצי' דתהו שעולים מנוגה כשמתעלים בשבת עולים לבחי' תענוג הפשוט שלמעלה מהחכ' והיינו בחי' אני ראשון הנ\"ל וע\"י נמשך בחכ' מבחי' אני ראשון, ואז נעשה השבת בחי' דכר ומשפיע כו', וזהו דכתי' זכור בקמץ, שיהי' משמעותו גם לשון דכר ומשפיע כו', והיינו בחי' ש\"ת וש\"ע<sup data-n=\"4544\">109</sup> כו'.\nז) <b>ומעתה</b> יובן ענין המכילתא במה שהמשיל את השבת לזאב כו', דהנה כתי' בנימין זאב יטרף<sup data-n=\"4545\">110</sup> ומתרגמינן ע\"ז בארעי' תשרי שכינתא ובאחסנתי' יתבני מקדשא, ולכאורה אינו מובן דבשלמא הקרבת הקרבן ע\"ג המזבח שייך לקרותו בש' טרף שהוא נק' אכילת המזבח אבל באמת ענין הקרבנות רמז אח\"כ במ\"ש בבוקר יאכל עד<sup data-n=\"4546\">111</sup> כו' כמשי\"ת ומאמר זאב יטרף לא קאי רק על השראת השכינה (שהיא היתה בחלקו של בנימין לבד כידוע שההיכל והדביר והמזבח במקום שהי' לו יסוד<sup data-n=\"4547\">112</sup> הכל הי' בחלקו של בנימין) ומהו\"ע השראת השכינה לקרותו בש' טרף כו'. אך הענין יובן בהקדם ענין ההפרש בין טרף למזון, כי הנה מזון הבהמות נק' בש' מזון להיות מזונה הוא עשב הגדל בשדה כמאמר ונתתי עשב בשדך לבהמתך<sup data-n=\"4548\">113</sup> שזהו סיבה קרובה לכן נק' בש' מזון משא\"כ עיקר מזון החיות הוא כאשר מזדמן להם איזה דבר מבע\"ח לטרוף, וזהו דבר שאינו מצוי רק בא ע\"י סיבה רחוקה לכן נק' בש' טרף כו'. ועד\"ז יובן ברוחני' שיש ב' מיני שפע, הא' הבא בדרך השתל' עו\"ע<sup data-n=\"4549\">114</sup> שהוא מחכ' לבינה ומבינה למדות כו' ונק' אוא\"ס המתלבש בבחי' ח\"ע בש' ממכ\"ע<sup data-n=\"4550\">115</sup> והו\"ע עה\"ע<sup data-n=\"4551\">116</sup> משא\"כ מציאות החכ' מלמעלה מן החכ' נמשך שלא בסדר והדרגה דעו\"ע רק מאין ליש בדרך דילוג הערך כמאמר והחכ' מאין תמצא כו' ולכן גם השפע הנמשכים<sup data-n=\"4552\">117</sup> מבחי' אור א\"ס שבבחי' ח\"ע נק' בש' מזון שהוא בחי' סיבה קרובה משא\"כ בחי' תוס' אורות הנמשכים מלמעלה מן החכ' בבחי' ח\"ע שהוא בחי' סיבה רחוקה נק' בש' טרף, וזהו\"ע טרף נתן ליראיו<sup data-n=\"4553\">118</sup>, כי יראיו מקבלים השפע הנמשך מלמעלה מן החכ' בחי'<sup data-n=\"4554\">119</sup> ח\"ע כו'. והנה מזה הטעם נק' השראת השכינה בש' טרף, כי עיקר ענין השראת השכינה הוא בחי' גילוי סוכ\"ע",[["4544","109","<b>ש\"ת וש\"ע</b>: שבת תתאה ושבת עילאה."],["4545","110","<b>בנימין זאב יטרף</b>: ויחי מט, כז ובתרגום אונקלוס שם."],["4546","111","<b>הקרבנות . . בבוקר יאכל עד</b>: ת\"א־ תיוב\"ע־ ת\"י שם. ב\"ר פצ\"ט, ג. סה\"מ תר\"ם ח\"א ע' ריד. וש\"נ."],["4547","112","<b>שההיכל . . והמזבח . . יסוד</b>: ראה יומא יב, א. זבחים נג, ב ואילך. אוה\"ת ישעי' כרך א ע' קכד ואילך."],["4548","113","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["4549","114","<b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["4550","115","<b>ממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["4551","116","<b>עה\"ע</b>: עילת העילות — ת\"ז בהקדמה יז, א."],["4552","117","<b>השפע הנמשכים</b>: ה: השפע הבא מלמע' מן החכ' בבחי' החכ' בבחי' תוס' אורות היא נמשכת ג\"כ בדרך דילוג הערך ובחי' אא\"ס שבכתר שלמע' מן החכ' נק' בשם סוכ\"ע [זהר פינחס שם] והוא בחי' סיבות כל הסיבות [ראה פרדס שער אם הא\"ס הוא הכתר ש\"ב, פ\"א. של\"ה בית ה' ו, א] והנה בחי' תוס' אורות הנמשכים."],["4553","118","<b>טרף נתן ליראיו</b>: תהלים קיא, ה."],["4554","119","<b>בחי'</b>: בבוך 810: בבחי'."]]],[2001910445,"שיתגלה למטה בהיכל ק\"ק כו' ובחי' זאת נק' בש' טרף כו'. וזהו בנימין זאב יטרף, כי בנימין נק' בנימין הצדיק<sup data-n=\"4555\">120</sup>, ובחי' צדיק הוא העולה למעלה מעלה וממשיך מבחי' אוא\"ס שלמעלה מבחי' ח\"ע בבחי' ח\"ע עד למטה מטה בבחי' המל' שהוא בחי' ביהמ\"ק<sup data-n=\"4556\">121</sup> ולכן נק' בש' טורף כנ\"ל (וכידוע דיסוד עולה עד פנימי' הכתר<sup data-n=\"4557\">122</sup> וממשיך משם בבחי' המל' וזהו דאחיד בשמו\"א<sup data-n=\"4558\">123</sup> כו'). ואח\"כ א' בבקר יאכל עד ולערב יחלק שלל, שהו\"ע היחודים עליונים הנמשכים בכ\"י מלמעלה מהשתל' בהשתל' ע\"י הקרבנות שהו\"ע את הכבש אחד תעשה בבקר ואת הכבש השני תעשה בין הערביים<sup data-n=\"4559\">124</sup> כו', כי ע\"י הקרבת הבהמה ע\"ג המזבח הי' עולה החיות שבה מבחי' נוגה ומתעלה ונכלל בשרשם<sup data-n=\"4560\">125</sup> פני שור<sup data-n=\"4561\">126</sup> שבמרכבה ומשם עולים<sup data-n=\"4562\">127</sup> למעלה מעלה באורות דתהו, והעלאה זאת גורם ההמשכה חדשה מלמעלה מהשתל' בבחי' השתל' כו' (והנה בחי' בירורי נוגה שיעלו להכלל בקדושה נק' ג\"כ בשם סיבה רחוקה שזהו ג\"כ בחי' דילוג הערך התהפכות הרע לטוב, וזהו בכל לבבך דא איהו רזא<sup data-n=\"4563\">128</sup> כו', וזהו ממרחק תביא לחמה<sup data-n=\"4564\">129</sup> וכמבואר בבה\"ז<sup data-n=\"4565\">130</sup> במאמר איהו אזלת למרחוק לאתר רחוק ואייתיאת משם מאנא<sup data-n=\"4566\">131</sup> כו'). וזהו\"ע בנימין זאב יטרף שהו\"ע השראת השכינה בד\"כ מלמעלה מהשתלשלות בבחי' השתל' וממילא נעשה שם מקום להקרבת הקרבנות להמשיך תוס' אורות חדשים בכ\"י שזהו\"ע בבוקר יאכל עד כו'.\n<b>קיצור</b> ז), ומעתה יובן דברי המכילתא שהמשיל השבת לזאב הטורף, דהנה כתי' בנימין זאב יטרף, ומתרגמינן בארעא תשרי שכינתא ובאחסנתי' יתבני בית מקדשא<sup data-n=\"4567\">132</sup>, ולכאו' א\"מ מהו שייך ללשון טרף, שהקרבנות שאפשר לכנותן בש' טרף זהו מרומז במ\"ש אח\"כ בבקר יאכל עד, ומ\"ע השראת השכינה לכנותו בשם טרף, ויובן בהקדם פי' טרף שאין פי' כמו מזון, כ\"א שמזון כמו מזון האדם והבהמה נק' בשם מזון שזהו סיבה קרובה שניזוני' מצמח האדמה, כמ\"ש עשב לבהמתך, ולחם לבב אנוש יסעד<sup data-n=\"4568\">133</sup>, אבל מזון החיות הוא מסיבה רחוקה והיא הנק' בשם טרף שטורף",[["4555","120","<b>בנימין נק' בנימין הצדיק</b>: יומא יב, א. סוטה לז, א. ראה זהר ויצא קנג, ב."],["4556","121","<b>המל' . . ביהמ\"ק</b>: ראה ע\"ח שער לידת המוחין שכ\"א, פ\"ב."],["4557","122","<b>דיסוד עולה עד פנימי' הכתר</b>: ראה גם סידור שער המילה קמט, ד. שער האמונה נא, א. שעה\"י קכה, א ובהערה 7. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670349\" data-slug=\"torat-chaim\" data-id=\"2300670349\">תו\"ח נח נא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670079\" data-slug=\"torat-chaim\" data-id=\"2300670079\">לך פ, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670393\" data-slug=\"torat-chaim\" data-id=\"2300670393\">פירוש המלות פו, ג</a>. ק, ד. פלח הרמון פסח ע' עד. בחוקותי ס\"ע תקלב."],["4558","123","<b>דאחיד בשמו\"א</b>: ראה גם לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי הערה 238."],["4559","124","<b>את הכבש אחד . . הערביים</b>: פינחס כח, ד."],["4560","125","<b>הבהמה . . ומתעלה ונכלל בשרשם</b>: ראה זהר פינחס רמ, ב. סה\"מ תרכ\"ז ע' קמה ואילך ובהנסמן שם. תרל\"ח ע' לה. תרל\"ט ח\"ב ע' תקנב. וש\"נ."],["4561","126","<b>הבהמה . . ונכלל בשרשם . . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["4562","127","<b>בשרשם . . עולים</b>: ה: בשרשו . . עולה."],["4563","128","<b>בכל לבבך דא איהו רזא</b>: ואתחנן ו, ה. ראה תו\"א וישלח כו, ד. לקו\"ת חוקת נח, ד ובהנסמן במ\"מ לשם."],["4564","129","<b>ממרחק תביא לחמה</b>: משלי לא, יד."],["4565","130","<b>וכמבואר בבה\"ז</b>: פינחס קטו, ב ואילך."],["4566","131","<b>איהו . . מאנא</b>: ה: האילת במאמר איהי .ֿ. מזונא."],["4567","132","<b>בארעא . . בית מקדשא</b>: השווה הלשון המובא לעיל בפנים."],["4568","133","<b>ולחם לבב אנוש יסעד</b>: תהלים קד, טו."]]],[2001910446,"בע\"ח ואוכלה שאינו מצוי כמו עשב השדה כו', ועד\"ז יובן ברוחני' שיש ב' מיני שפע הא' עילת העילות, הב' סיבת הסיבות, עה\"ע הוא בחי' ממכ\"ע שנמשך מחכ' לבינה, ומהם לזו\"נ, משא\"כ מציאות החכ' מלמעלה מן החכ' זהו מאין למציאות יש דחכ' בדרך דילוג הערך ולכן נא' ע\"ז תמצא בדרך מציאה<sup data-n=\"4569\">134</sup> סיבה רחוקה סבה\"ס, וא\"כ ההמשכה מח\"ע ואילך נק' בשם מזון, משא\"כ ההמשכה מלמעלה מהחכ' נק' טרף, וז\"ע טרף נתן ליראיו, וכדכתי' אין מחסור ליראיו<sup data-n=\"4570\">135</sup> ע\"ד ב\"נ רבות וחסרונן<sup data-n=\"4571\">136</sup> מילוי החסרון כו', ולפ\"ז יובן שענין השראת השכינה בבהמק\"ד שהי' בחלקו של בנימין הוא הנק' טרף להיות כי בו הי' גילוי סוכ\"ע, והוא בחלקו של בנימין להיותו בחי' צדיק (שלא הי' במכרי\"ו<sup data-n=\"4572\">137</sup>) שעולה מעלה מעלה להמשיך אוא\"ס שלמעלה מהשתלשלות, כידוע שיסוד עולה עד הדעת ופנימיות הכתר, וממשיך במל' וזהו דאחיד בשמי' (היינו שמי השמים) וארעא, וזהו בנימין זאב יטרף, ואח\"כ בבקר יאכל עד היינו הקרבנות שע\"י נמשך יחודי' עליונים ע\"י בירורי ניצוצות דתהו שעולים וגורמים המשכה חדשה מלמעלה מהשתלשלות, והנה בירורי נוגה זהו ג\"כ סיבה רחוקה, כדכתי' ממרחק תביא לחמה, וז\"ע בנימין זאב כו' שבאחסנתי' יתבני מקדשא וישרי שכינתי' ויקריבו שם קרבנות כו'.\nח) <b>ומעתה</b> יובן ענין יום השבת שנק' בש' זאב, להיות שיום זה גורם עליית כל הבירורים מנוגה עד למעלה מעלה מהשתל' וממשיך משם המשכה חדשה בבחי' חכ\"ע וגילוי זה נמשך למטה מטה מרכ\"ד עד סוכד\"ר (והו\"ע לקדשו המבו\"ל שנמשך ע\"י ששת ימים תעבוד כו' ובחי' המשכה זאת נק' בש' טרף כנ\"ל הן בחי' העלאה והן בחי' ההמשכה) וכ\"ז נעשה ע\"י יום השבת לכן נק' יום השבת בש' זאב הטורף כו'. והנה כל הנ\"ל נק' טורף מלפניו כי ההמשכה שהוא נמשך מלמעלה מהשתל' הוא מחמת הבירורים שקדמו בששת ימים שלפניו כי הם הכנה ליום השבת כמאמר מחד בשבתא לשבתא<sup data-n=\"4573\">138</sup> כו' (ומי שטרח בע\"ש<sup data-n=\"4574\">139</sup> יאכל בשבת), אך מה שא' שהוא טורף גם מלאחריו היינו שממשיך קדושת השבת שהוא בחי' המשכה מלמע' מבחי' ח\"ע כנ\"ל גם בששת ימים שלאחריו (כידוע דמיני' מתברכין כל שיתא יומין<sup data-n=\"4575\">140</sup> כו'). והנה מה שטורף מלפניו נק' בש' זכור כנ\"ל שבחי' הבירורים דששת ימים שנק' בשם טרף (להיות שבאים מנוגה אתר רחוקא) לכן נק' עושין את השבת להיות בבחי' זכר משפיע כו', משא\"כ מה שטורף מלאחריו נק' בש' שמור להיות שצריך לשמור קדושה זאת, וענין השמירה הוא ע\"י שיזהר מלדבר שקר ח\"ו, כי הנה קדושת השבת נק' בש' אמת<sup data-n=\"4576\">141</sup> כי אמת הוא ג\"כ המשכה מלמעלה מהשתל'",[["4569","134","<b>דחכ' . . תמצא בדרך מציאה</b>: ראה לעיל מאמר ד\"ה שלש רגלים תחוג לי רפ\"ג. וש\"נ."],["4570","135","<b>אין מחסור ליראיו</b>: תהלים לד, י. ראה גם לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 235."],["4571","136","<b>ב\"נ רבות וחסרונן</b>: ראה שו\"ע אדה\"ז הל' ברכת הפירות סר\"ז, ס\"ב. לקו\"ת ואתחנן ד, ג."],["4572","137","<b>במכרי\"ו</b>: במכירת יוסף."],["4573","138","<b>מחד בשבתא לשבתא</b>: ראה ביצה טז, א."],["4574","139","<b>ומי שטרח בע\"ש</b>: ע\"ז ג, א."],["4575","140","<b>דמיני' מתברכין כל שיתא יומין</b>: זהר בשלח סג, ב. יתרו פח, א. ראה מאמרי אדה\"ז על מארז\"ל ע' רסא ואילך."],["4576","141","<b>השבת . . אמת</b>: ראה זהר יתרו צ, סע\"א. אוה\"ת תשא ע' א'תתקנו ואילך."]]],[2001910447,"דח\"ע (כנ\"ל בענין חותמו של הקב\"ה אמת) ולכן כשדובר שקרים ח\"ו הוא מסלק ממנו קדושת השבת ח\"ו ונק' מחלל את השבת ולכן צריך לשמור א\"ע מזה כו', וזהו שמור מלאחריו כו', והנה כל הנ\"ל הוא בחי' השבת שיש בחי' דכר ונוק' משפיע ומקבל וכנ\"ל באריכות.\n<b>קיצור</b> ח), ועפ\"ז יובן מה שנק' השבת בשם זאב שטורף, כי כל הבירורים דנוגה שמבררי' בששת ימי החול עולים בשבת עד למעלה מהשתלשלות ונמשך משם תוס' בשבת שז\"ע לקדשו שנת\"ל ובחי' זכור בקמץ, שז\"ע טורף מפני שזהו מלמעלה מבחי' ממכ\"ע בחי' עה\"ע כ\"א מבחי' סוכ\"ע סה\"ס כו', וכ\"ז נק' טורף מלפניו כי זהו מהבירורים דששת ימים שקדמו לשבת, וכן ארז\"ל מי שטרח בע\"ש, ואמרו מחד בשבתא לשבתא, וכמארז\"ל מונה ששה ימים<sup data-n=\"4577\">142</sup> ומשמר יום א' שצ\"ל תחלה ששה ימים, שז\"ע לעשות השבת שיהי' בבחי' דכר ומשפיע, אך מה שטורף מלאחריו זהו מה שנמשך קדושת השבת בששת ימים שלאחריו דמיני' מתברכין כל הששה ימים כו' זהו שטורף מלאחריו, רק שמלפניו נק' זכור שעושים השבת בבחי' דכר, ומלאחריו נק' שמור שצריכים לשמור קדושת השבת והיינו שלא ישקר כי שבת נק' אמת לכן ע\"ה ירא לשקר בשבת<sup data-n=\"4578\">143</sup>, ודבר שקרים לא יכון<sup data-n=\"4579\">144</sup>, לכן צריך לשמור שלא יסלק ממנו קדושת השבת כו'.\nט) <b>ומעתה</b> י\"ל ענין יוה\"כ שנק' שבת שבתון כו' כי הנה כתי' ארי' שאג מי לא יירא<sup data-n=\"4580\">145</sup> כו' וארי' ר\"ת אלול ר\"ה יו\"כ<sup data-n=\"4581\">146</sup>, והענין הוא שיוהכ\"פ נק' ארי' רק שההכנה ליוהכ\"פ שהוא מדאורייתא הנה הוא מתחיל מר\"ה ומדרבנן מתחיל מר\"ח אלול<sup data-n=\"4582\">147</sup> ולכן ר\"ת ארי' כולל ר\"ת מכל הג' בחי' כנ\"ל. וביאור הענין שיוהכ\"פ נק' בש' ארי' הנה שאגת הארי הוא בכח גדול ובתגבורות גדולה מאד, וברוחני' ע\"ד העבודה הוא בחי' בע\"ת דמשכין לי' בחילא יתיר<sup data-n=\"4583\">148</sup>, להיות שבע\"ת הי' מקודם כל ימיו בתכלית הריחוק ופירוד ממקורו לזאת בזכרו על ה' אשר הוא מקום<sup data-n=\"4584\">149</sup> חיותו והוא נפרד ממנו בתכלית לזאת יצעק אל ה' בתגבורות גדולה לצאת מגדרי הכלי ולמאוס בחייו לגמרי עד שלפעמים תצא נשמתו לגמרי כמו בראב\"ד שיצאה נשמתו<sup data-n=\"4585\">150</sup> כו' (אם לא אותם אשר ה' חפץ בחייהם פועל בהם שוב אחרי הרצוא בתגבורות הנ\"ל והו\"ע בע\"כ אתה חי<sup data-n=\"4586\">151</sup> כו'), ולכן נק' חילא יתיר שהוא למעלה",[["4577","142","<b>מונה ששה ימים</b>: שבת סט, ב. ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 161."],["4578","143","<b>ע\"ה ירא לשקר בשבת</b>: ירושלמי דמאי רפ\"א. ראה גם לקו\"ש בהעלותך כרך ד ע' 1038 הערה 24."],["4579","144","<b>ודבר שקרים לא יכון</b>: תהלים קא, ז."],["4580","145","<b>ארי' שאג מי לא יירא</b>: עמוס ג, ח."],["4581","146","<b>וארי' ר\"ת אלול ר\"ה יו\"כ</b>: של\"ה ריש מס' ר\"ה ריג, א בשם הקדמונים. תושב\"כ שופטים שעה, ב. ובסידורו דינים והנהגות של ר\"ה רפד, א."],["4582","147","<b>שההכנה ליוהכ\"פ . . מר\"ח אלול</b>: ראה טושו\"ע הל' ר\"ה סתקפ\"א."],["4583","148","<b>בע\"ת דמשכין לי' בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540123\" data-slug=\"torat-chaim\" data-id=\"2300540123\">תו\"ח שמות ח\"א לז, א</a>. וש\"נ. פלח הרמון אחרי ע' קפח ואילך."],["4584","149","<b>מקום</b>: בבוך 73: מקור."],["4585","150","<b>בראב\"ד שיצאה נשמתו</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["4586","151","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."]]],[2001910448,"מצ\"ג, שהגם שבצ\"ג יכול להיות ג\"כ כלות הנפש (כמו בג' תלמידי רשב\"י שנסתלקו באד\"ר<sup data-n=\"4587\">152</sup>) הנה זהו מצד עוצם העונג בעריבות ומתיקות<sup data-n=\"4588\">153</sup> שתרגיש הנפש באלק\"ח<sup data-n=\"4589\">154</sup> ותגעל הנפש את הבשר כו' (כמ\"ש באוה\"ח<sup data-n=\"4590\">155</sup> כו') ואין זה רק מצד גילוי היחידה ולא נגע עדיין לתוכיות נקודת הלב שהוא בחי' עצמיות היחידה משא\"כ בבע\"ת שהצעקה אצלו הוא מצד ההיפוך והמנגד נוגע לעצמיות נקודת הלב שהוא בחי' עצמיות היחידה כו', וזהו\"ע חילא יתיר דבע\"ת שגבוה מצ\"ג כמארז\"ל במקום שבע\"ת<sup data-n=\"4592\">157</sup> צ\"ג אין יכולים לעמוד<sup data-n=\"4591\">156</sup> כו', ובחי' חילא יתיר זה נק' ארי' שהוא למעלה מבחי' זאב שהוא בחי' צ\"ג כנ\"ל.\n<b>והנה</b><sup data-n=\"4593\">158</sup> זהו כוונת מארז\"ל דריסת זאב בדקה<sup data-n=\"4594\">159</sup> ודריסת ארי' בגסה, כי הנה דקה הוא בחי' דקות הרע דנוגה שהו\"ע תאוות היתר, אבל בחי' גסה הוא גקה\"ט (והיינו בחי' גסות הרע דנוגה שהוא מקור לגקה\"ט שהו\"ע כמו תאוות היתר ברשפי אש שמזה יוכל לבא לכלל איסור ח\"ו<sup data-n=\"4595\">160</sup> כמבואר במ\"א), והנה ע\"י רשפי אש האהבה דצ\"ג לא יוכל להתהפך רק בחי' דקות הרע דנוגה לקדושה (והו\"ע חולין שנעשו על טה\"ק כנ\"ל<sup data-n=\"4596\">161</sup> אבל ע\"י תוקף הארי' דבע\"ת שנק' ארי', יוכל להתהפך גם גסות הרע ויוכלל בקדושה ולכן זדונות נעשו לו כזכיות<sup data-n=\"4597\">162</sup> כו', והו\"ע ההתהפכות מטמא לטהור כו'. והנה עם הנ\"ל יובן ענין ההפרש בין שבת ליוהכ\"פ שנק' שבת שבתון, כי שבת הוא ע\"ד הבחי' דצ\"ג שמהפך מבחי' חול לבחי' קודש משא\"כ יוהכ\"פ הוא ע\"ד הבחי' דבע\"ת שמהפך מטמא לטהור כו' ולכן הוא יום סליחת העוונות וזדונות נעשו לו כזכיות, והטעם לזה הנה מבואר למעלה שבחי' שבת הוא בחי' העלי' לבחי' חכ\"ע הנק' קודש (כידוע דחכ' הוא בחי' קדוש<sup data-n=\"4598\">163</sup> מלה בגרמי' כו' וכנ\"ל), אך ביוהכ\"פ נעשה עלי' יותר גבוה, והיינו לבחי' קדש הקדשים שהוא בחי' פנימי' הכתר והוא ענין בחי' הי' הוא ושמו בלבד<sup data-n=\"4599\">164</sup>, ולכן כל העבודה<sup data-n=\"4600\">165</sup> דיוהכ\"פ הי' בהיכל ק\"ק כו', ולכן גם כל השבתות מתעלים ע\"י יוהכ\"פ לבחי' קדה\"ק כו', ולכן",[["4587","152","<b>בג' תלמידי רשב\"י שנסתלקו באד\"ר</b>: זהר נשא קמד, א-ב."],["4588","153","<b>בעריבות ומתיקות . . כמ\"ש באוה\"ח</b>: ראה שם ר\"פ אחרי ד\"ה א\"י עז\"ה. מובא בכ\"מ בדא\"ח ומהם מאמרי אדה\"א בראשית ע' קעו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550246\" data-slug=\"torat-chaim\" data-id=\"2300550246\">תו\"ח תרומה ח\"ב שו, א</a>. וש\"נ."],["4589","154","<b>באלק\"ח</b>: בבוך 73: באלקים חיים."],["4590","155","<b>באוה\"ח</b>: ה: באוה\"ח הק'. כ\"ק אדמו\"ר מהר\"ש מחק תיבת הק'. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021232\" data-slug=\"likkutei-sichot\" data-id=\"1300021232\">לקו\"ש ח\"ב ע' 508</a> סל\"ג. פלח הרמון וישלח צה, סע\"ב. בא ס\"ע קט. מג\"א ע' שפה. פסח ע' סא. תזריע ע' קמז."],["4592","157","<b>שבע\"ת</b>: בבוך 810: שבע\"ת עומדים"],["4591","156","<b>במקום שבע\"ת . . לעמוד</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a>. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["4593","158","<b>והנה</b>: ע\"פ בוך 73, 810 שמתחיל כאן פיסקא חדשה. וכן לקמן בהקיצור מתחיל כאן פיסקא חדשה."],["4594","159","<b>דריסת זאב בדקה</b>: ראה חולין מב, א (במשנה)."],["4595","160","<b>תאוות היתר . . איסור ח\"ו</b>: ראה שע\"ת ג, סע\"ד ואילך."],["4596","161","<b>כנ\"ל</b>: ה: כנ\"ל)."],["4597","162","<b>זדונות נעשו לו כזכיות</b>: ראה יומא פו, ב."],["4598","163","<b>קדוש</b>: בבוך 810: קדש."],["4599","164","<b>הי' הוא ושמו בלבד</b>: ראה לעיל מאמר ד\"ה שיר המעלות ממעמקים הערה 56."],["4600","165","<b>כל העבודה</b>: לקמן בהקיצור כאן: עיקר העבודה."]]],[2001910449,"נק' שבת שבתון כו' (והנה כמו שמבואר למעלה דבבחי' השבת יש משפיע ומקבל שבחי' מקבל שבו נעשה ממילא ומאיליו כמארז\"ל דשבת מקדשא וקיימא כו', והיינו העלי' לבחי' ח\"ע הנק' שבת תתאה, משא\"כ בחי' משפיע שבו שהוא ההמשכה מבחי' אני ראשון לבחי' ראשית שהוא בחי' המשכת עונג העליון המלובש בכתר זהו דוקא נעשה ע\"י מעה\"ת כו', וכמאמר זכור כו' לקדשו כו', כ\"ה ביוהכ\"פ יש בחי' מקבל ומשפיע ועיצומו של יום הוא בחי' מקבל רק שבחי' מקבל שבו הוא גבוה מבחי' משפיע דשבת<sup data-n=\"4601\">166</sup>.\n<b>קיצור</b> ט), ומעתה יובן ענין יוהכ\"פ שנק' שבת שבתון, הנה כתי' ארי' שאג מי כו', שתי' ארי' הוא ר\"ת אלול ר\"ה יוהכ\"פ, והענין שיוהכ\"פ נק' ארי' ור\"ה הוא הכנה ליוהכ\"פ, ומדרבנן מתחיל ההכנה מר\"ח אלול, ולכן ש' ארי' כולל כל הג' זמנים אלו. ובה\"ע מה שיוהכ\"פ נק' ארי' הנה שאגת הארי' הוא בכח ותגבורת גדולה מאד, וע\"ד העבודה ברוחניות ז\"ע בע\"ת דמשכין לי' לקוב\"ה בחילא יתיר להיות שכל ימיהם הי' בבחי' הריחוק לכן בזכרו על ה' יצעק במר נפשו לצאת ממאסר הגוף, וע\"ד כמו ראב\"ד שיצא נשמתו, ויש אשר בע\"כ אתה חי מפני כי ה' חפץ בחייהם פועל בהם השוב אחר הרצוא, שזהו שלימות העבודה יותר שהרי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"4602\">167</sup>, ועכ\"פ מפני גודל הרצוא דבעת\"ש נק' חילא יתיר ע\"ד גבורת שאגת הארי, והגם שגם בצדיקים גמורים מצינו ג\"כ רצוא בכליות<sup data-n=\"4603\">168</sup> הנפש ממש כמו\"ש בג' תלמידי הרשב\"י ז\"ל באד\"ר שנסתלקו כו', אמנם זהו רק מצד הארת גילוי נקודת הלב, אבל בע\"ת להיות כי זהו מצד המנגד דהיינו ריחוקם מה' אדם<sup data-n=\"4604\">169</sup> הנה כליות נפשם זהו מצד עצם תוכיות פנימיות נקודת הלב שהיא גילוי היחידה עצמה כו' לכן זהו חילא יתיר ולכן נק' בחי' זו בש' ארי' שלמעלה מבחי' זאב הטורף כו'.\n<b>ובזה</b> יובן כוונת מארז\"ל דרוסת הזאב בדקה ודרוסת הארי בגסה, כי פי' דקה היינו דקות הרע דנוגה, שז\"ע תאוות היתר, אבל בחי' גסות זהו בחי' גסות הרע, והיינו בחי' הרע דנוגה שהוא מקור לג\"ק, וע\"ד שארז\"ל היום אומר לו כך<sup data-n=\"4605\">170</sup> ומחר אומר לו כך כו' עבוד כו' שזהו תכלית הרע דג\"ק כו', ויש לו מקור ברע דנוגה כו'. והנה ע\"י האהבה ברשפי אש דצ\"ג אינו יכול להתהפך כ\"א בחי' דקות הרע דנוגה שז\"ע זאב יטרף ודרוסת הזאב רק בדקה וז\"ע בחי' חולין היינו שנתערב טו\"ר, שנעשו על טה\"ק, משא\"כ דרוסת הארי היינו בע\"ת דמשכין בחילא יתיר הוא גם בגסה בחי' גסות הרע שיוכלל בקדושה ולכן זדונות נעשו כזכיות כו', מי יתן טהור מטמא<sup data-n=\"4606\">171</sup>. ועפ\"ז יובן ההפרש שבין שבת ליוהכ\"פ, ששבת הו\"ע עליית העולמות<sup data-n=\"4607\">172</sup>",[["4601","166","<b>דשבת</b>: ה: דשבת כו')."],["4602","167","<b>נתאוה הקב\"ה . . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>. לעיל מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום פ\"א. וש\"נ."],["4603","168","<b>בכליות</b>: כ\"ה בגוכתי\"ק."],["4604","169","<b>אדם</b>: אולי תיבה זו מיותרת."],["4605","170","<b>היום אומר לו כך</b>: ראה שבת קה, ב."],["4606","171","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה גם לקו\"ת חוקת ס, א."],["4607","172","<b>ששבת הו\"ע עליית העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."]]],[2001910450,"והמשכת הענג מבירורי נוגה כנ\"ל זהו כמו העבודה דצ\"ג שמחול יתהפך לקדש, משא\"כ יוהכ\"פ זדונות נעשו כזכיות זהו ע\"י התשובה בחילא יתיר בחי' ארי', והטעם הוא דבשבת העלי' בחכ', שבת כי קדש, אמנם ביוהכ\"פ העלי' לקה\"ק ולכן הי' עיקר העבודה דכה\"ג ביוהכ\"פ בקה\"ק ונק' שבת שבתון וכנ\"ל, וכמו בשבת שיש בחי' מקבל ומשפיע כנ\"ל בחי' שבת בעצם שמקדשא וקיימא, ובחי' אני ראשון שנמשך ע\"י הבירורי' דחול שז\"ע לעשות השבת כנ\"ל, כן ביוהכ\"פ יש ג\"כ ב' בחי' אלו ומה שעצומו של יום מכפר זהו בחי' מקבל שבו, רק שבחי' מקבל זה הוא גבוה יותר מבחי' משפיע דשבת.\nיו\"ד) <b>וביאור</b> הדברים, הנה בחי' מל' דא\"ס שנעשה בבחי' עתיק<sup data-n=\"4608\">*173</sup> יש שני בחי', הא' בחי' ז\"ת שבו שמתלבש בבחי' הכתר הנק' אריך<sup data-n=\"4609\">173</sup> וכידוע בכהאריז\"ל דחסד דעתיק מלובש בגולגלתא<sup data-n=\"4610\">174</sup> כו', (וע\"ד<sup data-n=\"4611\">175</sup> ההסבר נק' עומק<sup data-n=\"4612\">176</sup> המורכב ברצון שהוא בחי' עונג פשוט לגבי התענוג המתלבש בחכ' אך לגבי עצמיות התענוג נק' עונג מורכב כו'), ובחי' הב' הוא בחי' ג\"ר דע\"י שבלתי מתלבש בבחי' הכתר הנק' א\"א (וע\"ד ההסבר הוא בחי' עצמי' התענוג הפשוט שבלתי מורכב אפי' ברצה\"פ כו'). והנה בחי' משפיע דשבת הוא בחי' העונג המלובש ברצוה\"פ הנק' גולגלתא וזהו אני המתלבש בבחי' ראשון כנ\"ל, ובחי' זאת נק' אנכי כו', משא\"כ ביוכ\"פ מאיר בחי' אנכי אנכי כו' (וע' בסידור שער יוהכ\"פ<sup data-n=\"4614\">178</sup>) שהוא בחי' עצמות התענוה\"פ שבלתי מתלבש אפי' ברצון ולכן הוא מוחה פשעיך<sup data-n=\"4613\">177</sup> כו' והוא בחי' הי' הוא ושמו בלבד, אך גם זה הוא רק בחי' מקבל דיוהכ\"פ שהוא עיצומו של יום שהוא ג\"כ מכפר, אך ע\"י מעה\"ת נעשה בחי' משפיע, ובחי' מעה\"ת דיוהכ\"פ הוא בחי' התשו' כנ\"ל (משא\"כ מעה\"ת דשבת הוא בחי' תומ\"צ דו' ימי החול כו'). והענין הוא כי גם ג\"ר דע\"י הוא בחי' מל' דא\"ס שנק' אור א\"ס אבל העצמי'<sup data-n=\"4615\">179</sup> לא יתכן לקרותו גם בש' א\"ס כי הוא למעלה מגדר גילוי והתפשטות, וע\"י התשובה מעוררים קדושת העצמי' שיומשך בבחי' מל' דא\"ס (והו\"ע מקדשי שמך<sup data-n=\"4616\">180</sup> כו') ואז נעשה בחי' דכר ומשפיע. וזהו שלפעמים נא' שבת שבתון הוא<sup data-n=\"4617\">181</sup> שהוא בחי' נוק' ולכן נא' שם חוקת עולם כי בחי' זאת מאיר בו תמיד גם כשאין מעה\"ת שהוא בחי' התשו' מעומקא דליבא ופסוק זה הוא בפ' אחרי, אך בפ' אמור א' שבת שבתון הוא ושם לא נא' חוקת עולם כי שם מיירי שיש בחי' תשובה",[["4608","*173","<b>מל' דא\"ס שנעשה בבחי' </b> [ה: בחי']<b> עתיק</b>: ראה לקמן הערה 206."],["4609","173","<b>הכתר הנק' אריך</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["4610","174","<b>דחסד דעתיק מלובש בגולגלתא</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."],["4611","175","<b>(וע\"ד</b>: כ\"ה בבוך 810. אבל בבוך זה 1130 ובבוך 73 מתחיל כאן קטע חדש."],["4612","176","<b>עומק</b>: בוך 73־ 810: עונג. וכ\"ה בהקיצור כאן."],["4614","178","<b>בסידור שער יוהכ\"פ</b>: רנא, א."],["4613","177","<b>אנכי אנכי . . הוא מוחה פשעיך</b>: ישעי' מג, כה."],["4615","179","<b>העצמי'</b>: ה: העצמות."],["4616","180","<b>מקדשי שמך</b>: נוסח תפלת העמידה לשויו\"ט. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370211\" data-slug=\"torah-or\" data-id=\"3901370211\">תו\"א ויחי מו, ג</a>."],["4617","181","<b>הוא</b>: בבוך 73: היא."]]],[2001910451,"מעומקא דליבא כמש\"א ועיניתם את נפשותיכם<sup data-n=\"4618\">182</sup> שהכוונה הוא גם על בחי' עינוי רוחני' במרירות שתתמרמר הנפש על ריחוקו מה' ותצעק מעומקא דליבא ועי\"ז נמשך קדושת העצמי' בבחי' השם נעשה בחי' דכר ולכן א' שבת שבתון הוא כו'.\n<b>ועתה</b><sup data-n=\"4619\">183</sup> יובן ענין שמחת החג שאחרי יוהכ\"פ ומה שניתוסף בו מצות ניסוך המים, כי הנה ההפרש בין מים ליין, כי יין הוא בחי' בינה<sup data-n=\"4620\">184</sup> וידוע דבחי' חו\"ב הם תרדל\"מ<sup data-n=\"4621\">185</sup> לכן ע\"י ניסוך היין של כל השנה הי' נמשך בחי' חו\"ב בבחי' מוחי' למקורו<sup data-n=\"4622\">186</sup> נש\"י (שהם בחי' זו\"נ למעלה) וממילא יהי' נמשך גם למטה בחי' מוחי' בכל נשמה ונשמה בפרט, אך כ\"ז הוא חכם בבינה<sup data-n=\"4623\">187</sup> אבל בחי' מים הוא בעצם החכ'<sup data-n=\"4624\">188</sup> שהוא בחי' אין והיא כלולה בלמעלה מן החכ' בתכלית ההעלם ועז\"נ אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"4625\">189</sup> (כידוע שיש כמה מדרי' בחכ' חכ' שבכתר או חכ' דא\"ק או חכ' הכלולה בעצמיות אור א\"ס שלפני הצמצום* כו'), ולכן לא הי' יכול להיות המשכת מוחי' מעצם החכ' בכל השנה להיותה בתכלית ההעלם כו' אך בחג שנתגלה עצמי' ההעלם מצד השמחה שהוא שמחה עצמי' להיותה באה מבחי' הקירוב שאחר הריחוק שבכל השנה להיותה בתכלית ההעלם כו' כנ\"ל, ולכן בחג הסוכות שמתגלה עצמי' ההעלם מצד השמחה שהוא שמחה עצמי' להיותה באה מבחי' הקירוב שנעשה ביוהכ\"פ אחרי הריחוק העצום כו' שזה גורם שמחה עצמי' כמבואר<sup data-n=\"4626\">190</sup> במ\"א במשל הבן עם האב<sup data-n=\"4627\">191</sup> כאשר הי' בקירוב תמיד עמו אינו מתענג בגילוי ממנו כי עונג עצמי' לא יוכל לבא בגילוי אך כאשר נתרחק ממנו זמן רב ואח\"כ נתקרב עמו אז נגלה העונג עצמי' למתענגי' זה מזה בגילוי כי כל המנגד גורם גילוי עצום כו'), ולכן יוכל לבא גם ההעלם דעצמיות החכ' לידי גילוי אור ולכן הי' אז שאיבת מים בששון היינו\n\n<i>*)בצד הגליון נרשם: מן הצמצומי' עד וקדמון אצ\"ל:</i>\nהצמצומי' בג' מדריגות שבו שהוא יחיד אחד וקדמון<sup data-n=\"8706\">ה</sup>",[["4618","182","<b>ועיניתם את נפשותיכם</b>: כנראה הכוונה שבפ' אמור כתוב ועיניתם את נפשותיכם בתשעה, משא\"כ בפ' אחרי ששם לא הובא בתשעה — ראה לקו\"ת יו\"כ ע, ב ואילך."],["4619","183","<b>ועתה</b>: ע\"פ בוך 810 שמתחיל כאן פיסקא חדשה. וכן לקמן בהקיצור מתחיל כאן פרק חדש פי\"א."],["4620","184","<b>יין הוא בחי' בינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["4621","185","<b>חו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["4622","186","<b>למקורו</b>: בבוך 73: למקור."],["4623","187","<b>חכם בבינה</b>: ס\"י פ\"א, מ\"ד."],["4624","188","<b>מים . . החכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a> ובמ\"מ הגהות והע\"ק שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540308\" data-slug=\"torat-chaim\" data-id=\"2300540308\">תו\"ח בשלח ח\"א קמג, ב</a> ובהערה 91."],["4625","189","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["4626","190","<b>כמבואר</b>: ה: (כמבואר."],["4627","191","<b>במשל הבן עם האב</b>: ראה גם סידור שער הסוכות רנט, ב. נדפס גם במאמרי אדה\"ז תקס\"ב ח\"א ע' כג. אוה\"ת סוכות ע' א'תשס. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקח. מאמרי אדה\"א הנחות תקע\"ז ע' קיא. אוה\"ת שה\"ש ע' תשח.\n\n<b>ה</b> ) <b>יחיד אחד וקדמון</b>: ראה שעה\"י קטז, ב ואילך."]]],[2001910452,"שהמשיכו בחי' התגלות שמחה גם בבחי' ההעלם דחכ' כו'. ומזה הטעם היו שואבין משם רוה\"ק, כי הנה ההפרש בין נבואה לרוה\"ק<sup data-n=\"4628\">192</sup>, שבבחי' נבואה יש גילוי יותר גבוה מבחי' רוה\"ק אך אעפי\"כ בשרשו רוה\"ק הוא גבוה יותר, הענין הוא כי בחי' נבואה נמשך מבחי' וחכם בבינה ובחי' הבינה מאיר בנו\"ה דז\"א (ששם מקור הנביאים<sup data-n=\"4629\">193</sup> כידוע) אך בחי' רוה\"ק בשרשו הוא בבחי' עצם החכ' שלמעלה מבחי' התלבשות בבינה שנק' קדש מלה בגרמי', וז\"ע דוד מלך ישראל שלא הי' נביא<sup data-n=\"4630\">194</sup>, אך הי' מקור לבעל<sup data-n=\"4632\">196</sup> רוה\"ק<sup data-n=\"4631\">195</sup> והוא גבוה מן הנביאים שאחריו כי אחי' השילוני הי' מב\"ד של דוד<sup data-n=\"4633\">197</sup> והוא הי' רבו של אלי'<sup data-n=\"4634\">198</sup> הנביא (ואליהו מקור של כל הנביאים<sup data-n=\"4635\">199</sup> כו'). וזהו הטעם מה שבר\"ה אומרים פסוקי כתובים קודם לפסוקי נביאים להיות שכאשר המל' עולה בבחי' עלי' נעשי' עט\"ב<sup data-n=\"4637\">201</sup><sup data-n=\"4636\">200</sup> (כי בעלה הוא בחי' ח\"ע המתלבש בבינה כמאמר נודע בשערים בעלה<sup data-n=\"4638\">202</sup> וע\"י הבינה נמשך בבחי' ז\"א משא\"כ עלי' המל' הוא לבחי' עצם הח\"ע שבלתי מתלבשת בבינה ולכן נעשה עטרה לבחי' בעלה כו'<sup data-n=\"4639\">203</sup>. ומעתה יובן ענין הנ\"ל שבעת ניסוך המים דוקא היו שואבין רוה\"ק להיות שאז זמן גילוי עצמי' החכ' שלמעלה מבחי' התלבשות בבחי' בינה ובחי' זאת הוא מקור לבחי' רוה\"ק כנ\"ל, אך בכלל מאתים מנה<sup data-n=\"4640\">204</sup> ולכן יוכשר לזכות לנבואה ג\"כ משם כיונה בן אמיתי שזכה לנבואה בעת שמחת בה\"ש כו'.\n<b>קיצור</b> יו\"ד<sup data-n=\"4641\">205</sup>), וביאור הענין, הנה בבחי' מל' דא\"ס שנעשה עתיק לאצי'<sup data-n=\"4642\">206</sup> יש ב' בחי' הא' ז\"ת שבו שמתלבש בכתר דאצי' כנודע שבחי' חסד דעתיק מלובש בגלגלתא וגבורה דעתיק מלובש במו\"ס, וע\"ד ההסבר זהו בחי' ענג המלובש ברצון שנק' תענוג פשוט לגבי הענג המלובש בחכ', אמנם לגבי עצם הענג נק' ענג מורכב ברצון כו', ובחי' הב' שבו הוא בחי' ג\"ר דע\"י שאינו מתלבש גם בכתר דא\"א,",[["4628","192","<b>ההפרש בין נבואה לרוה\"ק</b>: ראה גם אוה\"ת הושע ע' תלז ואילך."],["4629","193","<b>בנו\"ה דז\"א . . מקור הנביאים</b>: ראה שער היחודים פ\"א. שער רוה\"ק דרוש א (הא'). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">תו\"א מקץ מג, ב</a>. סידור שער הק\"ש עט, א. אמ\"ב שער הק\"ש עא, ב. סה\"מ תר\"ם ח\"א ס\"ע שמד-ה. וש\"נ."],["4630","194","<b>דוד . . שלא הי' נביא</b>: ראה זהר תרומה קנד, א (ובאוה\"ח ומק\"מ שם). הגהות מהרח\"ו לזהר בא לט, א. סוטה מח, ריש ע\"ב. רש\"י מגילה יד, א ד\"ה נבואה. מאמרי אדה\"א שמות ח\"ב ע' תקמו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101283\" data-slug=\"likkutei-sichot\" data-id=\"1300101283\">לקו\"ש בלק כרך ח\"י ע' 275</a> בהערה."],["4632","196","<b>לבעל</b>: ה: לבעלי."],["4631","195","<b>דוד . . מקור לבעל רוה\"ק</b>: ראה שער היחודים ספ\"ב. שער רוה\"ק הנ\"ל."],["4633","197","<b>אחי' השילוני הי' מב\"ד של דוד</b>: הקדמת הרמב\"ם לס' היד."],["4634","198","<b>אחי' השילוני . . רבו של אלי'</b>: ראה ירושלמי ערובין פ\"ה, ה\"א. הקדמת הרמב\"ם שם. שער היחודים פ\"א בשם הרמב\"ן ז\"ל. שער רוה\"ק שם."],["4635","199","<b>ואליהו מקור של כל הנביאים</b>: ראה ירושלמי ערובין שם. לקמן בהקיצור כאן."],["4637","201","<b>עט\"ב</b>: נסמן לקמן הערה 217."],["4636","200","<b>שבר\"ה אומרים . . נעשי' עט\"ב</b>: ראה גם אוה\"ת הושע ע' תלז."],["4638","202","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["4639","203","<b>כו'</b>: ה: כו')."],["4640","204","<b>בכלל מאתיים מנה</b>: ב\"ק עד, א."],["4641","205","<b>קיצור יו\"ד</b>: לפיסקא ראשונה."],["4642","206","<b>מל' דא\"ס שנעשה עתיק לאצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370164\" data-slug=\"torah-or\" data-id=\"3901370164\">תו\"א מקץ לה, ד</a>. לקו\"ת חוקת סז, ב. מאמרי אדה\"ז ענינים ע' א ובהערה שם ובמ\"מ לשם. וראה גם סה\"מ תר\"ם ח\"ב ע' תרכד. וש\"נ."]]],[2001910453,"וע\"ד ההסבר הוא בחי' תענוג הפשוט הבלתי מורכב אפי' ברצה\"פ ג\"כ, ונת\"ל שבחי' משפיע דשבת הוא בחי' ענג המורכב ברצון שז\"ע א' דאמת שמאיר בתרי\"ג ארחין דגלגלתא כנ\"ל בחי' אני ראשון, וזהו נק' אנכי כו', אבל ביוהכ\"פ מאיר ב\"פ אנכי כדכתי' אנכי אנכי הוא מוחה פשעיך שהוא תענוג פשוט שאינו מורכב כלל אפי' ברצה\"פ ולכן נמשך משם מחילת עוונות להיות מוחה פשעיך כו', והיינו בחי' הוא ושמו בלבד, ומ\"מ גם בחי' זו זהו בחי' מקבל שיש ביוהכ\"פ שז\"ע עיצומו של יום שהוא מכפר, ובחי' זו כמו שבת בעצם שהיא מקדשא וקיימא כן בשבת שבתון דיוהכ\"פ שהיא העלי' לקה\"ק ג\"ר דעתיק זהו נק' עיצומו של יום שהוא כדוגמת מקדשא וקיימא, אך ע\"י מעה\"ת שביוהכ\"פ שזהו בחי' ארי' תשו' בחילא יתיר (ולא כמו מעשה התחתונים דשבת שהוא תומ\"צ דששת ימי החול כ\"א תשו' דוקא) נעשה יוהכ\"פ בחי' דכר ומשפיע, והענין כי גם ג\"ר דעת\"י הוא מבחי' מל' דא\"ס שנק' רק בשם אור לבד, משא\"כ בחי' העצמיות אינו שייך לקרותו אפי' בשם א\"ס ג\"כ וכ\"ש בש' אור כו' להיותו למעלה מגדר התפשטות, וע\"י התשו' בחילא יתיר מעוררים העצמיות שיומשך במל' דא\"ס, וז\"ע מקדשי שמך שיומשך מבחי' אתה קדוש בשמך קדוש ואז נעשה בבחי' דכר ומשפיע כו', וזהו מה שבפ' אחרי נא' שבת שבתון היא שקאי על עצומו של יום שעם היותו מכפר מ\"מ נק' היא מקבל כמו קדושת השבת בעצם שנק' קדש וזה נק' קד\"ק, ולכן כתי' חוקת עולם דהיינו תמיד פי' גם כשאין אתדל\"ת ח\"ו בבחי' תשו' כו', משא\"כ בפ' אמור דכתי' ועניתם את נפשותיכם, פי' עינוי אינו עינוי הגשמי דה' עינוי' שביוהכ\"פ<sup data-n=\"4643\">207</sup>, כ\"א גם בחי' עינוי הרוחני שמתמרמר על ריחוקו מה' אחד, מעומקא דליבא ותוך תוך פנימי' נקודת נפשו כו', ולכן לא נא' חוקת עולם בפ' אמור כי העלאת מ\"ן בבחי' עינוי זה לא בכל השני' בשוה, וכשיש העלאת מ\"ן אז מעורר בחי' קדושת העצמיות שיבא לידי גילוי בבחי' מל' דא\"ס ואז נעשה בחי' דכר ומשפיע ולכן נא' בפ' אמור שבת שבתון הוא, וה\"ז כמו ענין לקדשו דשבת רק שזהו בבחי' שבת שבתון כו'.\n<b>קיצור</b> י\"א<sup data-n=\"4644\">208</sup>), ובכ\"ז יובן ענין שמחת החג שאחרי יוהכ\"פ ושניתוסף בו ניסוך המים כי הנה שרש ההפרש בין מים ליין, שהיין הוא בבינה, וחו\"ב הם תרדל\"מ לכן ע\"י ניסוך היין נמשך מחו\"ב מוחין לזו\"נ שהם מקורי נש\"י כידוע וממילא נמשך גם בכל נשמה למטה מוחין חדשים בכאו\"א בפרט, אמנם הנה כ\"ז הוא רק בחי' וחכם בבינה, אך הנה בחי' מים הוא בחי' עצם החכ' שהוא אין כמ\"ש מאין תמצא בדרך מציאה שהוא הוא בחי' האין כמו באין דכתר כמ\"ש במ\"א, ועז\"נ אמרתי אחכמה והיא רחוקה להיותה בחי' אין דכתר, ולכן בכל השנה א\"א שיומשך מבחי' זו להיותה בבחי' ההעלם דכתר כו', ואמנם השמחה דחג שנמשך מיוהכ\"פ שנתעורר ההעלם דבחי' העצמיות דבחי' אתה קדוש בשמך קדוש, ולכן מחמת השמחה של הקירוב שאחרי הריחוק העצום דכל השנה, מתגלה שמחה העליונה מבחי' עצמיות ההעלם במקיפים דסכך הסוכה, ולכן סכך עולה מספר מאה<sup data-n=\"4645\">209</sup> להיות כי מאה הוא",[["4643","207","<b>דה' עינוי' שביוהכ\"פ</b>: יומא רפ\"ח."],["4644","208","<b>קיצור י\"א</b>: לפיסקא שני' מפ\"י ד\"ה ועתה."],["4645","209","<b>סכך עולה מספר מאה</b>: ראה פע\"ח שער חג הסוכות שכ\"ח, פ\"ד. שער הכוונות שם סוף דרוש ד. מ\"ח מסכ' ימי מצוה וסוכה פ\"ג, מ\"א. מעשה חושב — להר\"א אזולאי — רמון כא בסופו. סידור ר\"ש ראשקוב כונת הסוכה ד\"ה סכך ע' צו. סידור קול יעקב כוונת הסוכה הב' קעא, ב (הדפים אינם מסומנים). אוה\"ת ח\"ש כרך ב תכה, ב (ביאוה\"ז — להצ\"צ — ח\"ש כרך א ע' פד). המשך וככה תרל\"ז ספצ\"ג. סה\"מ תרל\"ח ס\"ע תקל. תרע\"ח ע' סב. לקו\"ש סוכות כרך ב' ע' 425. סה\"מ מלוקט א ע' שנז. תורת לו\"י כלים ע' שג."]]],[2001910454,"בחי' כתר כמ\"ש בזח\"א חיי דקך\"ב<sup data-n=\"4646\">210</sup>, וגם מל' נק' סוכך והיינו בחי' מל' דא\"ס שמחה מצד הגילוי דאתה קדוש הנמשך בו כנ\"ל, ולכן הי' ניסוך המים שרומז על עצם ההעלם דחכ' שמתגלה בחה\"ס.\n<b>ועוי\"ל</b> בא\"א, חכמה כח מה<sup data-n=\"4647\">211</sup>, כח התפשטותה אל הבינה מ\"ה ד..ה לגבי הכתר, ומפני הגילוי שנמשך מאתה קדוש מתגלה העלם הכתר והחכ' בזמן שמחתינו ולכן הי' אז שאיבת מים בששון, ולא נא' בפירוש בתושב\"כ בינה להיות כי זהו למעלה מהגילוי שבבינה כ\"א הלמ\"מ<sup data-n=\"4649\">213</sup>, ד\"ס שעריבים יותר מיינה ש\"ת<sup data-n=\"4650\">214</sup>, להיות זהו עצם החכ' סופר<sup data-n=\"4648\">212</sup> שלמעלה מיין ספר, ולכן משם היו שואבין רוה\"ק כו' כי ההפרש בין נבואה לרוה\"ק שנבואה נמשך מחכם בבינה שמשם נמשך בנו\"ה מקור הנבואה, אמנם רוה\"ק הגם שאינו גילוי המהות כנבואה מ\"מ בשרשו גבוה יותר שהוא מעצם החכ', וע\"ד חכם עדיף מנביא<sup data-n=\"4651\">215</sup> קדש מילה בגרמי', וע\"ד דהע\"ה שלא הי' נביא, כ\"א מקור לרוה\"ק שגבוה יותר מנביא, שהרי אחי' השילוני מב\"ד של דוד והוא הי' רבו של אלי', ואלי' מקור נביאים שאלישע הי' תלמידו<sup data-n=\"4652\">216</sup>, ולכן מקדימים פסוקי כתובים במוסף דר\"ה להיות כי אז הוא התחלת הארי' דיוהכ\"פ, ואז הוא עליית המל' שמתעלה להיות אחע\"ב<sup data-n=\"4653\">217</sup>, בעלה הוא חכם בבינה, נודע בשערי' דבינה בעלה חכם בבינה, וע\"י הבינה נמשך בז\"א, משא\"כ עליית המל' לבחי' עצם החכ' ולבחי' הכתר עד שנעשה עטרה לבעלה בחי' חכ' המאיר בבינה, ולכן בהגלות בחי' החכ' בעצם היו שואבין רוה\"ק שמקור רוה\"ק הוא עצם החכ', ועכ\"ז בכלל מאתיים מנה לכן זכה יונה בן אמתי לנבואה משמחת בית השואבה כמ\"ש בירושלמי דסוכה פ\"ה.",[["4646","210","<b>מאה . . כתר כמ\"ש בזח\"א חיי דקך\"ב</b>: אוצ\"ל: קכג, א."],["4647","211","<b>ד. .ה</b>: כאן נרשמה תיבה שא\"א לפענחה. ואוצ\"ל: דבינה."],["4649","213","<b>הלמ\"מ</b>: ראה סוכה לד, א. זבחים קי, ב. רמב\"ם הל' תמידין ומוספין פ\"י, ה\"ו."],["4650","214","<b>ד\"ס שעריבים . . ש\"ת</b>: ראה ע\"ז לה, א וברש\"י שם. סה\"מ תרח\"ץ ע' סד הערה 74."],["4648","212","<b>בתושב\"כ בינה . . החכ' סופר</b>: ראה גם לעיל מאמר ד\"ה שיר המעלות ממעמקים ובהערה 21."],["4651","215","<b>חכם עדיף מנביא</b>: ב\"ב יב, א. ראה לקוטי הש\"ס להאריז\"ל סוף מס' יבמות. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380097\" data-slug=\"likkutei-torah\" data-id=\"4001380097\">ויקרא ה, ד</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540206\" data-slug=\"torat-chaim\" data-id=\"2300540206\">תו\"ח שמות ח\"א נט, א</a> ובהערה 39. המשך וככה תרל\"ז פל\"ז ע' מד. פקפ\"ט ע' רטו."],["4652","216","<b>שאלישע הי' תלמידו</b>: ראה מלכים-א יט, יט-כא. מלכים-ב פ\"ב. ירושלמי ערובין פ\"ה, ה\"א. הקדמת הרמב\"ם שם."],["4653","217","<b>המל' . . אחע\"ב</b>: משלי יב, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">תו\"א ויגש מג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380155\" data-slug=\"likkutei-torah\" data-id=\"4001380155\">לקו\"ת שמיני יט, ב</a>. ש\"א כ, ב והערה 33."]]],[2001910455,"<b>קיצור</b> י\"ב<sup data-n=\"4654\">218</sup>), והנה יום ראשון דסוכת נק' ראשון כמ\"ש ולקחתם לכם<sup data-n=\"4655\">219</sup> ביום הראשון פרי כו', וראשון זה חלוק מכל בחי' ראשון, כי הוא ראשון אחר יוהכ\"פ שמעורר בחי' עצמיות דאתה קדוש (והד' ימים שבין יוהכ\"פ לחג אינם בחשבון<sup data-n=\"4656\">220</sup> כנודע) ויום ראשון דחג הוא הראשון שאחר יוהכ\"פ היינו בחי' דכר ומשפיע שביוהכ\"פ כנ\"ל, ובחי' זו ולקחתם לכם שיומשך המקיף בפנימי ע\"י ד\"מ שבלולב<sup data-n=\"4657\">221</sup> שהם אין<sup data-n=\"4658\">222</sup> שהלולב כפות<sup data-n=\"4659\">223</sup> והדסים תלתא תלתא<sup data-n=\"4660\">224</sup> וערבות גדילים באחוה<sup data-n=\"4661\">225</sup>, ואתרוג דר באילנו משנה לשנה<sup data-n=\"4662\">226</sup> שזהו הכל מצד שהם אין כמ\"ש במ\"א, לכן הם כלים שע\"י יומשך האין דכתר וחכ' בנש\"י להיות לכם, וביום שני דחג מתחיל נסוך המים<sup data-n=\"4663\">227</sup> כנ\"ל רוה\"ק, עד שביום השמיני בחי' חכ' מלמטלמ\"ע<sup data-n=\"4665\">229</sup> עצרת קליטה<sup data-n=\"4666\">230</sup> תהי' לכם<sup data-n=\"4664\">228</sup> שיוקלט כל השפע הנ\"ל בבחי' פנימיות לכם כו'.",[["4654","218","<b>קיצור י\"ב</b>: הוספה על מה שנרשם בפנים. ראה גם לעיל הערה 1."],["4655","219","<b>ולקחתם לכם</b>: אמור כג, מ."],["4656","220","<b>והד' ימים . . אינם בחשבון</b>: ראה גם סה\"מ מלוקט ד' ע' כג ובהנסמן שם."],["4657","221","<b>ד\"מ שבלולב</b>: סוכה לא, א. מנחות כז, א."],["4658","222","<b>ד\"מ שבלולב שהם אין</b>: ראה גם לעיל מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה הערה 117."],["4659","223","<b>שהלולב כפות</b>: ראה סוכה לב, א. סה\"מ מלוקט א' ע' רנג."],["4660","224","<b>והדסים תלתא תלתא</b>: ראה סוכה לב, ב."],["4661","225","<b>וערבות גדילים באחוה</b>: ראה שבת כ, א וברש\"י שם. מאמרי אדה\"א דברים ח\"ד ע' א'שיב בהערה."],["4662","226","<b>ואתרוג דר באילנו משנה לשנה</b>: סוכה לה, א."],["4663","227","<b>וביום שני דחג מתחיל נסוך המים</b>: תענית ג, א (ובפרש\"י ד\"ה אלא ר' יהושע היא)."],["4665","229","<b>שביום השמיני בחי' חכ' מלמטלמ\"ע</b>: ראה גם יאיר נתיב למאו\"א מערכת שמינית סס\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380120\" data-slug=\"likkutei-torah\" data-id=\"4001380120\">לקו\"ת צו יא, א</a>. מאמרי אדה\"ז אתהלך ליאזניא ע' כב. קהלת יעקב מערכת שמיני חג העצרת."],["4666","230","<b>עצרת קליטה</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"ח. לקו\"ת שמ\"ע פח, ד. צא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שנה ואילך. וש\"נ."],["4664","228","<b>שביום השמיני . . עצרת . . תהי' לכם</b>: פינחס כט, לה."]]],[2001910456,"<h3>הקבצו ושמעו</h3>\n<b>ש\"פ ויחי ש' אמ\"ת וצד\"ק לפ\"ק\n(נא' לעת ערב)</b>\n<b>הקבצו</b> ושמעו<sup data-n=\"4667\">1</sup> בני יעקב ושמעו אל ישראל אביכם<sup data-n=\"4668\">2</sup>, ומפרש במדרש (פ' צ\"ד)<sup data-n=\"4669\">3</sup> אל ישראל אביכם שבשמים<sup data-n=\"4670\">4</sup>. והענין דהנה אי' במדרש<sup data-n=\"4671\">5</sup> ובגמ' מהיכן זכו ישראל לק\"ש, אפי' למצות ק\"ש<sup data-n=\"4673\">7</sup> שהיא מצוה כללית<sup data-n=\"4674\">8</sup> וכמ\"ש וזאת המצוה אשר צוה ה' לעשות בארץ<sup data-n=\"4675\">9</sup>, והול\"ל<sup data-n=\"4676\">10</sup> לחשוב כל המצות ולא חשיב רק ק\"ש מפני שהיא מצוה כללית כו', בהסתלקותו<sup data-n=\"4672\">6</sup> של יעקב דכשאמר האספו והגידה לכם<sup data-n=\"4677\">11</sup> כו' נסתלקה ממנו שכינה אמר להשבטים שמא יש בלבכם מחלוקת על הקב\"ה וא\"ל שמע ישראל ה' אלקינו ה' אחד<sup data-n=\"4678\">12</sup> כשם שאין בלבך מחלוקת על הקב\"ה כך אין בלבינו מחלוקת על הקב\"ה, ומ\"ש כאן ישראל צ\"ל שהוא בחי' ישראל סבא, דישראל זוטא הרי אמרו בזהר<sup data-n=\"4679\">13</sup> שהוא מ\"ש כי נער ישראל ואהבהו<sup data-n=\"4680\">14</sup> שגם בחי' ישראל נק' נער, ומ\"ש כאן ישראל קאי על ישראל סבא, ומסיים שם במדרש פי' הפסוק שמע ישראל ממערת המכפלה אותו דבר שצויתנו עדיין נוהג בנו ה' אלקינו ה' אחד. וצ\"ל מ\"ש עדיין נוהג איך שייך לומר שלא ינהג בנו שהרי ק\"ש הוא מ\"ע כמו שארי מצות, ועוד צ\"ל מ\"ש נוהג בנ\"ו. וצ\"ל תחילה דקדוקי הפסוק מ\"ש ה' אלקינו ה' אחד ג' שמות ה' אלקינו ה' ולכאו' הול\"ל ה' אלקינו אחד, וגם לענין הפסוק שלומדי' מזה מצות ליחדו<sup data-n=\"4681\">15</sup> הי' די שיאמר ה' אחד ותו לא כו'. ואי' בספרים<sup data-n=\"4682\">16</sup> שג' שמות אלו הם נגד אני ראשון ואני אחרון<sup data-n=\"4683\">17</sup> ומבלעדי אין אלקים, דשם ה' הא' הוא בחי' אני ראשון קודם שנאצל אצי' העליון ושם ה' הב' הוא בחי' אני אחרון לאחר נון אלפים יובלות<sup data-n=\"4684\">18</sup>,",[["4667","1","<b>הקבצו ושמעו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["4668","2","<b>הקבצו . . אל ישראל אביכם</b>: ויחי מט, ב."],["4669","3","<b>במדרש (פ' צ\"ד)</b>: ראה ב\"ר פצ\"ח, ג."],["4670","4","<b>אל ישראל אביכם שבשמים</b>: שם: אל ישראל שבשמים אביכם. ושם לפנ\"ז: לאל ישראל אביכם."],["4671","5","<b>אי' במדרש</b>: ראה ב\"ר שם. תנחומא ויחי ח, בסופו."],["4673","7","<b>למצות ק\"ש</b>: ראה שו\"ע אדה\"ז ריש הל' ק\"ש."],["4674","8","<b>ק\"ש שהיא מצוה כללית</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקסט. וש\"נ. סה\"מ תרל\"ט ח\"ב ע' תפג. וש\"נ. פלח הרמון אמור ע' שעח. וש\"נ."],["4675","9","<b>וזאת המצוה . . בארץ</b>: ואתחנן ו, א [בדילוגים]. ראה לקו\"ת ואתחנן ד, א. ט, א. מאמרי אדה\"א הנחות תקע\"ז ע' רנה. וש\"נ. לקמן הנחה ד\"ה קדש ישראל לה' פיסקא ומכ\"ז יובן ובהנסמן שם."],["4676","10","<b>והול\"ל</b>: אוצ\"ל: והו\"ל."],["4672","6","<b>ובגמ' . . בהסתלקותו</b>: ראה פסחים נו, א. הנסמן בב\"ר שם."],["4677","11","<b>האספו והגידה </b> [אוצ\"ל: ואגידה]<b> לכם</b>: ויחי מט, א."],["4678","12","<b>שמע ישראל . . ה' אחד</b>: ואתחנן ו, ד."],["4679","13","<b>ישראל סבא דישראל זוטא . . בזהר</b>: בא, מג, א. ויקהל רטז, סע\"א."],["4680","14","<b>כי נער ישראל ואהבהו</b>: הושע יא, א."],["4681","15","<b>מצות ליחדו</b>: ראה רמב\"ם הל' יסוה\"ת פ\"א, ה\"ז. סהמ\"צ להרמב\"ם מ\"ע ב. ולהצ\"צ נט, ב ואילך. אוה\"ת בראשית כרך ז ע' 2328 ואילך."],["4682","16","<b>ואי' בספרים</b>: בס' כד הקמח — במהדורת שעוועל כתבי רבינו בחיי ס\"ע קצז. ראה גם סה\"מ תר\"ם ח\"ב ס\"ע תרצד ואילך ובהנסמן שם."],["4683","17","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["4684","18","<b>נון אלפים יובלות</b>: ראה ש\"ך ר\"פ בהר. מאמרי אדה\"א דברים ח\"א ע' רסח. וש\"נ. סה\"מ תרל\"ח ע' תלד. וש\"נ. תרל\"ט ח\"ב ע' תפא. וש\"נ. תר\"ם ח\"א ע' רצט. וש\"נ."]]],[2001910457,"ומבלעדי באמצעיתא<sup data-n=\"4685\">19</sup> אין אלקים, דאלקים גימט' הטבע<sup data-n=\"4686\">20</sup> ונר' שהטבע הוא שהעולם כמנהגו נוהג<sup data-n=\"4687\">21</sup> אך באמת גם הטבע אלקות וזהו מבלעדי אין אלקים.\n<b>ולהבין</b> זה צ\"ל תחילה ענין אחד שהד' הוא ד' רבתי<sup data-n=\"4688\">22</sup>, ד' הוא בחי' דיבור וכמ\"ש בדבר ה' שמים נעשו<sup data-n=\"4689\">23</sup>, לעולם ה' דברך נצב בשמים<sup data-n=\"4690\">24</sup>, שדבר ה' עומד תמיד<sup data-n=\"4691\">25</sup> בשמים להחיותו ולהוותו מאין ליש ואם הי' נסתלק כרגע הי' נעשה אין ואפס, וזהו א\"ת מחי' אלא מהוה<sup data-n=\"4692\">26</sup>, ואין הכוונה על עת הבריאה לבד כ\"א בכ\"ע ובכל רגע<sup data-n=\"4693\">27</sup> נמשך חיות חדש והוא מבחי' דיבור וזהו ד', וענין ד' רבתי הוא דיבור שבמח'<sup data-n=\"4694\">28</sup> וכמו בראשית נמי מאמר הוא, והלא במאמר אחד<sup data-n=\"4695\">29</sup> יכול להבראות, וכמו שקודם הדיבור צריכים לסדר תחילה מה לדבר, והענין דהנה יש ב' בחי' מח' שבדיבור ודיבור שבמח', מח' שבדיבור הוא מה שבעת הדיבור צריכים והיינו להחזיק את הראש כדי שידבר מה ששייך להשכל בל\"א האלטון ק‘ ער זל ריידן צוא דער זאך, הרי העיקר הוא הדיבור והמח' הוא רק שיצא הדיבור ישר מפיו, ודיבור שבמח' הוא כמו עיון המח' וכמו שמסדר תחילה מה לדבר הרי הסידור הוא בעיון מחשבתו שמשער מה שצריך להתגלה בדיבור והוא מסדר הענין הרי שהוא במח' רק ששייך לדיבור, וזהו נק' דיבור שבמח', ועוי\"ל שאפי' דיבור ממש מ\"מ נק' דיבור שבמח' וכמו ר\"א בר\"ש שדיבר בעניני תורה<sup data-n=\"4696\">30</sup> במקום שאסור לדבר בד\"ת, ומתרץ בגמ' לאונסו שאני מפני שהי' טרוד בהענין והרי הוציא אותיות ממש מתוך פיו ומ\"מ התירו לו חכמים וגם עתה מותר באופן זה<sup data-n=\"4697\">31</sup> וא\"כ ה\"ז בכלל מח' יחשב שאם הי' נחשב לדיבור הרי אסור לדבר אלא שהוא בכלל מח' הרי יש דיבור ממש",[["4685","19","<b>ומבלעדי באמצעיתא</b>: ראה ת\"ז ת\"ע קכ, סע\"א. שע\"ת קמו, א ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550308\" data-slug=\"torat-chaim\" data-id=\"2300550308\">תו\"ח תצוה ח\"ב שלא, ג</a>."],["4686","20","<b>דאלקים גימ' הטבע</b>: ראה שבילי אמונה — לר' מאיר אבן אלדבי — הנתיב הראשון (ט, ב). פרדס שער הנתיבות שער י\"ב, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540086\" data-slug=\"torat-chaim\" data-id=\"2300540086\">תו\"ח שמות ח\"א לח, א</a> הערה 20."],["4687","21","<b>שהעולם כמנהגו נוהג</b>: ע\"ז נד, ב."],["4688","22","<b>אחד . . ד' רבתי</b>: מסורה גדולה ואתחנן ו, ד וריש בראשית. זהר בהקדמה יב, א. פינחס רלו, ב."],["4689","23","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["4690","24","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["4691","25","<b>שדבר ה' עומד תמיד</b>: ראה שער היחוה\"א פ\"א. לקמן הנחה ד\"ה והמים להם חומה על יד הערה 75 ואילך."],["4692","26","<b>א\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["4693","27","<b>בכ\"ע ובכל רגע</b>: ראה גם הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' 2040. סה\"מ תר\"ם ח\"א ע' ה. וש\"נ."],["4694","28","<b>ד' רבתי . . דיבור שבמח'</b>: ראה גם (בנוסף להערה 1) מאמרי אדה\"א דברים ח\"א ע' רפג ואילך."],["4695","29","<b>בראשית נמי מאמר הוא והלא במאמר אחד</b>: בראשית א, א. ר\"ה לב, א. אבות רפ\"ה. ראה מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. סה\"מ תרכ\"ז ע' רפב ואילך. לקמן הנחה ד\"ה כי תבואו כו' ושבתה הארץ על יד הערה 44. סה\"מ מלוקט ג' ע' קסד ואילך. וש\"נ."],["4696","30","<b>ר\"א בר\"ש שדיבר בעניני תורה</b>: זבחים קב, ב."],["4697","31","<b>וגם עתה מותר באופן זה</b>: ראה הל' ת\"ת לאדה\"ז ספ\"ג."]]],[2001910458,"שהוא נחשב בכלל מח' וזהו דיבור שבמח', וזהו\"ע ד' רבתי דאחד, שהוא דיבור כנ\"ל מ\"מ הוא בכלל מח', וגם ד' הוא ד' מחנות שכינה<sup data-n=\"4698\">32</sup> וד' חיות המרכבה<sup data-n=\"4699\">33</sup> פני ארי' פני שור פני נשר פני אדם שהם מקור כל סדר השתל', דפני ארי' מקור כל החיות<sup data-n=\"4700\">34</sup> ופני שור מקור כל הבהמות<sup data-n=\"4701\">35</sup> ופני נשר מקור כל העופות<sup data-n=\"4702\">36</sup> ופני אדם מקור שכלים הנבדלים<sup data-n=\"4703\">37</sup>.\n<b>והנה</b> עצם תי' אחד ארז\"ל כד אמליכתי'<sup data-n=\"4704\">38</sup> למעלה ולמטה ולד' רוחות העולם תו לא צריכנא, וזהו תי' אחד ח\"ד מורה על ז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"4706\">40</sup> אף שנעשו ז' רקיעים כו' מ\"מ בטלים לא\"ס<sup data-n=\"4705\">39</sup> אלופו ש\"ע<sup data-n=\"4707\">41</sup>, ולכאו' צ\"ל איך יצדקו שניהם כא' שנתהוו במציאות ומ\"מ בטלים, אך הענין הוא דהנה דיבור למעלה אינו דומה לדיבור למטה<sup data-n=\"4708\">42</sup>, דלמטה הדיבור הוא נפרד מהאדם, אבל למעלה הדיבור הוא מתאחד עם אלקות וכמ\"ש את השמים ואת הארץ אני מלא<sup data-n=\"4709\">43</sup>, לית אתר פנוי מני'<sup data-n=\"4710\">44</sup>, אין לך דבר שחוץ ממנו, וא\"כ אינו שייך שיהי' נפרד ולהיכן נפרד וא\"כ גם הנבראים שנתהווה מהדיבור אינם נפרדים כ\"א בטלים לאלקות. וביאור הענין דהנה דכשנתבונן היטיב יובן איך שהדיבור באדם ג\"כ אינו נפרד<sup data-n=\"4711\">*45</sup>, ויובן מפעולתו על העצם כמו השפעת הרב לתלמיד שהוא בדיבור ועי\"ז הוא מתקשר אל הרב כ\"כ עד שבענין הרב יש בכוחו למס\"נ ושוכח על עניני עצמו לגמרי והוא מפני שנוגע למקור המשפיע, וכן הוא בתורה הנגלית ג\"כ שארז\"ל אבידת אביו ואבידת רבו<sup data-n=\"4712\">45</sup> אבידת רבו קודמת כו' שרבו שלמדו חכ' מביאו לחיי עוה\"ב, והרי הבן שרשו",[["4698","32","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["4699","33","<b>וד' חיות המרכבה</b>: יחזקאל פ\"א. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, סע\"א</a> ואילך."],["4700","34","<b>דפני ארי' . . החיות</b>: ראה טעמי המצות להרח\"ו ר\"פ ויקרא. אור החיים אחרי יז, יד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380436\" data-slug=\"likkutei-torah\" data-id=\"4001380436\">לקו\"ת בהעלותך לא, ג</a>. מאמרי אדה\"א דברים ח\"ד ע' א'רו וע' א'רפה. סה\"מ תרל\"ח ע' יז. וש\"נ."],["4701","35","<b>ופני שור . . הבהמות</b>: ראה בהערה שלפנ\"ז. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרכ\"ט ע' קי. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["4702","36","<b>ופני נשר . . העופות</b>: ראה לעיל הערה 34. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380422\" data-slug=\"likkutei-torah\" data-id=\"4001380422\">לקו\"ת נשא כח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550172\" data-slug=\"torat-chaim\" data-id=\"2300550172\">תו\"ח יתרו ח\"ב ער, א</a>. סה\"מ תרכ\"ט שם."],["4703","37","<b>ופני אדם מקור שכלים הנבדלים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 47."],["4704","38","<b>כד אמליכתי'</b>: ראה ברכות יג, ב. אמרי בינה פתח השער בתחילתו."],["4706","40","<b>ח\"ד . . ז' . . וד' רוחות העולם</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. סה\"מ תר\"ם ח\"א ע' קט הערה 50."],["4705","39","<b>אחד . . לא\"ס</b>: ראה זהר רע\"מ פינחס רנז, א."],["4707","41","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["4708","42","<b>דיבור למעלה . . לדיבור למטה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310026\" data-slug=\"tanya\" data-id=\"3401310026\">תניא פכ\"א</a>. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה במשנה כו' ר' נהוראי אומר פ\"א."],["4709","43","<b>את השמים . . אני מלא</b>: ירמי' כג, כד."],["4710","44","<b>לית אתר פנוי מני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["4711","*45","<b>שהדיבור באדם ג\"כ אינו נפרד</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה כי תבואו וכו' ושבתה הארץ רפ\"ד ושם מציין: ”בד\"ה וככה תאכלו\" — תרל\"ז פע\"ט. ראה גם לקמן בהנחה שם על יד הערה 65. סה\"מ תר\"ם ח\"א ע' שטו וע' תמח."],["4712","45","<b>אבידת אביו ואבידת רבו</b>: ראה ב\"מ לג, א במשנה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380098\" data-slug=\"likkutei-torah\" data-id=\"4001380098\">לקו\"ת ויקרא ו, רע\"א</a>. סה\"מ תר\"ם ח\"ב ע' תרה. וש\"נ."]]],[2001910459,"מעצמיות מוח האב<sup data-n=\"4713\">46</sup> וה\"ז השפעה פנימיות, והשפעת הרב לתלמיד הוא הארה חיצוניות דלא קאים איניש אדעתי' דרבי'<sup data-n=\"4714\">47</sup> עד ארבעים שנין וכמ\"ש ולא נתן ה' לכם לב לדעת ועינים לראות עד היום הזה<sup data-n=\"4715\">48</sup> לסוף ארבעים שנין וההתקשרות שעד מ' שנה הוא מהארה חיצוניות, ובמ\"א מבואר שהוא רק חלק עשיריות<sup data-n=\"4716\">49</sup> וגם זה רק במספר ולא באיכות וכמות וכמו חכ' ודיבור שאינם בערך זל\"ז ובמספר הם נחשבים בשוה, שהרי בהארה חיצוניות מתקשר כ\"כ ע\"י הדיבור וא\"כ מובן שהדיבור אינו נפרד מהאדם, וכמו\"כ יובן למעלה שהדיבור אינו נפרד מאחר שבאדם ג\"כ אינו נפרד והלא הבריאה היא רק בחיק הבורא ואלמלא מתכנשין<sup data-n=\"4717\">50</sup> כל באי א\"י<sup data-n=\"4718\">51</sup> לברוא אפי' יתוש א', ומאחר שכ\"ה בנברא כמו\"כ יובן בהבורא וזה אינו שייך לומר שבאדם אינו נפרד ולמעלה ח\"ו כי זה לא יתכן אלא שהדיבור אינו נפרד וא\"כ גם הנבראים שנתהווה מהדיבור אינם נפרדים, וזהו תי' אחד שהח\"ד מורים על ז' רקיעים וארץ וד' רוחות העולם ומ\"מ הם בטלים לא\"ס אלופו ש\"ע, וכדי שיהי' מציאות הדיבור שיתהווה בחי' ז' רקיעים וארץ וד' רוחות העולם זהו שאמר ה' אחד יו\"ד צמצום ה' המשכה (ונ\"ל שצ\"ל התפשטות) ו' המשכה<sup data-n=\"4719\">52</sup> כו' וזהו מקור הדיבור שיהי' מקור לעולמות, ה' אלקינו הו\"ע יחוד הנשמות דישראל עלו במח'<sup data-n=\"4720\">53</sup> והו\"ע מח' ויובלא לא אתפרש לעלמין<sup data-n=\"4721\">54</sup> כמו שהבן נמשך מעצמיות מוח האב כמו\"כ כתי' בנים אתם לה' אלקיכם<sup data-n=\"4722\">55</sup> ונמשכים ממח' העצמיות, דכמו שיש מח' שבדיבור ודיבור שבמח' כמו\"כ יש דיבור שבמח' ועצם המח', דדיבור שבמח' הגם שהוא מח' מ\"מ שייך לדיבור אבל עצם המח' הוא מה שאינו שייך לדיבור ואף אם לא הי' מציאות הדיבור שייך מח' זו, ושרש הישראל הוא מעצמיות המח', לכן התקשרות ישראל בהקב\"ה ע\"י התורה וכמאמר תלת דרגין<sup data-n=\"4723\">56</sup> מתקשרין דא בדא ישראל מתקשראין באורייתא ואורייתא בקוב\"ה, ור\"ת י'ש'ר'א'ל'<sup data-n=\"4724\">57</sup> י'ש ש'שים ר'יבוא א'ותיות ל'תורה.",[["4713","46","<b>הבן . . מוח האב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540177\" data-slug=\"torat-chaim\" data-id=\"2300540177\">תו\"ח בא ח\"א קטז, סע\"ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111005\" data-slug=\"likkutei-sichot\" data-id=\"1300111005\">לקו\"ש שמות כרך יא ע' 5</a> הערה 48."],["4714","47","<b>דלא קאים איניש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540728\" data-slug=\"torat-chaim\" data-id=\"2300540728\">תו\"ח בשלח ח\"א ריז, ג</a> הערה 418. המשך וככה תרל\"ז ספל\"ה. סה\"מ תרנ\"ב ע' צה. תרנ\"ז ס\"ע מט ואילך."],["4715","48","<b>ולא נתן . . היום הזה</b>: תבוא כט, ג [בדילוג]."],["4716","49","<b>שהוא רק חלק עשיריות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370313\" data-slug=\"torah-or\" data-id=\"3901370313\">תו\"א יתרו ע, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370319\" data-slug=\"torah-or\" data-id=\"3901370319\">עא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381100\" data-slug=\"likkutei-torah\" data-id=\"4001381100\">לקו\"ת ברכה צג, ב</a>. סה\"מ תרל\"ח ע' תפח. וש\"נ. תר\"ם ח\"א ע' קכו. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ובהערה 100."],["4717","50","<b>ואלמלא מתכנשין</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. אוה\"ת בראשית כרך ו ע' 2040. המשך מים רבים תרל\"ו פכ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261455\" data-slug=\"likkutei-sichot\" data-id=\"1300261455\">לקו\"ש משפטים כרך כו ע' 366</a>."],["4718","51","<b>באי א\"י</b>: אוצ\"ל: באי עולם א\"י."],["4719","52","<b>ה' . . יו\"ד צמצום . . ו' המשכה</b>: ראה אגה\"ת פ\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתעז ואילך. סה\"מ תרל\"ח ע' קו. וש\"נ."],["4720","53","<b>דישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">לקו\"ת שה\"ש יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">יט, ב</a>. (לעיל בחלק המאמרים) מאמר ד\"ה אז ישיר פ\"ה (ד\"ה ואמנם). לקמן הנחה ד\"ה אז ישיר על יד הערה 79. הנחה ד\"ה זכור ע' תכב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540558\" data-slug=\"torat-chaim\" data-id=\"2300540558\">תו\"ח שמות ח\"א לב, ב</a> ובהערה 248. סה\"מ תר\"ם ח\"א ע' שטז. וש\"נ."],["4721","54","<b>מח' ויובלא . . לעלמין</b>: ראה זהר ח\"ש קכג, א."],["4722","55","<b>בנים אתם לה' אלקיכם</b>: פ' ראה יד, א."],["4723","56","<b>תלת דרגין</b>: ראה זהר אחרי עג, א."],["4724","57","<b>ור\"ת י'ש'ר'א'ל'</b>: ראה מגלה עמוקות אופן קפו. סידור מהרי\"ק שער חג המצות ע' סה. פני יהושע קדושין ל, א ד\"ה ת\"ר."]]],[2001910460,"<b>וביאור</b> ענין ישראל עלו במח' הנה כתי' בנים אתם לה' אלקיכם פי' ה' אלקיכם ז\"א ומל'<sup data-n=\"4725\">58</sup> וכידוע דלידת הנשמות הוא מזיווג גופני<sup data-n=\"4726\">59</sup> דזו\"נ אך אי' בזהר זכה יתיר יהבין לי' נשמתא מסט' דאו\"א<sup data-n=\"4727\">60</sup> ומבחי' זו נמשך רק מקיף דחי' ופנימיות דנשמה אבל כדי שיהי' נשמה שיחי' את הגוף זהו צ\"ל ע\"י זיווג זו\"נ, וצ\"ל שקאי על נשמות הגבוהות אך לפמ\"ש רבינו ז\"ל בסש\"ב שאפי' נפש דמל' דעשי'<sup data-n=\"4728\">61</sup> וכו' בתוכו מלובש חכ' דאצילות שבו שורה אוא\"ס א\"כ כל נשמה שרשה מבחי' מח' עלו במח' כו', וזהו מ\"ש העמוסי' מני בטן<sup data-n=\"4729\">62</sup> דכמו שיש עבור ולידה בגשמיות כמו\"כ יש עיבור ולידה ברוחניות ולידת הנשמות הוא בשביעי ש\"פ<sup data-n=\"4730\">63</sup>, וענין עיבור הנשמות הוא דהנה ארז\"ל נר דלוק על ראשו<sup data-n=\"4731\">64</sup> ומלמדין אותו כל התורה כולה וא\"ז בגשמיות, אך ענין נר דלוק על ראשו הוא בחי' נר ה' נשמת אדם<sup data-n=\"4733\">66</sup>, וענין ש' ה' דנר זה י\"ה הוא תושב\"כ ותושבע\"פ ו\"ה הו\"ע בחי' מצות<sup data-n=\"4734\">67</sup>, ומלמדין אותו כל התורה כולה שנותנין לו כח<sup data-n=\"4732\">65</sup> לקבל ע\"ע עומ\"ש ועומ\"צ וזהו העמוסי' ל' יום יום יעמס לנו<sup data-n=\"4735\">68</sup> וכן אבי העמיס עליכם<sup data-n=\"4736\">69</sup> ל' עול, ולפי' הזהר קאי רק על נשמות הגבוהות, אך לפי פי' רבינו ז\"ל קאי על כל הנשמות, וזהו\"ע ה' אלקינו, ומזה יבוא לבחי' ואהבת<sup data-n=\"4737\">70</sup> דלכאו' איך שייך ציווי על אהבה<sup data-n=\"4738\">71</sup> שהוא מדה שבלב ואם יש אהבה א\"צ ציווי ואם אין אהבה מה מועיל ציווי, אך הציווי אינו על האהבה כ\"א על ההתבוננות, דכמו שהבן נמשך ממוח האב כמו\"כ ישראל נמשכי' מעצמיות אלקות וכמ\"ש בנים אתם לה' אלקיכם, והנה אהבת הבן על<sup data-n=\"4739\">72</sup> האב הוא אהבה טבעית וכמו\"כ אהבת ישראל להקב\"ה וכמ\"ש בזהר כברא דרחים לי' בתר אבוהי ואימי' יתיר מגרמי' ונפשוה' ונשמתו<sup data-n=\"4740\">73</sup> רק שצריכים לעורר האהבה והוא ע\"י התבוננות וזהו שמע ישראל שמע הוא ל' השגה והבנה<sup data-n=\"4741\">74</sup>, ותבונה הוא בן ובת<sup data-n=\"4742\">75</sup> וכתי' אם",[["4725","58","<b>ה' אלקיכם ז\"א ומל'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 59."],["4726","59","<b>דלידת הנשמות . . גופני</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ח, דרוש ד. שער פני' וחי' ש\"מ, דרוש י."],["4727","60","<b>זכה יתיר . . מסט' דאו\"א</b>: זהר משפטים צד, ב."],["4728","61","<b>בסש\"ב שאפי' נפש דמל' דעשי'</b>: ראה שם פי\"ח."],["4729","62","<b>העמוסי' מני בטן</b>: ישעי' מו, ג."],["4730","63","<b>ולידת הנשמות הוא בשביעי ש\"פ</b>: ראה פע\"ח שער הלולב שכ\"ט, ספ\"ח. מאמרי אדה\"א ויקרא ח\"א ע' שפז. וש\"נ."],["4731","64","<b>נר דלוק על ראשו</b>: נדה ל, ב. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פ\"ב."],["4733","66","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["4734","67","<b>ו\"ה . . מצות</b>: בסה\"מ תש\"ד כאן ע' 153: ו' הם מצות וה' אחרונה תפלה."],["4732","65","<b>ומלמדין . . התורה כולה . . שנותנין לו כח</b>: נדה שם. ראה גם לעיל שם ובהערה 68."],["4735","68","<b>יום יום יעמס לנו</b>: תהלים סח, כ."],["4736","69","<b>אבי העמיס עליכם</b>: מלכים-א יב, יא. דברי הימים-ב י, יא."],["4737","70","<b>ואהבת</b>: ואתחנן ו, ה."],["4738","71","<b>ציווי על אהבה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 74."],["4739","72","<b>על</b>: כ\"ה בגוכתי\"ק."],["4740","73","<b>כברא דרחים . . ונפשוה' </b> [אוצ\"ל: ונפשי']<b> ונשמתו</b>: ראה זהר רע\"מ תצא רפא, סע\"א. לעיל שם ובהערה 75."],["4741","74","<b>שמע . . והבנה</b>: ראה זהר אד\"ר נשא קלח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380640\" data-slug=\"likkutei-torah\" data-id=\"4001380640\">לקו\"ת פינחס פ, א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."],["4742","75","<b>ותבונה הוא בן ובת</b>: ראה זהר (אד\"ז) האזינו רצ, ב. רצא, א. תניא פט\"ז ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380684\" data-slug=\"likkutei-torah\" data-id=\"4001380684\">לקו\"ת מסעי צ, א</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכג. פרשיות התורה ח\"א ע' לג. שעה\"י קי, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670517\" data-slug=\"torat-chaim\" data-id=\"2300670517\">תו\"ח בראשית כח, ד</a> ובהערה 26. ביאוה\"ז להצ\"צ בלק כרך א ע' תקכ ואילך."]]],[2001910461,"לבינה תקרא<sup data-n=\"4743\">76</sup> והו\"ע ההתבוננות ה' אלקינו הוא יחוד הנשמות וה' אחד הוא יחוד המלאכים איך שהם בטלים לאלקות.\n<b>אך</b> צ\"ל דמאחר דהנשמה גבהה מעלתה כ\"כ מהו\"ע העלי' שירדה כ\"כ, אך הענין דהנה אי' בזהר<sup data-n=\"4744\">77</sup> ע\"פ ויקח רומח בידו<sup data-n=\"4745\">78</sup> הם רמ\"ח תיבין דק\"ש<sup data-n=\"4746\">79</sup>, וכתי' אשר לקחתי מיד אמורי בחרבי ובקשתי ות\"א בצלותא ובעותא<sup data-n=\"4747\">80</sup>, והו\"ע חרב וקשת, וצ\"ל מה צריכים לחרב וקשת. והענין דמשנת\"ל שישראל עלו במח' היינו נפה\"א אבל נה\"ב שרשו מפני שור<sup data-n=\"4748\">81</sup> שבמרכבה ואפי' נפש השכליות שרשו מפני אדם<sup data-n=\"4749\">82</sup> ולכן תמיד יש מלחמה בין יצ\"ט ובין יצה\"ר, שטבע נפה\"א ליכלל ולהדבק לאלקות וטבע נה\"ב להימשך אחר תאוות זרות ורצונות זרות, אך ע\"י הבירור דנה\"ב מתעלה נפה\"א במעלה עליונה יותר, וזהו רוממות אל בגרונם<sup data-n=\"4750\">83</sup> וחרב פיפיות בידם שע\"י רוממות אל דק\"ש חרב פיפיות בידם שניתן כח לנפה\"א ומתיש כח נה\"ב שהוא חרב פיפיות, והעלי' היא שבאה לאשתאבא בגופא דמלכא<sup data-n=\"4751\">84</sup> ושרש הנשמה בחי' מח' שהוא רק לבוש וא\"כ ה\"ז עלי' גדולה, אך לפמ\"ש בזהר שהו\"ע מח' ויובלא לא אתפרש לעלמין ומה יוכל עוד מדריגה עליונה מזה. אך צ\"ל ע\"פ מ\"ש בזהר ע\"פ בי נשבעתי נאום ה'<sup data-n=\"4752\">85</sup>, בי מה שבתוכי, וכמו בית יעקב לכו ונלכה באור ה'<sup data-n=\"4753\">86</sup> פי' באור שבש' ה' כמו\"כ צ\"ל כאן ג\"כ דשרש הנשמה ממח' ואפי' בחי' מח' ויובלא כו' מ\"מ ה\"ז בכלל גרמוהי שאפי' כלי החכ' נק' גרמוהי אבל העלי' הוא בבחי' חיוהי<sup data-n=\"4754\">87</sup>, וזהו עתידים שיאמרו לפניהם קדוש<sup data-n=\"4755\">88</sup> כדרך שאומרי' לפני הקב\"ה, דקדוש הוא קדוש",[["4743","76","<b>אם לבינה תקרא</b>: משלי ב, ג. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600547\" data-slug=\"or-hatorah-hb\" data-id=\"8316600547\">אוה\"ת משלי כרך א ע' תקמז</a>."],["4744","77","<b>אי' בזהר . . רמ\"ח תיבין דק\"ש</b>: ראה זהר עקב רבע, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380869\" data-slug=\"likkutei-torah\" data-id=\"4001380869\">לקו\"ת תצא לח, א</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א ויקרא ח\"א ע' צא. וש\"נ. הערה בסה\"מ תש\"ד ס\"ע 83־ תרל\"ב ח\"א ע' נז."],["4745","78","<b>ויקח רומח בידו</b>: בלק כה, ז."],["4746","79","<b>רמ\"ח תיבין דק\"ש</b>: ראה תנחומא קדושים ו. שערי זהר לשם קסד, ד."],["4747","80","<b>אשר לקחתי . . בחרבי ובקשתי ות\"א בצלותא ובעותא</b>: ויחי מח, כב. ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 91."],["4748","81","<b>נה\"ב שרשו מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ."],["4749","82","<b>נפש השכליות שרשו מפני אדם</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 97."],["4750","83","<b>רוממות אל בגרונם</b>: תהלים קמט, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380860\" data-slug=\"likkutei-torah\" data-id=\"4001380860\">לקו\"ת תצא לה, ד</a>. סה\"מ תר\"ם ח\"א ע' קנג. ע' שנט ואילך."],["4751","84","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ."],["4752","85","<b>בי נשבעתי נאום ה'</b>: וירא כב, טז. ראה זהר אד\"ר נשא קל, א ובקול ברמה שם. סה\"מ תרל\"ו ח\"ב ע' רצט. המשך תער\"ב ח\"ב ע' תתקצג. ח\"ג ע' א'תלה. אוה\"ת שבהערה הבאה."],["4753","86","<b>בית יעקב . . באור ה'</b>: ישעי' ב, ה. ראה זהר שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370227\" data-slug=\"torah-or\" data-id=\"3901370227\">תו\"א שמות נ, ג</a>. אוה\"ת ישעי' כרך א' ע' קא. סה\"מ תרל\"ט ח\"ב ע' תנז. וש\"נ. דרושים שבהערה שלפנ\"ז."],["4754","87","<b>העלי' הוא בבחי' חיוהי</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">עב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380599\" data-slug=\"likkutei-torah\" data-id=\"4001380599\">לקו\"ת בלק ע, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">פ' ראה כז, א</a> ואילך. יוה\"כ ע, ג. סה\"מ תר\"ם ח\"ב ע' תקה ואילך."],["4755","88","<b>עתידים שיאמרו לפניהם קדוש</b>: ראה ב\"ב עה, ב. לקו\"ת בהעלותך־ נצבים־ יו\"כ שבהערה הבאה."]]],[2001910462,"וא\"ו, וצדיקים שיתעלו בבחי' קדש<sup data-n=\"4756\">89</sup> אנשי קדש תהיון לי<sup data-n=\"4757\">90</sup> לכן יאמרו לפניהם קדוש. ואח\"כ אומרים והיו הדברים האלה ואמרז\"ל בד\"ת<sup data-n=\"4758\">91</sup> הכתוב מדבר, שהתורה היא כלי להמשכה זו, דאורייתא מחכ' נפקת<sup data-n=\"4759\">92</sup> וחכ' הוא בחי' כח מ\"ה<sup data-n=\"4760\">93</sup> שהוא בחי' התדבקותא אל הכתר וכדאי' בתניא חכ' הוא אחד האמת שבו שורה אוא\"ס<sup data-n=\"4761\">94</sup>, ה\"ה הכלי לגילוי זה. אך כל האומר אין לי אלא תורה<sup data-n=\"4763\">96</sup> אפי' תורה אין לו כ\"א צ\"ל עיון תפלה ג\"כ וכמ\"ש גומל נפשו איש חסד<sup data-n=\"4764\">97</sup> שעיון תפלה הוא גמ\"ח, דתחילה צ\"ל העלאה וכמ\"ש אם ישים אליו לבו<sup data-n=\"4765\">98</sup> רוחו ונשמתו אליו יאסוף, ועיקר התפלה הוא ק\"ש<sup data-n=\"4766\">99</sup> [שהו\"ע מס\"נ<sup data-n=\"4767\">100</sup>] שהוא כולל שיעור קומה דסדר השתל' לכן יש בק\"ש רמ\"ח תיבין כנגד רמ\"ח אברים<sup data-n=\"4768\">101</sup> דמלכא<sup data-n=\"4769\">102</sup> והוא בחי' אדם אדמה לעליון<sup data-n=\"4770\">103</sup> לבחי' כי<sup data-n=\"4771\">104</sup> לא אדם הוא<sup data-n=\"4762\">95</sup>, לכן יש מעלה בתפלה שקודם התפלה אסור באכילה<sup data-n=\"4772\">105</sup> וכמ\"ש חדלו לכם מן האנשים אשר נשמה באפם<sup data-n=\"4773\">106</sup> משא\"כ קודם התורה<sup data-n=\"4774\">*107</sup>, דהנה אדם הוא א' דם<sup data-n=\"4775\">107</sup>",[["4756","89","<b>דקדוש הוא קדוש וא\"ו . . קדש</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">יו\"כ סט, ב</a> ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["4757","90","<b>אנשי קדש תהיון לי</b>: משפטים כב, ל [ושם: ואנשי]."],["4758","91","<b>והיו הדברים האלה ואמרז\"ל בד\"ת</b>: ואתחנן ו, ו. וכ\"ה בכ\"מ ומהם: סה\"מ תרכ\"ט ע' כד. ע' צט. ס\"ע רמז. ע' רעו. ע' רעט. ע' רצ. תרל\"ג ח\"א ע' קמב. תרצ\"ז ע' 263. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 113."],["4759","92","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4760","93","<b>וחכ' . . כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א. סה\"מ תר\"ם ח\"א ע' שז ובהערה 39. ע' שעו על יד הערה 66."],["4761","94","<b>וכדאי' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא</a> חכ' . . אוא\"ס</b>: ראה שם פל\"ה בהגהה."],["4763","96","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. סה\"מ תר\"ם ח\"ב ע' תפד ואילך. תש\"ח ע' 266 בהערה."],["4764","97","<b>גומל נפשו איש חסד</b>: משלי יא, יז. ראה רש\"י שבת קכז, ריש ע\"ב ד\"ה ה\"ג. ראה גם סה\"מ תרל\"ח ע' מב ואילך ובהנסמן שם."],["4765","98","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["4766","99","<b>ועיקר התפלה הוא ק\"ש</b>: ראה סידור שער התפלה יט, א. מאמרי אדה\"א דברים ח\"א ע' רנד. וש\"נ. ח\"ב ע' תלז וע' תקסד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221116\" data-slug=\"likkutei-sichot\" data-id=\"1300221116\">לקו\"ש אמור כרך כב ע' 116</a> הערה 18."],["4767","100","<b>ק\"ש . . מס\"נ</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310030\" data-slug=\"tanya\" data-id=\"3401310030\">תניא ספכ\"ה</a>."],["4768","101","<b>בק\"ש רמ\"ח . . רמ\"ח אברים</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ה. שער הכוונות שם דרוש ח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381215\" data-slug=\"likkutei-torah\" data-id=\"4001381215\">לקו\"ת שה\"ש כא, סע\"ג</a>."],["4769","102","<b>רמ\"ח אברים דמלכא</b>: נסמן לקמן הנחה ד\"ה אז ישיר משה הערה 77."],["4770","103","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ. סה\"מ תרל\"ח ע' שג. וש\"נ."],["4771","104","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["4762","95","<b>הוא</b>: תיבה זו איננה ברורה בצילום גוכתי\"ק."],["4772","105","<b>שקודם התפלה אסור באכילה</b>: ברכות י, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380108\" data-slug=\"likkutei-torah\" data-id=\"4001380108\">לקו\"ת צו ח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380606\" data-slug=\"likkutei-torah\" data-id=\"4001380606\">בלק עב, א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשנו. וש\"נ. שמות ח\"א ס\"ע קפב ואילך. וש\"נ. סה\"מ תרל\"ח ע' ריב. לקמן הנחה ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 20."],["4773","106","<b>חדלו לכם מן האנשים . . באפם</b>: ישעי' ב, כב [ושם: מן האדם . . באפו]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380639\" data-slug=\"likkutei-torah\" data-id=\"4001380639\">לקו\"ת פינחס עט, ד</a>. מאמרי אדה\"א ויקרא שם ע' תשנז. וש\"נ. הנחות תקע\"ז ע' טו. וש\"נ. אוה\"ת על מארז\"ל ע' יד. ע' יט. ע' כג. לקמן שם על יד הערה 22."],["4774","*107","<b>משא\"כ קודם התורה</b>: ראה שו\"ע אדה\"ז חאו\"ח הל' ת\"ת סקנ\"ה, ס\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשמז. לקמן שם על יד הערה 19."],["4775","107","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670107\" data-slug=\"torat-chaim\" data-id=\"2300670107\">אדם הוא א</a>' דם</b>: ראה מבו\"ש ש\"ה ח\"ב, פ\"ה. של\"ה (בהקדמת ב\"י ב\"ד) כא, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תמב. תו\"ח בראשית לה, א ובהנסמן במ\"מ לשם. אוה\"ת (יהל אור) תהלים ריש ע' שנח."]]],[2001910463,"וקודם הוא רק דם והא' דהיינו אינו<sup data-n=\"4776\">108</sup> מאיר בגוף רק נשמה באפם אבל ע\"י התפלה בהתבוננות ה' אלקינו שהו\"ע יחוד הנשמות ובחי' ה' אחד שהו\"ע יחוד המלאכים איך שהח' והד' שהם ז' רקיעים וארץ וד' רוחות העולם בטלים לאלף א\"ס אלופו ש\"ע ואז האלף מאיר בגוף האדם ג\"כ, וזהו והיו הדברים האלה בד\"ת הכתוב מדבר שהוא הכלי להמשכה זו, וזהו פרשה ראשונה דק\"ש.\n<b>ועתה</b> צ\"ל פ\"ש דק\"ש דכתי' בה ואספת דגנך<sup data-n=\"4777\">109</sup> וצ\"ל מהו\"ע ואספת דגנך מאחר שכבר נא' ואכלת ושבעת<sup data-n=\"4778\">110</sup>, אך זה מדרכי המוסר דהנה ארז\"ל עשה תורתך קבע<sup data-n=\"4779\">111</sup> ומלאכתך עראי<sup data-n=\"4780\">112</sup> ואין הכוונה שיהי' הקביעות בתורה והמלאכה עראי שהרי יש בע\"ס<sup data-n=\"4781\">113</sup> שהם טרודים במלאכתם, אך הכוונה שיהי' העיקר בשביל התורה, וזה נק' קביעות כמו קביעות האדם בביתו אף שהוא נוסע בכ\"ע ורוב העיתים אינו בבית מ\"מ קביעותו הוא בביתו, וכמו\"כ כאן הכוונה שכל עסקו במו\"מ יהי' שיפרנס אשתו ובו\"ב ויעסוק בתורה<sup data-n=\"4782\">114</sup>, וכשיחשוב כוונה זו לא די שאינו נפרד ה\"ה מקושר, דכשאינו מחשב לא די שאינו מקושר אלא הוא נפרד אבל כשמכוון כנ\"ל לא די שאינו נפרד אלא שהוא מקושר וזהו ואספת דגנך שהוא דבר גשמי ואספת<sup data-n=\"4783\">115</sup> לאלקות, וזהו שניתוסף בפ\"ש. ובפ\"ש נא' אני ה' אלקיכם<sup data-n=\"4784\">116</sup> אשר הוצאתי אתכם מארץ מצרים, וצ\"ל מה שייך יצ\"מ לק\"ש. והענין דלא יאמר האדם איך יבוא לבחי' זאת והלא ידע אינש בנפשו שיש בו איזה חטא כו' ואי' בזהר משל ע\"ז מאן דנפח<sup data-n=\"4785\">117</sup> צריך שלא יהי' דבר המפסיק אבל ידע אינש בנפשו שיש עוונות המפסיקים כמ\"ש כי עוונותיכם המבדילים ביניכם ובין אלקיכם<sup data-n=\"4786\">118</sup> וא\"כ יאמר נואש, לז\"א אני ה' אלקיכם אשר הוצאתי אתכם מאמ\"צ שהיו מושקעים במ\"ט דהיפך<sup data-n=\"4787\">119</sup> ומ\"מ אח\"כ בנו\"ן יום קבלו תורה<sup data-n=\"4788\">120</sup>, וכתי' ויחן ישראל נגד ההר כולם כאיש אחד<sup data-n=\"4789\">121</sup>, ובמ\"ת א\"ל אנכי ה'",[["4776","108","<b>דהיינו אינו</b>: אוצ\"ל: דהיינו שנשמה אינו."],["4777","109","<b>ואספת דגגך</b>: עקב יא, יד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 127."],["4778","110","<b>ואכלת ושבעת</b>: שם שם, טו."],["4779","111","<b>עשה תורתך קבע</b>: רמב\"ם הל' ת\"ת פ\"ג, ה\"ז. ראה אבות פ\"א, מט\"ו. ברכות לה, ב. שו\"ע אדה\"ז הל' מו\"מ סקנ\"ו, ס\"א. הל' ת\"ת פ\"ג, ה\"ב ואילך."],["4780","112","<b>קבע . . עראי</b>: ראה לעיל הערה 109. לקמן הנחה ד\"ה כי תשא על יד הערה 32. סה\"מ תרכ\"ו ס\"ע קסח ואילך. ע' קעא. תרל\"ט ח\"ב ע' תסו. וש\"נ. וראה ג\"כ שע\"ת קכח, ג."],["4781","113","<b>בע\"ס</b>: בעלי עסקים. תיבה זו איננה ברורה בצילום גוכתי\"ק."],["4782","114","<b>העיקר בשביל . . ויעסוק בתורה</b>: ראה שו\"ע אדה\"ז הל' מו\"מ סקנ\"ו, ס\"ב. וש\"נ."],["4783","115","<b>ואספת</b>: תיבה זו איננה ברורה בצילום גוכתי\"ק."],["4784","116","<b>אני ה' אלקיכם</b>: שלח טו, מא."],["4785","117","<b>ואי' בזהר . . מאן דנפח</b>: באוה\"ת בראשית כאן ע' תתרכג מציין לאגה\"ת פ\"ה."],["4786","118","<b>כי עוונותיכם . . אלקיכם</b>: ישעי' נט, ב [ושם: כי אם . . היו מבדילים . . לבין]. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה פ\"ב."],["4787","119","<b>מושקעים במ\"ט דהיפך</b>: ראה ז\"ח יתרו לא, א. סה\"מ תר\"ם ח\"א ע' קמב. וש\"נ."],["4788","120","<b>בנו\"ן יום קבלו תורה</b>: ראה שו\"ע אדה\"ז חאו\"ח סדר תפלת חה\"ש סתצ\"ד, ס\"א. סה\"מ תר\"ם ח\"א ע' רז. וש\"נ."],["4789","121","<b>ויחן ישראל . . כאיש אחד</b>: ראה יתרו יט, ב (בדילוג] וברש\"י שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211104\" data-slug=\"likkutei-sichot\" data-id=\"1300211104\">לקו\"ש יתרו כרך כא ע' 104</a>."]]],[2001910464,"אלקיכם<sup data-n=\"4790\">122</sup> שנמשך מבחי' אנכי מי שאנכי<sup data-n=\"4791\">123</sup>, והוא מפני שהוצאתם מאמ\"צ, וכמו\"כ בכל דור ודור חייב אדם לראות א\"ע כאילו הוא יצא ממצרים<sup data-n=\"4792\">124</sup>, ולאו דוקא בכ\"ד אלא בכ\"י<sup data-n=\"4793\">125</sup> ובכ\"ע ובכ\"ר, דמצרים הם המצרים והגבולים<sup data-n=\"4794\">126</sup> ומאחר שהוציא מאמ\"צ כמו\"כ יוציא כו', זהו\"ע ג\"פ דק\"ש.\n<b>והנה</b> כ\"ז הי' די בימי משה אבל אח\"כ שנתמעטו הלבבות תקנו חז\"ל ברכת ק\"ש<sup data-n=\"4795\">127</sup> שתים לפני' ואחת לאחרי', וכמו שתקנו פסוד\"ז<sup data-n=\"4796\">128</sup> מפני שנתמעטו הלבבות כמו\"כ תקנו ברכת ק\"ש, והנה ברכה א' היא ביאור ה' אחד שהו\"ע ביטול [המלאכים]<sup data-n=\"4797\">129</sup> העולמות איך שרפים אומרים קדוש ואופנים אומרים ברוך<sup data-n=\"4798\">130</sup>, וברכה שני' הוא ביאור ה' אלקינו אהבת עולם אהבתנו (בפ\"א<sup data-n=\"4800\">132</sup> אהבתיך<sup data-n=\"4799\">131</sup>) ואח\"כ ברכה א' שאחרי' אמת ויציב ויש כאן ט\"ו ווי\"ן<sup data-n=\"4801\">133</sup> והו\"ע בווין תתקטר<sup data-n=\"4802\">134</sup> ל'<sup data-n=\"4803\">135</sup> קשר וכמ\"ש עשה ווין לעמודים<sup data-n=\"4804\">136</sup> פי' אונקליות<sup data-n=\"4805\">137</sup> ורש\"י פי' יתדות הם שמושקעים בארץ<sup data-n=\"4806\">138</sup> וכמ\"ש אהל בל יצען<sup data-n=\"4807\">139</sup> בל יסע יתדותיו לנצח, שהיו מחברים האהל עם החצר<sup data-n=\"4808\">140</sup>",[["4790","122","<b>אנכי ה' אלקיכם</b>: יתרו כ, ב [ושם: אלקיך]."],["4791","123","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["4792","124","<b>בכל דור . . יצא ממצרים</b>: פסחים קטז, ב [במשנה]."],["4793","125","<b>אלא בכ\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ\"ז</a>. הגדה עם לקוטי טעמים (קה\"ת תשמ\"ו ואילך) ע' תריח בשולי הגליון."],["4794","126","<b>דמצרים הם המצרים והגבולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["4795","127","<b>אח\"כ . . תקנו חז\"ל ברכת ק\"ש</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380856\" data-slug=\"likkutei-torah\" data-id=\"4001380856\">לקו\"ת תצא לד, ד</a>: אכנה\"ג. ראה ברכות יא, סע\"א (במשנה). שו\"ע אדה\"ז הל' ק\"ש רסנ\"ט. סה\"מ תרל\"ח ע' צא. וש\"נ."],["4796","128","<b>שתקנו פסוד\"ז</b>: ראה שו\"ע אדה\"ז חאו\"ח סנ\"א, ס\"א־ ס\"ב. תו\"ח פקודי ח\"ב ע' תמה [ושם: אנשי כנה\"ג]. וש\"נ. סה\"מ תרל\"ח ע' תנא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380888\" data-slug=\"likkutei-torah\" data-id=\"4001380888\">לקו\"ת תבוא מב, ד</a>."],["4797","129","<b></b> [המלאכים]<b></b>: אולי הכוונה שתיבה זו מיותרת."],["4798","130","<b>שרפים . . קדוש ואופנים . . ברוך</b>: ישעי' ו, ב-ג. יחזקאל ג, יב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה שיר המעלות ממעמקים ובהערה 63."],["4800","132","<b>בפ\"א</b>: [ בפעם א' אמר כ\"ק אדמו\"ר מהר\"ש] ראה גם לקמן הנחה ד\"ה קדש ישראל לה' על יד הערה 31. 43. 79. 88. 147. סה\"מ תרל\"ח ע' תכז ובהערה 104. תר\"ם ח\"א ע' רעט ובהערה 80. ח\"ב ע' תשיז. וש\"נ."],["4799","131","<b>אהבת עולם . . אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — ראה ש\"א ב, א ובהערה 12]."],["4801","133","<b>אמת ויציב . . ט\"ו ווי\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> הערה 14. (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 75. ולקמן (בחלק ההנחות) בהנחה שם על יד הערה 68."],["4802","134","<b>בווין תתקטר</b>: זמירות לליל שבת — אזמר בשבחין."],["4803","135","<b>ל'</b>: אולי כ\"ה בגוכתי\"ק."],["4804","136","<b>עשה ווין לעמודים</b>: פקודי לח, כח [ושם: ווים]."],["4805","137","<b>ווין . . אונקליות</b>: רש\"י תרומה כו, לב [בכמה דפוסים אינו ד\"ה בפ\"ע, ונמצא זה לעיל בסיום פסוק לא]. כז, י."],["4806","138","<b>ורש\"י פי' יתדות . . בארץ</b>: ראה שם תרומה כז, יט."],["4807","139","<b>אהל בל יצען</b>: ישעי' לג, כ (הובא ברש\"י שם)."],["4808","140","<b>מחברים האהל עם החצר</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 163."]]],[2001910465,"והוא בחי' כי כל בשמים וארץ בחי' יסוד<sup data-n=\"4809\">141</sup>, ומספר ט\"ו הוא מספר י\"ה שהוא בחי' חו\"ב<sup data-n=\"4810\">142</sup> תרדל\"מ<sup data-n=\"4811\">143</sup> הגם שהם יש ואין<sup data-n=\"4812\">144</sup> מ\"מ מאחר שהיש בטל להאין לכן הם תרדל\"מ וצריכים בו\"ה<sup data-n=\"4813\">145</sup> ג\"כ ואז ה' שלם<sup data-n=\"4814\">146</sup> כו', וזהו ה' אלקינו ה' אחד פירש\"י מה שעכשיו הוא הוי' אלקינו יהי' לע\"ל ה' אחד דהנה אי' בלקו\"ת דזה לא מצינו רק בשם אלקים שנא' בו אלקינו<sup data-n=\"4815\">147</sup> והוא מפני שהוא מדת הצמצום<sup data-n=\"4816\">148</sup> אך ע\"י ה' אלקינו דעכשיו יומשך לע\"ל בחי' ה' אחד וכמ\"ש לעבדו שכם אחד<sup data-n=\"4817\">149</sup> שנא' שם ג\"כ אחד וזהו עיקר האחד, והוא נעשה ע\"י הבירורים דעכשיו, וזהו עדיין הדבר נוה\"ג בנו שנוהג בנו עדיין הבירורים דה' אלקינו והוא בנ\"ו לבד שאינו עדיין בחי' לעבדו שכם אחד, וזהו אותו דבר שצוויתנו עדיין נוהג בנו וע\"י ה' אלקינו דעכשיו יהי' לע\"ל בחי' לעבדו שכם אח\"ד כו'.",[["4809","141","<b>כי כל . . יסוד</b>: דברי הימים-א כט, יא. ראה גם לעיל שם ובהערה 164."],["4810","142","<b>י\"ה . . חו\"ב</b>: ראה זהר אד\"ז האזינו רצ, ב. אגה\"ת פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שסו וע' תרנו."],["4811","143","<b>חו\"ב תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["4812","144","<b>חו\"ב . . יש ואין</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["4813","145","<b>וצריכים בו\"ה</b>: אוצ\"ל: וצריכים להמשיך י\"ה בו\"ה."],["4814","146","<b>ה' שלם</b>: ראה רש\"י ס\"פ בשלח."],["4815","147","<b>בלקו\"ת . . בשם אלקים . . אלקינו</b>: נסמן (לעיל בחלק המאמרים) בהמאמר כאן בהערה 85."],["4816","148","<b>אלקים . . הצמצום</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א פ\"ב. שער היחוה\"א רפ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."],["4817","149","<b>לעבדו שכם אחד</b>: צפני' ג, ט."]]],[2001910466,"<h3>קדש ישראל לה'</h3>\n<b>ש\"פ שמות תאמ\"ר לפ\"ק\n(נא' לע\"ע)</b>\n<b>קדש</b> ישראל לה'<sup data-n=\"4818\">1</sup> ראשית תבואתה<sup data-n=\"4819\">2</sup>, והנה תבואתה הוא בה' לסוף והניקוד בחולם על הת', ותחלה צ\"ל דמשמע דמפני מה הם ראשית תבואתה מפני שקדש ישראל לה', וצ\"ל מה שייכות זל\"ז. ועוד צ\"ל והלא הניקוד הוא בחולם והי' צ\"ל בו' וכתי' בה', וצ\"ל מהו הרמז בזה. והענין דהנה כתי' כה אמר ה' צבאות בוראך יעקב יצרך ישראל<sup data-n=\"4820\">3</sup> אמר הקב\"ה לעולמו<sup data-n=\"4821\">4</sup> עולמי עולמי מי בראך יעקב בראך ישראל יצרך",[["4818","1","<b>קדש ישראל לה'</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["4819","2","<b>קדש ישראל לה' ראשית תבואתה</b>: ירמי' ב, ג. ראה גם תנחומא — באבער — בראשית י ובהערה נה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010110\" data-slug=\"or-hatorah-hb\" data-id=\"8159010110\">אוה\"ת פינחס ע' א'ריב</a>. לקמן הנחה ד\"ה את חג המצות תשמור בתחילתו. לעיל (בחלק המאמרים) בהמאמר כאן הערה 2."],["4820","3","<b>כה . . צבאות . . יצרך ישראל</b>: ישעי' מג, א [בהוספת תיבת צבאות. ושם: ויצרך]."],["4821","4","<b>אמר הקב\"ה לעולמו</b>: ראה יל\"ש ישעי' שם [רמז תנג]. ויק\"ר פל\"ו, ד."]]],[2001910467,"שנא' בוראך יעקב יצרך ישראל, וצ\"ל אומרו עולמי עולמי מי בראך והלא הבריאה היא יש מאין דבר מלא דבר<sup data-n=\"4822\">5</sup> ומה שייך לומר מי בראך.\n<b>אך</b> הענין הוא דהנה כתי' סוף דבר הכל נשמע את אלקים ירא ואת מצותיו שמור כי זה כל האדם<sup data-n=\"4823\">6</sup>, שתכלית מכוון בריאת האדם הוא כדי שימשיך בחי' זה, וצ\"ל תחילה אלקים ירא היינו קבעומ\"ש ואת מצוותיו שמור קבעו\"מ, וענין זה הוא גילוי כמ\"ש זה אלי ואנוהו<sup data-n=\"4824\">7</sup> שכל א' מראה באצבע<sup data-n=\"4825\">8</sup> זה אלי, ורש\"י פי' שם ראתה שפחה על הים<sup data-n=\"4826\">9</sup> מה שלא ראה יחזקאל בן בוזי הכהן<sup data-n=\"4827\">10</sup>, וכן על לע\"ל כתי' והי' ביום ההוא יהי' אלקינו זה כו' זה ה' קוינו לו<sup data-n=\"4828\">11</sup>, ולע\"ל נא' ב\"פ זה<sup data-n=\"4829\">12</sup> ועכשיו רק פ\"א, דעיקר הגילוי יהי' לע\"ל דשם נעשה לפניך<sup data-n=\"4830\">13</sup> כמצות רצונך, הגם דהתחלת עבודה הי' מאדה\"ר וכמ\"ש ויניחהו בג\"ע לעבדו ולשמרו<sup data-n=\"4831\">14</sup> לעבדו רמ\"ח מ\"ע ולשמרו שס\"ה מל\"ת<sup data-n=\"4832\">15</sup>, אך הנה אדם ר\"ת אדם דוד משיח<sup data-n=\"4833\">16</sup>, דאדה\"ר אח\"כ בסיבת החטא אף שלא הי' במקרה<sup data-n=\"4834\">17</sup> מ\"מ הרי ויגרש את האדם<sup data-n=\"4835\">18</sup>, ואף בימי שלמה דקיימא סיהרא באשלמותא<sup data-n=\"4836\">19</sup> מ\"מ לא הי' שלימות עדיין וכמשי\"ת, ובימי משיח אז יהי' כמצות רצונך, וזהו שלע\"ל יהי' ב\"פ זה דבמ\"ת הי' לוחות הראשונות ולוחות האחרונות<sup data-n=\"4837\">20</sup> ואמרז\"ל אלמלי לא נשתברו הלוחות<sup data-n=\"4838\">21</sup> הי' חירות מן היצה\"ר<sup data-n=\"4839\">22</sup> דחרות על הלוחות<sup data-n=\"4840\">23</sup> כתי' אך ע\"י חטא העגל נשתברו הלוחות ונתנו לוחות שניות אף שנתוסף בהם",[["4822","5","<b>דבר מלא דבר</b>: אולי צ\"ל: דבר לא מדבר — ראה סה\"מ תרל\"ח ע' שעא. תרל\"ט ח\"ב ע' שסט. תר\"ם ח\"ב ע' תקלג ובהנסמן בהנ\"ל."],["4823","6","<b>סוף דבר . . אלקים . . שמור . . כל האדם</b>: קהלת יב, יג [ושם: האלקים]."],["4824","7","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["4825","8","<b>שכל א' מראה באצבע</b>: ראה שמו\"ר פכ\"ג, טו."],["4826","9","<b>ורש\"י . . ראתה שפחה על הים</b>: ממכילתא בשלח טו, ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך."],["4827","10","<b>יחזקאל בן בוזי הכהן</b>: ברש\"י שם: נביאים. ראה גם לעיל (בחלק המאמרים) בהמאמר כאן. מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 242."],["4828","11","<b>והי' . . יהי' . . קוינו לו</b>: ישעי' כה, ט [ושם: ואמר . . הנה]."],["4829","12","<b>ב\"פ זה</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן הערה 10."],["4830","13","<b>דשם נעשה לפניך</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן. וש\"נ."],["4831","14","<b>ויניחהו בג\"ע לעבדו ולשמרו</b>: בראשית ב, טו [ושם: לעבדה ולשמרה — ראה גם סה\"מ תר\"ם ח\"א ע' שצט]."],["4832","15","<b>לעבדו רמ\"ח . . שס\"ה מל\"ת</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["4833","16","<b>אדם ר\"ת אדם דוד משיח</b>: ראה רקאנטי בראשית א, כו. ספר הגלגולים פ\"א. פס\"ב בשם ספר הקנה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540507\" data-slug=\"torat-chaim\" data-id=\"2300540507\">תו\"ח שמות ח\"א מז, ב</a> הערה 157."],["4834","17","<b>החטא אף שלא הי' במקרה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680307\" data-slug=\"torat-chaim\" data-id=\"2300680307\">תו\"ח תולדות קנד, א</a> ואילך ובהערה 20. סה\"מ תר\"ם ח\"א ע' רס ואילך וע' תה. תרס\"ג ח\"ב כאן ע' קיב. סה\"מ מלוקט ה' ע' קנד ואילך ובהנסמן שם."],["4835","18","<b>ויגרש את האדם</b>: בראשית ג, כד."],["4836","19","<b>בימי שלמה דקיימא סיהרא באשלמותא</b>: ראה זהר ויצא קנ, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפט."],["4837","20","<b>ולוחות האחרונות</b>: ראה בסמוך בפנים."],["4838","21","<b>אלמלי לא נשתברו הלוחות</b>: ע\"פ ערובין נד, א."],["4839","22","<b>חירות מן היצה\"ר</b>: ראה גם עקידה בחוקותי שער ע בשם רז\"ל. אור החיים נשא ה, טו."],["4840","23","<b>דחרות על הלוחות</b>: תשא לב, טז."]]],[2001910468,"הרבה מדרש הלכות ואגדות<sup data-n=\"4841\">24</sup> כו', וכמ\"ש והוא יגיד לך תעלומות חכ' ככפלים לתושי'<sup data-n=\"4842\">25</sup>, אך הרי באמת אין חוטא נשכר אלא הוא מפני ריבוי הבירורים שצריכים לברר, והוא ע\"ד מ\"ש כי אתה נרי ה' וה' יגיה חשכי<sup data-n=\"4843\">26</sup> פי' שכדי שיאיר בחי' נר ה' נשמת אדם<sup data-n=\"4844\">27</sup> הוא ע\"י שם ה' דסדר השתל' אך שיגי' גם החשך נמשך מלמעלה יותר וכמו במרתף אינו מאיר אור הנר וצריכים אבוקה להאיר וכמו\"כ כדי שיגיה גם החשך דנה\"ב נמשך ה' דלעילא כדי שיהי' אורח צדיקים כאור נוגה<sup data-n=\"4845\">28</sup> הולך ואור, וכמו\"כ יובן בענין לוחות הראשונות<sup data-n=\"4846\">29</sup> שניתוסף בהם הרבה הוא מפני הבירורים והוא נמשך מבחי' תעלומות חכ'<sup data-n=\"4847\">30</sup>, ככפלי' לתושי' (בפ\"א<sup data-n=\"4848\">31</sup> דמ\"ש ככפלים לתושי' הוא נתינת טעם דתושי' הוא תורה<sup data-n=\"4849\">32</sup> שמתשת כח הנה\"ב ובלוחות שניות הם ככפלי' לתושי' לכן נמשכים מבחי' תעלומות חכ') ואז יוכל להתברר גם חטא העגל כמארז\"ל בראתי יצה\"ר בראתי תורה תבלין<sup data-n=\"4850\">33</sup>, דאפי' אם אבן הוא נמוח<sup data-n=\"4851\">34</sup> וכמו שיורדים<sup data-n=\"4852\">35</sup> על האבן נימוח אף שהמים הם רכים<sup data-n=\"4853\">36</sup>, וזהו שלע\"ל נא' ב\"פ זה דקרי\"ס שהיא הכנה למ\"ת<sup data-n=\"4854\">37</sup> והיינו להלוחות הראשונות ולא ללוחות השניות, אף שבאמת הי' זה הכנה גם על הלוחות השניות<sup data-n=\"4855\">38</sup> אך ה\"ז ע\"ד שהידיעה אינה מכרחת הבחירה<sup data-n=\"4856\">39</sup>, לכן נא' פ\"א זה, אבל לע\"ל נא' ב\"פ זה שהוא בחי' ככפלים לתושי' לכן נא' ב\"פ זה.\n<b>והנה</b> משה הוא הממשיך בחי' זה למטה דארז\"ל שכל הנביאים נתנבאו בכה משה נתנבא בזה<sup data-n=\"4857\">40</sup>, ואפי' ב\"פ זה דלע\"ל ג\"כ יומשך ע\"י משה שהוא גואל ראשון",[["4841","24","<b>מדרש הלכות ואגדות</b>: ראה שמו\"ר פמ\"ו, א. פמ\"ז, ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161197\" data-slug=\"likkutei-sichot\" data-id=\"1300161197\">לקו\"ש יתרו כרך טז ע' 197</a> הערה 42. ראה גם בענין לוחות ראשונות ואחרונות אוה\"ת תשא ס\"ע ב'נו ואילך. סה\"מ תרל\"ב ח\"א ע' פב ואילך. וש\"נ. ע' רמד ואילך."],["4842","25","<b>והוא יגיד . . ככפלים לתושי'</b>: איוב יא, ו [ושם: ויגד . . כי-כפלים]."],["4843","26","<b>כי אתה . . יגיה חשכי</b>: שמו\"ב כב, כט. ראה גם סה\"מ עזר\"ת ע' לד."],["4844","27","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["4845","28","<b>אורח צדיקים כאור נוגה</b>: משלי ד, יח [ושם: ואורח]."],["4846","29","<b>הראשונות</b>: אוצ\"ל: האחרונות."],["4847","30","<b>תעלומות חכ'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540606\" data-slug=\"torat-chaim\" data-id=\"2300540606\">תו\"ח שמות ח\"א לג, א</a>. וש\"נ."],["4848","31","<b>בפ\"א</b>: [ בפעם א' אמר כ\"ק אדמו\"ר מהר\"ש] ראה גם לעיל הנחה ד\"ה הקבצו ושמעו ובהערה 132."],["4849","32","<b>דתושי' הוא תורה</b>: ראה מדרש תהלים ז, א. סנהדרין כו, ב. ז\"ח מדהנ\"ע בראשית ה, ד. עה\"כ להסה\"ד מערכת תושי'. אגה\"ק סכ\"ב. תו\"א (ואוה\"ת) יתרו סז, ב (ע' תשעח ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380288\" data-slug=\"likkutei-torah\" data-id=\"4001380288\">לקו\"ת בחוקותי מט, ג</a>."],["4850","33","<b>בראתי יצה\"ר . . תבלין</b>: ראה ספרי עקב יא, יח. קדושין ל, ב."],["4851","34","<b>אם אבן הוא נמוח</b>: קדושין שם."],["4852","35","<b>וכמו שיורדים</b>: אוצ\"ל: וכמו מים שיורדים."],["4853","36","<b>מים שיורדים על האבן . . רכים</b>: ראה אבות דר\"נ פ\"ו, ב."],["4854","37","<b>דקרי\"ס שהיא הכנה למ\"ת</b>: ראה שער האמונה לב, ב ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540550\" data-slug=\"torat-chaim\" data-id=\"2300540550\">תו\"ח בשלח ח\"א קמח, ג</a>. וש\"נ."],["4855","38","<b>דקרי\"ס שהיא הכנה . . להלוחות הראשונות . . הלוחות השניות</b>: ראה גם סה\"מ תרס\"ג ח\"ב כאן ע' קיב."],["4856","39","<b>שהידיעה אינה מכרחת הבחירה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370067\" data-slug=\"torah-or\" data-id=\"3901370067\">תו\"א וירא טו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670074\" data-slug=\"torat-chaim\" data-id=\"2300670074\">תו\"ח בראשית ל, ד</a> ובהערה 15. תולדות קנד, ב ואילך ובהערה 43. סה\"מ תר\"ם ח\"א ע' תסו."],["4857","40","<b>שכל הנביאים . . נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29. אוה\"ת מטות ע' א'תצד."]]],[2001910469,"וגואל אחרון<sup data-n=\"4858\">41</sup>, דגבי משה כתי' ונתתי עשב בשדך לבהמתך<sup data-n=\"4859\">42</sup> וצ\"ל איך אמר ע\"ע ונתתי, אך הנה משנה תורה משה אמרה מפי עצמו וברוה\"ק (בפ\"א כ\"ה בתוס'<sup data-n=\"4860\">43</sup>) והו\"ע שכינה מדברת מתוך גרונו של משה<sup data-n=\"4861\">44</sup> וא\"כ מה המלאך יכול לומר ע\"ע בי נשבעתי נאום ה'<sup data-n=\"4862\">45</sup> מכ\"ש נשמה שגבוה ממלאך<sup data-n=\"4863\">46</sup>. וענין לבהמתך דכתי' וזרעתי את בנ\"י זרע אדם וזרע בהמה<sup data-n=\"4864\">47</sup>, דנשמות הגבוהות נקראים בשם זרע אדם ונשמות דבי\"ע נק' בשם זרע בהמה<sup data-n=\"4865\">48</sup>, ומשה המשיך בהם בחי' הדעת דאצי', וזהו עשב ע\"ב שי\"ן<sup data-n=\"4866\">49</sup>, וזהו ונתתי עשב בשדך לבהמתך שהמשיך בחי' הדעת גם בנשמות דבי\"ע, אך משה נתנבא בזה שהוא המשיך בחי' זה למטה, והעיקר שיהי' בחי' זה בשבטי ישראל לכן שבטי ישראל י\"ב מספר זה<sup data-n=\"4867\">50</sup>.\n<b>ועפ\"ז</b> יובן מ\"ש עולמי עולמי מי בראך יעקב בראך וישראל יצרך ולכאו' והרי הבריאה היא יש מאין, אך הנה עיקר הכוונה הוא שיהי' בחי' זה בשבטי ישראל ולפעמים יעקב נכלל בכלל שבטי ישראל ולולי זאת לא הי' ברה\"ע כלל, וכמארז\"ל עשרה הכף בשקל הקדש<sup data-n=\"4868\">51</sup> עה\"ד מכוון כנגד עשרה מאמרות<sup data-n=\"4869\">52</sup>, תנאי",[["4858","41","<b>משה . . וגואל אחרון</b>: ראה שמו\"ר פ\"ב, ד. ו. דב\"ר ספ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111008\" data-slug=\"likkutei-sichot\" data-id=\"1300111008\">לקו\"ש שמות כרך יא ע' 8</a>. וש\"נ. מטו\"מ כרך כח ע' 213. וש\"נ. מאמרי אדה\"א ויקרא ח\"א ע' שנט. וש\"נ. נ\"ך ע' תרד. וש\"נ."],["4859","42","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380290\" data-slug=\"likkutei-torah\" data-id=\"4001380290\">לקו\"ת בחוקותי נ, א</a>. סה\"מ תרכ\"ט ע' ריד ואילך."],["4860","43","<b>משנה תורה . . מפי עצמו . . בתוס'</b>: ראה מגילה לא, ב ותוד\"ה משה. לעיל (בחלק המאמרים) בהמאמר כאן הערה 45."],["4861","44","<b>שכינה מדברת מתוך גרונו של משה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' רלא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670123\" data-slug=\"torat-chaim\" data-id=\"2300670123\">תו\"ח בראשית לה, ב</a> הערה 26. שע\"ת לט, א ובהערה 6."],["4862","45","<b>בי נשבעתי נאום ה'</b>: וירא כב, טז. ראה אגה\"ק סכ\"ה [קמא, א] בפ' וירא לפי' הרמב\"ן. ד\"ה להבין מ\"ש בפע\"ח (קו\"א לתניא קנט, א). סה\"מ תרכ\"ט ע' צה. וש\"נ. ע' קנח. וש\"נ. ע' ריב ואילך. תרל\"א ח\"א ע' רסה. וש\"נ. המשך תרס\"ו ע' תס.\nלעיל הובא פי' הרמב\"ן — ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560059\" data-slug=\"or-hatorah-hb\" data-id=\"8316560059\">אוה\"ת</a> מיכה כרך א ע' תפח שמציין: כמ\"ש באגה\"ק ססי' כ\"ה בשם הרמב\"ן ס\"פ וירא. באוה\"ת וישלח ע' 496 מציין: וכמ\"ש הרמב\"ן פ' וירא גבי הגר. ראה סה\"מ תרל\"ג ח\"א ס\"ע נב בהערה שמציין לוירא יט, כד. ע\"ש."],["4863","46","<b>נשמה שגבוה ממלאך</b>: ראה ע\"ח שער העבורים שכ\"א, פ\"א. אגה\"ת פ\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380822\" data-slug=\"likkutei-torah\" data-id=\"4001380822\">לקו\"ת פ' ראה כו, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">ברכה צח, א</a>. סה\"מ תרל\"ח ע' קיג ואילך. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ."],["4864","47","<b>וזרעתי את בנ\"י . . בהמה</b>: ירמי' לא, כו [ושם: א) בית ישראל. ב) בדילוג. וכ\"ה גם (לעיל בחלק המאמרים) במאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' על יד הערה 66. אבל ראה גם לקמן הנחה ד\"ה אז ישיר משה על יד הערה 157. מאמרי אדה\"א ויקרא ח\"א ע' ב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560173\" data-slug=\"or-hatorah-hb\" data-id=\"8316560173\">אוה\"ת בראשית כרך ג' ע' תקנג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות יד, א</a> ובהערה 627. סה\"מ תר\"ם ח\"ב ע' תשכג]."],["4865","48","<b>דנשמות . . זרע אדם . . בהמה</b>: ראה תו\"א ר\"פ משפטים. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550047\" data-slug=\"torat-chaim\" data-id=\"2300550047\">תו\"ח שם ח\"ב רעז, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550176\" data-slug=\"torat-chaim\" data-id=\"2300550176\">רפ, א</a>. רפא, ג ואילך. סה\"מ תר\"ם ח\"א ע' תכא. וש\"נ. לקמן הנחה ד\"ה אז ישיר משה קרוב לסופו."],["4866","49","<b>עשב ע\"ב שי\"ן</b>: ראה ת\"ז תכ\"א סב, ב. תנ\"א פו, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370335\" data-slug=\"torah-or\" data-id=\"3901370335\">תו\"א משפטים עה, ב</a>. אוה\"ת שם ע' א'קיד."],["4867","50","<b>י\"ב מספר זה</b>: ב\"ר פכ\"ד, ה. פס\"ג, ו. שמו\"ר פל\"ח, ח. ויק\"ר פ\"ח, ג."],["4868","51","<b>עשרה הכף בשקל הקדש</b>: נשא ז, פו."],["4869","52","<b>עה\"ד . . מאמרות</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לקו\"ת חוקת נז, סע\"ג ואילך בשם המגיד. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540769\" data-slug=\"torat-chaim\" data-id=\"2300540769\">תו\"ח וארא ח\"א פא, ג</a> ובהערה 636. סה\"מ תרל\"ח ע' ע. וש\"נ. סה\"מ מלוקט ד' ע' פ ואילך."]]],[2001910470,"התנה הקב\"ה<sup data-n=\"4870\">53</sup> במע\"ב אם יקיימו ישראל את תורתי מוטב וא\"ל אחזיר את העולם לתוהו ובוהו, אלה תולדות שמו\"א<sup data-n=\"4871\">54</sup> אלה בזכות מי<sup data-n=\"4872\">55</sup> כו' בזכות אלה שמות בנ\"י<sup data-n=\"4873\">56</sup> ואלה כו' בזכות אלה העדות<sup data-n=\"4874\">57</sup> כו' אלמלא מעמדות לא נתקיימו שו\"א<sup data-n=\"4875\">58</sup> הרי עיקר הקיום ע\"י תורה, וכ\"ה באמת דעיקר ע\"י יעקב דכתי' אלה תולדות יעקב יוסף<sup data-n=\"4876\">59</sup> ולכאו' הול\"ל ראובן, והענין דיעקב הוא בריח התיכון<sup data-n=\"4877\">60</sup> המבריח מן הקצה אל הקצה ובמשכן הו\"ע כרוב א' מקצה מזה<sup data-n=\"4878\">61</sup> וכרוב א' מקצה מזה, וכ\"ז בעולמות עליונים שלמעלה מעולמות הנבראים וכדי שיומשך גם בנבראים כתי' ויוסף הוא המשביר<sup data-n=\"4879\">62</sup> לכל עם הארץ שהמשיך בבי\"ע ג\"כ והוא ו' עם מילוי ו'<sup data-n=\"4880\">63</sup>, א\"כ הרי יעקב הוא המשפיע בעולמות, אך זה הי' עד מ\"ת דאי' במדרש כל המצות שעשו האבות ריחות היו<sup data-n=\"4881\">64</sup> אבל אנו שמן תורק שמיך<sup data-n=\"4882\">65</sup> כדבר שמריקים מכלי לכלי<sup data-n=\"4883\">66</sup> לכן במ\"ת שהי' השפעה עצמיות הי' ע\"י משה, דמשה מלגאו ויעקב מלבר<sup data-n=\"4884\">67</sup>, לזאת עד מ\"ת שהי' בחיצוניות הי' ע\"י יעקב אבל במ\"ת שהוא השפעה עצמיות הוא ע\"י משה.\n<b>והנה</b> עיקר הכוונה הוא שיומשך בחי' זה בנש\"י והוא ע\"י המצות, והמצות נק' בשם זריעה<sup data-n=\"4885\">68</sup> דכתי' אור זרוע לצדיק<sup data-n=\"4886\">69</sup> זרע הקב\"ה התומ\"צ<sup data-n=\"4887\">70</sup> כדי להנחילם לישראל לעוה\"ב ולא הניח דבר שאין בו מצוה בא לזרוע שדהו צריך להניח פאה<sup data-n=\"4888\">71</sup> כשבא",[["4870","53","<b>תנאי התנה הקב\"ה</b>: כ\"ה בכ\"מ ומהם: לקמן הנחה ד\"ה והמים להם חומה על יד הערה 48. (לעיל בחלק המאמרים) מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ובהערה 27. מאמרי אדה\"א בראשית ע' קמ. וש\"נ. תו\"ח שם ב, ד הערה 37. — ראה שבת פח, א."],["4871","54","<b>אלה תולדות שמו\"א</b>: בראשית ב, ד [ושם: השמים והארץ]."],["4872","55","<b>אלה בזכות מי</b>: ראה שמו\"ר פמ\"ח, [ב]. סה\"מ תר\"ם שם. וש\"נ."],["4873","56","<b>אלה שמות בנ\"י</b>: שמות א, א [ושם: ואלה — אבל כ\"ה גם בשמו\"ר שם. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה ט. סה\"מ תרל\"ח ע' עח הערה 302. תר\"ם ח\"א ע' שצו. וש\"נ]."],["4874","57","<b>אלה העדות</b>: ואתחנן ד, מה."],["4875","58","<b>אלמלא מעמדות . . שו\"א</b>: תענית כז, ב."],["4876","59","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה ב\"ר פפ\"ד, ו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480137\" data-slug=\"or-hatorah-hb\" data-id=\"8316480137\">אוה\"ת וישב כרך ה ע' תתק</a> ואילך. סה\"מ תרכ\"ט ע' שפו. תרכ\"ז ע' ריט. וש\"נ."],["4877","60","<b>דיעקב הוא בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381181\" data-slug=\"likkutei-torah\" data-id=\"4001381181\">לקו\"ת שה\"ש יג, סע\"א</a> ואילך. מאמרי אדה\"א שמות ח\"א ע' יט. וש\"נ. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["4878","61","<b>כרוב א' מקצה מזה</b>: תרומה כה, יט. ראה תו\"א תרומה פא, ב."],["4879","62","<b>ויוסף הוא המשביר</b>: מקץ מב, ו [בדילוג]."],["4880","63","<b>ו' עם מילוי ו'</b>: ראה לקו\"ת חוקת ס, ד. אוה\"ת בהעלותך ע' שפז. פ' ראה ע' תשעו. סה\"מ תרכ\"ט ע' כז. וש\"נ. ע' שפו."],["4881","64","<b>כל המצות . . ריחות היו</b>: ראה שהש\"ר שבהערה הבאה."],["4882","65","<b>אנו שמן תורק שמך</b>: שה\"ש א, ג. ראה שהש\"ר פ\"א, ג (א). מאמרי אדה\"א שמות ח\"א ע' רנז ואילך. וש\"נ. סה\"מ תרכ\"ט ע' רכא ואילך. וש\"נ. סה\"מ תר\"ם ח\"א ע' תד ואילך."],["4883","66","<b>כדבר שמריקים מכלי לכלי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081087\" data-slug=\"likkutei-sichot\" data-id=\"1300081087\">לקו\"ש בהעלותך כרך ח ע' 76</a> הערה 11."],["4884","67","<b>דמשה מלגאו ויעקב מלבר</b>: ת\"ז תי\"ג כט, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380634\" data-slug=\"likkutei-torah\" data-id=\"4001380634\">לקו\"ת פינחס עח, ג</a> ואילך."],["4885","68","<b>והמצות נק' בשם זריעה</b>: ראה תו\"א שמות נג, ג. סה\"מ תרל\"ח ע' תי ואילך. תר\"ם ח\"א ע' רסב. וש\"נ."],["4886","69","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["4887","70","<b>זרע הקב\"ה התומ\"צ</b>: ראה במדב\"ר פי\"ז, ה. סה\"מ תר\"ם שם. וש\"נ."],["4888","71","<b>לזרוע שדהו . . פאה</b>: במדרש שם: לזרוע לא תזרע כרמך [תצא כב, ט]. לקצור כי תקצור קצירך [שם כד, יט]."]]],[2001910471,"לבנות בית צ\"ל מזוזה ומעקה כו'. ולכאורה צ\"ל למה נק' המצות בשם זריעה. אך הנה ארז\"ל נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"4889\">72</sup> ולכאו' צ\"ל מה שייך דירה בתחתונים והלא את השמים ואת הארץ אני מלא<sup data-n=\"4890\">73</sup> ולית אתר פנוי מיני'<sup data-n=\"4891\">74</sup> ואי' במדרש דמה ראה בלבת אש מתוך הסנה<sup data-n=\"4893\">76</sup> ללמד שאין מקום פנוי<sup data-n=\"4892\">75</sup> מהשכינה אפי' סנה, והו\"ע דלית אתר פנוי מיני', וא\"כ מהו\"ע דירה בתחתונים. והענין דהנה יעקב כשהי' במקום המקדש א' מה נורא המקום הזה<sup data-n=\"4894\">77</sup> ות\"א לית דין אתר הדיוט<sup data-n=\"4895\">78</sup>, ומשמע דשארי מקומות הם אתר הדיוט, דמקור העולמות הם ע\"מ שנק' מילין דהדיוטא<sup data-n=\"4896\">79</sup> (בפ\"א וכמו עד\"מ מלך שיש לו ריבוי זהב ומשבחים אותו בחרסין כמו\"כ ע\"מ לגבי א\"ס הם מילין דהדיוטא), אך מקום המקדש לית דין אתר הדיוט וכמ\"ש אכן יש ה' במקום הזה<sup data-n=\"4897\">80</sup>, הגם דאת השמים ואת הארץ אני מלא הרי כתי' ואתה מחי' את כלם<sup data-n=\"4898\">81</sup> שהם אותיות מא' ועד ת' שהם חילופי' ותמורות שהו\"ע העלמות והסתרים ובמקדש מאיר גילוי אלקות, אף דצמצם שכינתו<sup data-n=\"4899\">82</sup> בין שני בדי ארון אך הצמצום הוא סיבת הגילוי, וזהו במקדש קורין את ה' ככתבו ובמדינה בכינויו<sup data-n=\"4900\">83</sup>, ואמרז\"ל מה הנשמה ממלא את הגוף<sup data-n=\"4901\">84</sup> כך הקב\"ה ממלא כל העולם והנה הנפש שמחי' את הגוף אף שהוא בכל הגוף ה\"ז רק בהתפשטות אבל עיקר הנשמה הוא במוח שבראש<sup data-n=\"4902\">85</sup> לכן כל כאב אפי' שברגל מרגיש בו<sup data-n=\"4903\">86</sup>, כמו\"כ עיקר<sup data-n=\"4904\">87</sup> הגילוי הי' במקדש. אך מובן ממשל זה דכמו שהנשמה שמחי' את הגוף הוא רק הארה היינו פנימיות הנשמה אבל לא המקיף כמו\"כ יובן שמה שנמשך במקדש הוא רק בחי' ממכ\"ע אבל בחי' סוכ\"ע גם במקדש לא האיר<sup data-n=\"4905\">*88</sup> שאם במקדש האיר בחי' סוכ\"ע",[["4889","72","<b>נתאווה הקב\"ה . . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>. לעיל (בחלק המאמרים) בהמאמר כאן ספ\"א. וש\"נ."],["4890","73","<b>והלא את השמים . . אני מלא</b>: ירמי' כג, כד [ושם: הלא]."],["4891","74","<b>ולית אתר פנוי מיני'</b>: נסמן לעיל הנחה ד\"ה הקבצו ושמעו הערה 44."],["4893","76","<b>בלבת אש מתוך הסנה</b>: שמות ג, ב."],["4892","75","<b>במדרש . . ללמד שאין מקום פנוי</b>: שמו\"ר פ\"ב, ה."],["4894","77","<b>מה נורא המקום הזה</b>: ויצא כח, יז."],["4895","78","<b>ות\"א לית דין אתר הדיוט</b>: ראה אוה\"ת בא כרך ז ע' ב'תרכד."],["4896","79","<b>ע\"מ שנק' מילין דהדיוטא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a>. אוה\"ת בא שם. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 170 ואילך. סה\"מ תרכ\"ז ס\"ע רטו ואילך. תרל\"א ח\"א ע' ד."],["4897","80","<b>אכן יש ה' במקום הזה</b>: ויצא כח, טז. ראה גם המשך תער\"ב ח\"ב ע' תתקכט ואילך."],["4898","81","<b>ואתה מחי' את כלם</b>: נחמי' ט, ו. ראה שער היחוד והאמונה פ\"ב."],["4899","82","<b>דצמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380223\" data-slug=\"likkutei-torah\" data-id=\"4001380223\">לקו\"ת אמור לד, ב</a>. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["4900","83","<b>במקדש . . ה' ככתבו ובמדינה בכינויו</b>: תמיד פ\"ז, מ\"ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ראה קראתי בשם ספ\"ד."],["4901","84","<b>מה הנשמה ממלא את הגוף</b>: ראה ברכות י, א. מאמרי אדה\"א הנחות תקע\"ז ע' לה. וש\"נ."],["4902","85","<b>עיקר הנשמה הוא במוח שבראש</b>: ראה רבינו יונה לברכות יד, סע\"ב ד\"ה הרוצה. לקמן הנחה ד\"ה וברך את לחמך הערה 21."],["4903","86","<b>במוח . . כל כאב אפי' שברגל מרגיש בו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, א</a>): ואפי' חום שבצפרני רגליו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תריח."],["4904","87","<b>עיקר</b>: אחרי תיבה זו נרשם משהו וקשה לקרותו בהצילום."],["4905","*88","<b>במקדש . . ממכ\"ע . . סוכ\"ע גם במקדש לא האיר</b>: ראה סה\"מ תרמ\"ד ע' רכב."]]],[2001910472,"הרי אינו שייך התחלקות ראש ורגל, ובמקדש קורין את ה' ככתבו ובמדינה בכינויו הרי בעת שקראו במקדש ככתבו קראו במדינה בכינויו אלא שהאיר רק בחי' ממכ\"ע, וזהו שאף בימי שלמה לא קיימא סיהרא באשלמותא<sup data-n=\"4906\">88</sup> (בפ\"א שהוא רק בחי' סיהרא). וזהו נתאווה הקב\"ה להיות לו דירה בתחתונים היינו שיומשך בחי' סוכ\"ע, הגם דאת השמים כו' ה\"ז בהעלם והכוונה שיומשך בגילוי, ומפני מה נתאווה אין אנו יודעין<sup data-n=\"4907\">89</sup> אבל זה אנו יודעין שנתאווה, וכדי שיהי' דירה בתחתונים הוא ע\"י המצות.\n<b>והענין</b> דהנה ארז\"ל חייב לברך מאה ברכות בכ\"י<sup data-n=\"4908\">90</sup>, וצ\"ל מהו המספר דמאה ומהו\"ע הברכות מה צריך למצות שלנו. אך הנה ברכה הוא ל' המשכה<sup data-n=\"4909\">91</sup> וכמ\"ש המבריך את הגפן<sup data-n=\"4910\">92</sup> שממשיכו בארץ למטה ועי\"ז נצמח עוד גפן, ומאה ברכות הם מאה המשכות, ומספר דמאה הוא כדי שיומשך לכה\"פ אחד בעשי' דכשנמשך מאה בבריאה נמשך חלק עשירי<sup data-n=\"4912\">94</sup> ביצי' והוא עשרה ומיצי' נמשך חלק עשירי בעשי'<sup data-n=\"4911\">93</sup> הרי נמשך אחד בעשי' ואם לא הי' מאה ברכות לא הי' נמשך בעשי' אפי' א', וכתי' בית ישראל ברכו את הוי'<sup data-n=\"4913\">95</sup> כדי שיומשך משם הוי' הוא ע\"י ישראל דוקא, דר\"מ<sup data-n=\"4914\">96</sup> למד זה ממ\"ש ועתה ישראל מה ד' אלקיך שואל מעמך<sup data-n=\"4915\">97</sup> הרי ישראל כתיב מפני שיש בהם בחי' מ\"ה, דההפרש בין מה למאה הוא דבמאה יש א' דארז\"ל ך\"ו דור קרא הא' תגר<sup data-n=\"4916\">98</sup> על שלא הי' בו ברה\"ע שהוא ראש לכל האותיות, ואי' בזהר הטעם דא' ר\"ת ארור<sup data-n=\"4917\">99</sup> וב' ר\"ת ברוך פי' דאלף הוא ראש לכל האותיות והוא אותיות פלא<sup data-n=\"4918\">100</sup> שהוא בחי' כתר<sup data-n=\"4919\">101</sup> ושם כחשיכה כאורה<sup data-n=\"4920\">102</sup> ויומשך גם למקום שאינו ראוי לכן לא הי' בו ברה\"ע, ולפ\"ז צ\"ל איך הי' מ\"ת בא', הענין דאחר שהי' ברה\"ע בב' שהוא בחי' חכ' וכמ\"ש בחכ' יבנה",[["4906","88","<b>שאף בימי שלמה . . באשלמותא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670186\" data-slug=\"torat-chaim\" data-id=\"2300670186\">תו\"ח בראשית לב, ג</a> ובהערה 39. וישב קצח, סע\"ד. סה\"מ תרכ\"ח ע' מא. סה\"מ מלוקט ב' ע' רעח ואילך. מלוקט ו' ע' נב ואילך."],["4907","89","<b>ומפני מה נתאווה אין אנו יודעין</b>: ראה גם אוה\"ת בלק ע' תתקצז: ושמעתי שכאדמו\"ר נ\"ע אמר בדרושים הישנים בלאזני' . . הנה על תאווה אין שואלים קושיא. סה\"מ תרכ\"ז ע' תנג ואילך. וש\"נ. תרל\"ב ח\"ב ע' תקט. המשך מים רבים פפ\"ו ע' צא. תרל\"ח ס\"ע תנד ואילך. וראה גם פלח הרמון בחוקותי ע' תפג."],["4908","90","<b>חייב לברך מאה ברכות בכ\"י</b>: ראה מנחות מג, ב."],["4909","91","<b>ברכה הוא ל' המשכה</b>: ראה גם זח\"ג רע\"מ עקב ער, סע\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו\"א מקץ לז, ג</a>. לקו\"ת ואתחנן ב, א. ביאוה\"ז עקב קיט, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540841\" data-slug=\"torat-chaim\" data-id=\"2300540841\">תו\"ח בשלח ח\"א קס, ג</a>. וש\"נ. סה\"מ תר\"ם ח\"א ע' רלח. וש\"נ."],["4910","92","<b>המבריך את הגפן</b>: כלאים רפ\"ז."],["4912","94","<b>נמשך חלק עשירי</b>: ראה גם שערי אורה [לרי\"ג] שער א (ה, ב ואילך). שפע טל בהקדמה יד, א ואילך. שם ש\"א, פ\"ה. לעיל (בחלק המאמרים) מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 38."],["4911","93","<b>מאה בבריאה . . ביצי' . . בעשי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380615\" data-slug=\"likkutei-torah\" data-id=\"4001380615\">לקו\"ת בלק עד, ב</a>."],["4913","95","<b>בית ישראל ברכו את הוי'</b>: תהלים קלה, יט."],["4914","96","<b>דר\"מ</b>: ראה סה\"מ תרל\"ח ע' ריג."],["4915","97","<b>ועתה ישראל . . שואל מעמך</b>: עקב י, יב."],["4916","98","<b>ך\"ו דור קרא הא' תגר</b>: ראה ב\"ר פ\"א, י. תנחומא — באבער — יתרו טז. וש\"נ."],["4917","99","<b>ואי' בזהר . . דא' ר\"ת ארור</b>: ויגש רה, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380793\" data-slug=\"likkutei-torah\" data-id=\"4001380793\">לקו\"ת פ' ראה יט, ב</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["4918","100","<b>דאלף . . אותיות פלא</b>: ראה זהר בלק קצג, ב. ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'. שו\"ת אור זרוע בתחלתו אלפא ביתא א ס\"ג."],["4919","101","<b>פלא . . כתר</b>: ראה תיקונים לז\"ח צח, ד."],["4920","102","<b>כחשיכה כאורה</b>: ראה לקמן הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ הערה 89."]]],[2001910473,"בית בחכ' יבנה בית<sup data-n=\"4921\">103</sup>, ולכן בראשית ת\"י בחוכמתא<sup data-n=\"4922\">104</sup>, לכן אף שמ\"ת הי' בא' נמשך ע\"י בחי' חכ' וחכ' יש בה קצת דין<sup data-n=\"4923\">105</sup> היינו הצמצום שיומשך למקום הראוי דוקא, וזהו א\"ת מה אלא מאה<sup data-n=\"4924\">106</sup> שהא' נמשך בבחי' מה נמשך למקום הראוי, וזהו ועתה ישראל מה ה' אלקיך שואל מעמך ישראל שיש בהם בחי' מה ביטול נמשך הא' למקום הראוי. ומשנת\"ל שצ\"ל מספר מאה, ג\"ז אמת דיחידות עשירית מאה, מאה בבינה<sup data-n=\"4925\">107</sup>, והתגלות עתיק בבינה<sup data-n=\"4926\">108</sup>, א\"כ ע\"י מאה ברכות נמשך בחי' א' פלא.\n<b>אך</b> הנה הברכות הם בדיבור וידוע דדיבור הוא ביצי'<sup data-n=\"4927\">109</sup> ונת\"ל דהעיקר שיומשך בעשי' והו\"ע מעשה המצות, דמח' דיבור ומעשה מח' בבריאה ודיבור ביצי' ומעשה בעשי'<sup data-n=\"4928\">110</sup>, ובכל מצוה צ\"ל מחדו\"מ<sup data-n=\"4929\">111</sup> דע\"י כוונת המצוה נמשך בעולם המח' הוא עולם הבריאה וע\"י הדיבור נמשך ביצי' וע\"י מעשה המצוה נמשך בעשי'. וזהו בראתי יצרתיו אף עשיתיו<sup data-n=\"4930\">112</sup>, בראתיו יצרתיו הם בריאה ויצי' ואף עשיתיו הפסיק הענין<sup data-n=\"4931\">113</sup>, דבריאה יצי' קרובים זל\"ז כמו מח' ודיבור שהם בערך, אבל מעשה לגבי דיבור אינו בערך לכן נא' אף הפסיק הענין. מ\"מ אף הוא ל' ריבוי שמרבה בחי' רביעית<sup data-n=\"4932\">114</sup>, דכדי שיומשך מטה מטה יותר שרשו למעלה מעלה ביותר<sup data-n=\"4933\">115</sup> וכמ\"ש די לחכימא ברמיזא<sup data-n=\"4934\">116</sup> דמי שהוא חכם די לו ברמיזא ומה שא\"א להתגלות בדיבור ה\"ה מתגלה ברמיזא הרי יש במעשה מה שאין בדיבור כלל, וכתי' ואתא<sup data-n=\"4935\">117</sup> מרבבות קדש<sup data-n=\"4936\">118</sup>, אתא הם אותיות<sup data-n=\"4937\">119</sup> ושרשם מרבבות<sup data-n=\"4938\">120</sup> דיחידות עשירית מאות אלפים רבבות אלפי'",[["4921","103","<b>בחכ' יבנה בית . . בית</b>: משלי כד, ג. ראה גם סה\"מ תר\"ם ח\"א ע' שז. וש\"נ."],["4922","104","<b>בראשית ת\"י בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["4923","105","<b>וחכ' . . קצת דין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. סה\"מ תר\"ם ח\"א ע' שז. וש\"נ. לקמן הנחה ד\"ה וברך את לחמך על יד הערה 49."],["4924","106","<b>א\"ת מה אלא מאה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["4925","107","<b>מאה בבינה</b>: ראה גם כסא מלך סתי\"ג אות ק. אוה\"ת שמות ע' פב."],["4926","108","<b>והתגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["4927","109","<b>דדבור הוא ביצי'</b>: ראה בסמוך בפנים ובהערה הבאה."],["4928","110","<b>מח' בבריאה . . ביצי' . . בעשי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380597\" data-slug=\"likkutei-torah\" data-id=\"4001380597\">סט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a>. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תא. וש\"נ."],["4929","111","<b>ובכל מצוה צ\"ל מחדו\"מ</b>: ראה לקו\"ת חוקת נז, א. פינחס עה, א. סידור שחרית לא, ג ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071374\" data-slug=\"likkutei-sichot\" data-id=\"1300071374\">לקו\"ש ח\"ז ע' 362</a>."],["4930","112","<b>בראתי יצרתיו אף עשיתיו</b>: ישעי' מג, ז [ושם: בראתיו]. ראה הנסמן לעיל הערה 110."],["4931","113","<b>ואף עשיתיו הפסיק הענין</b>: ישעי' מג, ז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540181\" data-slug=\"torat-chaim\" data-id=\"2300540181\">תו\"ח בשלח ח\"א קמד, ג</a>. וש\"נ."],["4932","114","<b>אף הוא . . בחי' רביעית</b>: ישעי' מג, ז. ראה גם לקו\"ת שם סז, ב. סט, ג."],["4933","115","<b>דכדי שיומשך מטה . . מעלה ביותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["4934","116","<b>די לחכימא ברמיזא</b>: ראה רשב\"ם ח\"ש כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב."],["4935","117","<b>ואתא</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 130."],["4936","118","<b>ואתא מרבבות קודש</b>: ברכה לג, ב."],["4937","119","<b>אתא הם אותיות</b>: ישעי' כא, יב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. מאמרי אדה\"א שמות ח\"א ע' קנח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540319\" data-slug=\"torat-chaim\" data-id=\"2300540319\">תו\"ח שמות ח\"א כה, ג</a>. וש\"נ."],["4938","120","<b>אותיות ושרשם מרבבות</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 132."]]],[2001910474,"בחכמה<sup data-n=\"4939\">121</sup> וכמ\"ש אלפך חכ'<sup data-n=\"4940\">122</sup> ורבבות בכתר<sup data-n=\"4941\">123</sup> הרי שרש בכתר<sup data-n=\"4942\">124</sup>, ואף שלמטה האותיות אינם בחי' אחרונה אבל למעלה הם בחי' אחרונה דדיבור של הקב\"ה חשיב מעשה<sup data-n=\"4943\">125</sup>, ועוד יש ע\"ז הרבה משלים כמו החותם שהוא ניכר על השעוה<sup data-n=\"4944\">126</sup> ולא על האבן טוב, וכמו פני ארי' שלמעלה מפני שור<sup data-n=\"4945\">127</sup> ולמטה הרי ארי' הוא חי' טמאה<sup data-n=\"4946\">128</sup> ושור בהמה טהורה, והעיקר יובן מטפה גשמיות שהוא השפעה עצמיות והשפעות הרב לתלמיד הוא השפעה חיצוניות<sup data-n=\"4947\">129</sup> ומ\"מ העצמיות נמשך בטפה גשמיות דוקא.\n<b>וכמו\"כ</b> יובן בענין המצות שהם רמזים<sup data-n=\"4948\">130</sup> דתרי\"ג מצות דאורייתא<sup data-n=\"4949\">131</sup> וז'<sup data-n=\"4951\">133</sup> מצות<sup data-n=\"4952\">134</sup> דרבנן הם תר\"ך<sup data-n=\"4950\">132</sup> עמודי אור<sup data-n=\"4953\">135</sup> ונמשכו למטה בדברי' גשמים וע\"י שהאדם מניח למטה תפילין נמשך למעלה ג\"כ הקב\"ה מניח תפילין<sup data-n=\"4954\">136</sup>, וציצית למעלה הוא ויקחני בציצית ראשי<sup data-n=\"4955\">137</sup> והו\"ע שער רישי' כעמר נקי<sup data-n=\"4956\">138</sup> ומספר דל\"ב הם ל\"ב נת\"ח<sup data-n=\"4957\">139</sup>, שהם רק רמזים לבד, וכתי' הציבי לך ציונים<sup data-n=\"4958\">140</sup> שהם רק ציונים, ולכן",[["4939","121","<b>אלפי' בחכמה</b>: ראה גם כסא מלך סתי\"ג אות ק. אוה\"ת בראשית כרך ג' ריש ע' 1134. סה\"מ תרל\"א ח\"א ע' רפט. וככה תרל\"ז פקי\"ז. סה\"מ תרל\"ח ע' קפח."],["4940","122","<b>אלפך חכמה</b>: איוב לג, לג [ושם: ואאלפך]."],["4941","123","<b>ורבבות בכתר</b>: ראה כסא מלך שם. סה\"מ תרל\"ח ע' סד. וש\"נ."],["4942","124","<b>שרש בכתר</b>: אוצ\"ל: שרש האותיות בכתר."],["4943","125","<b>דדיבור . . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח. אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרס\"ח ע' צט."],["4944","126","<b>החותם שהוא ניכר על השעוה</b>: ראה מאמרי אדה\"ז כתובים ח\"א ע' נז. אוה\"ת שמות ע' פו. וארא ע' רב. ע' ריד. שה\"ש ע' קא."],["4945","127","<b>פני ארי' . . מפני שור</b>: ראה יחזקאל א, י."],["4946","128","<b>ארי' הוא חי' טמאה</b>: ראה אוה\"ח אחרי יז, יד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, ג</a>. סה\"מ תר\"ם ח\"א ע' כג. וש\"נ."],["4947","129","<b>השפעה עצמיות . . השפעה חיצוניות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381287\" data-slug=\"likkutei-torah\" data-id=\"4001381287\">לקו\"ת שה\"ש לט, ד</a>. סה\"מ תר\"ם ח\"ב ע' תרב ואילך ובהנסמן שם. לעיל (בחלק המאמרים) מאמר ד\"ה הקבצו ושמעו פ\"א."],["4948","130","<b>המצות שהם רמזים</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' קט. לעיל (בחלק המאמרים) מאמר ד\"ה במשנה כו' ר' נהוראי אומר פ\"א."],["4949","131","<b>דתרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לרי\"ג מערכת שש מאות [צפת תשנ\"ב ע' 208). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. ובאגרותיו ח\"ג ע' רג."],["4951","133","<b>וז' מצות דרבנן</b>: וסימנם: נ\"ע בשמח\"ה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211410\" data-slug=\"likkutei-sichot\" data-id=\"1300211410\">לקו\"ש יתרו כרך כא ע' 401</a>. ובאגרותיו ח\"ב ע' שכ."],["4952","134","<b>וז' מצות דרבנן</b>: ראה אגה\"ק סכ\"ט. דרך חיים פנ\"ו. פס\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291104\" data-slug=\"likkutei-sichot\" data-id=\"1300291104\">לקו\"ש שופטים כרך כט ע' 104</a> ואילך. וש\"נ."],["4950","132","<b>דתרי\"ג . . וז' . . תר\"ך</b>: ראה כתר תורה הובא בתורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["4953","135","<b>תר\"ך עמודי אור</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"ג. לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670571\" data-slug=\"torat-chaim\" data-id=\"2300670571\">תו\"ח בראשית מה, ג</a> הערה 32."],["4954","136","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370162\" data-slug=\"torah-or\" data-id=\"3901370162\">תו\"א מקץ לה, ב</a> ואילך. לעיל (בחלק המאמרים) בהמאמר כאן הערה 126."],["4955","137","<b>וציצית . . ויקחני בציצית ראשי</b>: יחזקאל ח, ג. מנחות מב, א. רש\"י שלח טו, לח."],["4956","138","<b>שער רישי' כעמר נקי</b>: ע\"פ דניאל ז, ט. ראה גם סה\"מ תרכ\"ז ע' תכא. תרל\"ג ח\"א ע' לה."],["4957","139","<b>דל\"ב הם ל\"ב נת\"ח</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380523\" data-slug=\"likkutei-torah\" data-id=\"4001380523\">לקו\"ת קרח נב, ב</a>. ד."],["4958","140","<b>הציבי לך ציונים</b>: ירמי' לא, כ. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370170\" data-slug=\"torah-or\" data-id=\"3901370170\">תו\"א מקץ לז, סע\"ב</a> ואילך. סידור שער החנוכה רפ, א ואילך. מאמרי אדה\"ז תקס\"ד ע' צב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950473\" data-slug=\"or-hatorah-hb\" data-id=\"8315950473\">אוה\"ת בשלח ע' תעג</a> ואילך."]]],[2001910475,"נק' המצות בשם זריעה שהוא ג\"כ כנ\"ל דזרעוני גינה אינן נאכלים ואפי' אותם שנאכלים הרי מגרעין א' נצמח ריבוי שלא בערך וכמ\"ש ויזרע בארץ ההיא וימצא מאה שערים<sup data-n=\"4959\">141</sup>, ובאמת ארז\"ל אין זריעה אלא צדקה<sup data-n=\"4960\">142</sup>, אך אנו רואין שמגרעין נצמח ריבוי שלא בערך, וזרעוני גינה אינם נאכלים, ומ\"מ נצמח מהם אילן עם ענפים ועלים ופירות ומוכרח שבתחילה הי' כ\"ז בהגרעין<sup data-n=\"4961\">143</sup> דא\"ל לא הי' נצמח כו', ומה שיש תפוחי יערים אף שיש דעה שאסור להרכיב מ\"מ העיקר כהדיעה שמותר להרכיב<sup data-n=\"4963\">145</sup> שהוא ג\"כ זריעה<sup data-n=\"4962\">144</sup>, לכן נק' המצות בשם זריעה דע\"י שעושה מצוה גשמי' למטה נמשך למעלה ג\"כ מצוה זו שאין ערך זל\"ז כלל. אך הזריעה צ\"ל בארץ דוקא, וזהו מ\"ש כי תהיו אתם ארץ חפץ<sup data-n=\"4964\">146</sup> שישראל הם בחי' ארץ שיוכל לזרוע בהם בחי' חפץ ה' (בפ\"א בחי' ה' חפץ למען צדקו<sup data-n=\"4965\">147</sup>), ודוקא כשישראל מניח התפילין<sup data-n=\"4966\">148</sup> אבל אם מונחים על השולחן א\"ז מצוה כלל, וכן דוקא כשישראל עושה המצוה אבל כשיעשה<sup data-n=\"4967\">149</sup> אותה מי שאינו מצווה כלל בהר סיני<sup data-n=\"4968\">150</sup> א\"ז כלום, ובישראל ג\"כ הרי כל מצוה יש לה אבר פרטי והנחת התפילין צ\"ל דוקא בזרועו ועל ראשו וכשמניחם על פס היד או על הבטן<sup data-n=\"4969\">151</sup> כאילו לא עשה כלום, וכמו שבארץ יש ארץ שמיוחד על זריעת ענבים ויש ארץ שמיוחד לצמיחת זתים<sup data-n=\"4970\">152</sup>.\n<b>ומכ\"ז</b> יובן מ\"ש וזאת המצוה החקים והמשפטים כו' לעשותם בארץ<sup data-n=\"4971\">153</sup> וחשיב מצות ק\"ש<sup data-n=\"4972\">154</sup> ולכאורה והלא ק\"ש היא חובת הגוף<sup data-n=\"4973\">155</sup> ושוה בארץ ובח\"ל כמו בשעה שהי' בהמק\"ד לאחר כו' ולמה אומר בארץ<sup data-n=\"4974\">156</sup> דוקא, ומה שלא חשיב רק מצות ק\"ש מבואר במ\"א התי' דק\"ש היא מצוה כללית<sup data-n=\"4975\">157</sup>, אבל צ\"ל מהו",[["4959","141","<b>ויזרע . . מאה שערים</b>: תולדות כו, יב [בדילוגים]."],["4960","142","<b>אין זריעה אלא צדקה</b>: ראה תד\"א זוטא פ\"א. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 72."],["4961","143","<b>שבתחילה הי' כ\"ז בהגרעין</b>: ראה גם לעיל שם ובהערה 142."],["4963","145","<b>שאסור להרכיב . . שמותר להרכיב</b>: ראה פתחי תשובה לשו\"ע יו\"ד הלכות כלאי אילן סרצ\"ה, ס\"ה סק\"ב."],["4962","144","<b>ומה שיש . . ג\"כ זריעה</b>: ענין זה לא הובא (לעיל שם) בהמאמר כאן. וכן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370240\" data-slug=\"torah-or\" data-id=\"3901370240\">תו\"א שמות נג, ד</a>."],["4964","146","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["4965","147","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא. כתוב זה הובא במדרש שבהערה 70."],["4966","148","<b>כשישראל מניח התפילין</b>: ראה תו\"א שם. סה\"מ תר\"ם ח\"א ע' שא. וש\"נ."],["4967","149","<b>אם מונחים על השולחן . . אבל כשיעשה</b>: ראה גם מאמר ד\"ה הבאים ישרש תשמ\"ג נעתק בחלקו במ\"מ לתו\"א שם."],["4968","150","<b>אבל כשיעשה . . בהר סיני</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 150."],["4969","151","<b>והנחת תפילין . . על הבטן</b>: ראה גם לעיל שם ובהערה 151."],["4970","152","<b>ארץ שמיוחד . . ענבים . . זתים</b>: ראה שבת פה, א."],["4971","153","<b>וזאת המצוה . . לעשותם בארץ</b>: ואתחנן ו, א [ושם: לעשות]."],["4972","154","<b>וזאת המצוה . . מצות ק\"ש</b>: ראה גם לעיל הנחה ד\"ה הקבצו ושמעו ובהערה 9."],["4973","155","<b>ק\"ש היא חובת הגוף</b>: ראה קדושין לז, א וברש\"י שם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091080\" data-slug=\"likkutei-sichot\" data-id=\"1300091080\">לקו\"ש עקב כרך ט ע' 80</a> ואילך ובהערות שם. אחרי כרך יז ע' 190."],["4974","156","<b>ולמה אומר בארץ</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380880\" data-slug=\"likkutei-torah\" data-id=\"4001380880\">לקו\"ת תצא מ, סע\"ד</a>. סה\"מ תר\"ם ח\"א ע' רסא. וש\"נ."],["4975","157","<b>דק\"ש היא מצוה כללית</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקסט. וש\"נ. סה\"מ תרל\"ט ח\"ב ע' תפג. וש\"נ. פלח הרמון אמור ע' שעח. וש\"נ."]]],[2001910476,"לעשותם בארץ. אך הענין דכדי שיהי' בחי' ארץ חפץ הנ\"ל הוא ע\"י ק\"ש דהנה ארז\"ל למה קדמה שמע לוהי' א\"ש<sup data-n=\"4976\">158</sup> כדי שיקבל עליו עומ\"ש תחילה ואח\"כ יקבל עליו עו\"מ<sup data-n=\"4977\">159</sup>, ענין עו\"מ הוא שלא יעשה המצוה בקרירות דרך מצות אנשים מלומדה<sup data-n=\"4978\">160</sup> ע\"צ ההרגל ה\"ז כאילו אינו בעת שעושה המצוה, ואף שא\"א שהוא כאילו לא עשה אבל א\"ז כדבעי שצ\"ל שמחה ש\"מ<sup data-n=\"4979\">161</sup> והיינו כשמתבונן שעושה נח\"ר ליוצרו ולכאורה איך שייך לומר שהוא עושה נח\"ר כו', אך כח זה ניתן במ\"ת נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"4980\">162</sup> ומזה צ\"ל שמח, וז\"ש תחת אשר לא עבדת<sup data-n=\"4981\">163</sup> את ה' אלקיך בשמחה ובטוב לבב כו' וזהו עד\"מ שבעת שעושה המצוה ירגיש כח המצווה של מצוה זו, אך תחילה צ\"ל קבעומ\"ש היינו שיהי' מוכן לכל מה שיצוה, וזהו\"ע הקדמת נעשה לנשמע<sup data-n=\"4982\">164</sup> ועי\"ז אח\"כ קבלת עו\"מ, וזהו ארץ חפץ, לכן נק' מצות ק\"ש בשם מצות הארץ שע\"י ההתבוננות בה' אחד בשכמל\"ו<sup data-n=\"4984\">166</sup> ואהבת<sup data-n=\"4983\">165</sup> יהי' בחי' ארץ. וזהו סוף דבר, דהנה אנו אומרים בברכת ק\"ש ותן בלבנו בינה<sup data-n=\"4985\">167</sup> והו\"ע מבין דבר מתוך דבר<sup data-n=\"4986\">168</sup>, תוך דבר הוא ממכ\"ע וממנו מבין דבר שהוא סוכ\"ע<sup data-n=\"4987\">169</sup>, וזהו סוף דבר הסוף הוא שצריכים להמשיך בחי' דבר סוכ\"ע, וכדי להמשיך בחי' זו לז\"א את אלקים ירא הוא קבעומ\"ש ואת מצותיו שמור שיהי' שמירת המצות והיינו גניזת אור שבמצות שהם כלים<sup data-n=\"4988\">170</sup> וכמ\"ש רחבה מצותך מאד שיהי' כלים רחבים לבחי' מאד העליון<sup data-n=\"4989\">171</sup> וזהו ואת מצותיו שמור שיהי' שמירת המצות, כי זה כל האדם שיומשך בחי' זה באדם. וזהו אנכי עשיתי ארץ<sup data-n=\"4990\">172</sup> ואדם עלי' בראתי שעיקר המכוון בשביל האדם,",[["4976","158","<b>למה קדמה שמע לוהי' א\"ש</b>: ראה ברכות פ\"ב, מ\"ב (יג, א)."],["4977","159","<b>יקבל עליו עול מצות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380468\" data-slug=\"likkutei-torah\" data-id=\"4001380468\">לקו\"ת שלח לט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">מ, א</a>. לעיל (בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי פ\"ו."],["4978","160","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). סה\"מ תר\"ם ח\"א ע' שט. וש\"נ."],["4979","161","<b>שצ\"ל שמחה ש\"מ</b>: ראה בסמוך הערה 163."],["4980","162","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">נח\"ר</a> . . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["4981","163","<b>תחת אשר לא עבדת</b>: תבוא כח, מז. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>. מאמרי אדה\"א נ\"ך ע' כז ואילך ובהנסמן שם."],["4982","164","<b>הקדמת נעשה לנשמע</b>: שבת פח, א. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רח. ש\"א נט, ב. מאמרי אדה\"א נ\"ך ע' רסא. סה\"מ תרכ\"ט ע' רנג. תר\"ם ח\"ב ע' תתלג."],["4984","166","<b>בשכמל\"ו</b>: פסחים נו, א."],["4983","165","<b>בה' אחד . . ואהבת</b>: ואתחנן ו, ד. ה."],["4985","167","<b>ותן בלבנו בינה</b>: ברכת אהבת עולם. ראה מאמר ד\"ה זה משנת תרס\"ט בסה\"מ ליקוט ח\"ג ע' קפ-קפא."],["4986","168","<b>בינה . . מבין דבר מתוך דבר</b>: ראה חגיגה יד, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. אגה\"ק סט\"ו (קכד, רע\"א). וראה גם סה\"מ תרכ\"ט ע' רטז. וש\"נ."],["4987","169","<b>תוך דבר הוא ממכ\"ע . . דבר . . סוכ\"ע</b>: ראה סה\"מ תרל\"ח ע' רכב ואילך ובהנסמן שם. לקמן הנחה ד\"ה אז ישיר על יד הערה 87."],["4988","170","<b>שבמצות שהם כלים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370510\" data-slug=\"torah-or\" data-id=\"3901370510\">תו\"א מג\"א צז, א</a>. ויקהל קיד, ב. לקו\"ת חוקת נז, א."],["4989","171","<b>רחבה מצותך . . מאד העליון</b>: תהלים קיט, צו. ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"ב ע' תרנז. וש\"נ."],["4990","172","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב. ראה גם זהר תולדות קלד, ב. ויגש רה, ב."]]],[2001910477,"והאדם בראתי בגימ' תרי\"ג<sup data-n=\"4991\">173</sup> שיקיים המצות ועי\"ז נמשך מבחי' אנכי מי שאנכי<sup data-n=\"4992\">174</sup>.\n<b>וזהו</b> קדש ישראל לה' ראשית תבואתה וכתי' בה' וניקוד בקמץ וכולל פירות האילן ופירות האדמה ונק' תבואתה שפרי האילן נכלל בכלל פרי אדמה ולכן אם ברך על פר\"א בורא פ\"א<sup data-n=\"4993\">175</sup> יצא לבד איזה פרטים שאינו יוצא<sup data-n=\"4994\">176</sup>, וב' בחי' אלו הו\"ע בפסח על התבואה בעצרת על פה\"א<sup data-n=\"4995\">177</sup>, בפסח אז זמן בישול שעורים<sup data-n=\"4996\">178</sup> בחי' שיעור ה'<sup data-n=\"4997\">179</sup> והו\"ע בהבראם בה' בראם<sup data-n=\"4998\">180</sup>, לכן נק' חדש האביב<sup data-n=\"4999\">181</sup> ר\"ת אב י\"ב<sup data-n=\"5000\">182</sup>, הם י\"ב צירופי ה'<sup data-n=\"5001\">183</sup> וא\"ב דכתיב החדש הזה לכם<sup data-n=\"5002\">184</sup> כו' ראשון הוא לכם כו' וכל מקום שנא' לישראל לכם שרשו מלכם שכ\"כ<sup data-n=\"5003\">185</sup>, ובחודש ש'<sup data-n=\"5004\">186</sup> הוי' ככתבו<sup data-n=\"5005\">187</sup> לכן נק' אב ואח\"כ ע\"י בירורים דחמשים יום קבלו התורה<sup data-n=\"5006\">188</sup> בשבועות והו\"ע בעצרת על פה\"א, שהוא בחי' כי אדם עץ השדה<sup data-n=\"5007\">189</sup> לכן הניקוד בחולם, ומ\"מ כתיב בה' שאף בחי' אילן דבעצרת הוא ג\"כ חטה שאז זמן שתי הלחם<sup data-n=\"5008\">190</sup> וחטה גימ' ך\"ב אתוון דאורייתא<sup data-n=\"5009\">191</sup> ומ\"מ נק' אילן צ\"ל",[["4991","173","<b>בראתי בגימ' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש שם (קז, ב בדפי הספר). ”היום יום\" כב חשון בתוך תורת הה\"מ. לקמן הנחה ד\"ה והמים להם חומה על יד הערה 61. ד\"ה תקעו בחדש שופר על יד הערה 44. ובחלק ההנחות שם על יד הערה 54. סה\"מ תרל\"ו ח\"ב ע' תצב. תרל\"ח ע' תנד. וש\"נ. תר\"ם ח\"א ע' רנ. וש\"נ. מאמר ד\"ה רבי אומר תר\"ץ."],["4992","174","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["4993","175","<b>ברך על פר\"א </b> [ פרי אילן]<b> בורא פ\"א</b>: ברכות מ, א (במשנה). שו\"ע אדה\"ז הל' ברכת הפירות סר\"ו, ס\"א. סידור סדר ברכת הנהנין פ\"א, ה\"ד."],["4994","176","<b>לבד איזה פרטים שאינו יוצא</b>: ראה סידור שם ה\"ו [הובא בשו\"ע אדה\"ז שם, ס\"ב]. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 191."],["4995","177","<b>בפסח על התבואה . . פה\"א</b>: ר\"ה פ\"א, מ\"ב (טז, א)."],["4996","178","<b>בפסח . . בישול שעורים</b>: ראה לעיל שם ובהערה 177."],["4997","179","<b>שעורים . . שיעור ה'</b>: ראה זהר בלק קפח, ב."],["4998","180","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["4999","181","<b>חדש האביב</b>: משפטים כג, טו. תשא לד, יח. פ' ראה טז, א."],["5000","182","<b>האביב ר\"ת אב י\"ב</b>: ראה גם לעיל שם ובהערה 178."],["5001","183","<b>י\"ב צירופי ה'</b>: ראה גם שערי אורה [לרי\"ג] שער ה (סה, ב). תניא פמ\"א ובמ\"מ הגהות והע\"ק ולקוטי פירושים לשם. סה\"מ תרל\"ה ח\"א ע' קסו ד\"ה בענין. שיחת אחש\"פ תשמ\"ז (הנחה בלתי מוגה) סי\"א (תו\"מ התוועדויות תשמ\"ז ח\"ג ע' 127). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתב."],["5002","184","<b>החדש הזה לכם</b>: בא יב, ב."],["5003","185","<b>וכל מקום שנא' לישראל לכם . . שכ\"כ </b> [ שכתב כאן]<b></b>: אולי לומד כן הפירוש בשמו\"ר פט\"ו, כג. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830112\" data-slug=\"or-hatorah-hb\" data-id=\"8158830112\">אוה\"ת שלח ע' תרג</a>. מטו\"מ בהוספות ע' א'תקח [נדפס באוה\"ת שלח מהדורת תשנ\"ז בהוספות ע' 112]: ומה שנז' זה ע\"פ החדש הזה לכם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301430243\" data-slug=\"likkutei-sichot\" data-id=\"1301430243\">לקו\"ש</a> פינחס כרך לג ע' 185 הערה 59."],["5004","186","<b>ובחודש ש'</b>: אוצ\"ל: ובחודש ניסן ש'."],["5005","187","<b>ובחודש ניסן ש' הוי' ככתבו</b>: משנת חסידים מסכת ניסן רפ\"א."],["5006","188","<b>ואח\"כ . . דחמשים יום קבלו התורה</b>: ראה שו\"ע אדה\"ז חאו\"ח סדר תפלת חה\"ש סתצ\"ד, ס\"א. סה\"מ תר\"ם ח\"א ע' רז. וש\"נ."],["5007","189","<b>כי אדם עץ השדה</b>: פ' שופטים כ, יט [ושם: האדם]."],["5008","190","<b>דבעצרת . . שתי הלחם</b>: אמור כג, טו ואילך. סהמ\"צ להרמב\"ם מ\"ע מו. רמב\"ם הל' תמידין ומוספין רפ\"ח."],["5009","191","<b>וחטה גימ' ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."]]],[2001910478,"שהוא למ\"ד עה\"ד חטה היתה<sup data-n=\"5010\">192</sup> שהוא אילן וגם חטה, וכדי שיהי' בחי' תבואה צ\"ל ארץ וישראל הם ארץ חפץ שבהם נצמח התבואה לכן נק' ראשית תבואתה. וזהו קדש ישראל לה' שיתעלו בבחי' קדש וכמ\"ש ואנשי קדש תהיון לי<sup data-n=\"5011\">193</sup>, וזהו תכלית ירידת הנשמה בגוף כדי שיבוא לבחי' קדש, ותחילה צ\"ל בחי' ארץ חפץ כדי שיהי' צמיחת התבואה ואח\"כ קדש ישראל לה' שיתעלו לבחי' קדש העליון ואנשי קדש תהיון לי כו'.\nש\"פ וארא לא נאמר",[["5010","192","<b>עה\"ד חטה היתה</b>: ברכות מ, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380147\" data-slug=\"likkutei-torah\" data-id=\"4001380147\">לקו\"ת צו יז, ד</a>. מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["5011","193","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל."]]],[2001910479,"<h3>הוא אהרן ומשה</h3>\n<b>ש\"פ בא תאמ\"ר לפ\"ק</b>\n<b>הוא</b> אהרן ומשה<sup data-n=\"5012\">1</sup> אשר אמר ה' להם הוציאו את בנ\"י מאמ\"צ<sup data-n=\"5013\">2</sup> כו' הם המדברים כו' הוא משה ואהרן<sup data-n=\"5014\">3</sup> ואי' בזהר<sup data-n=\"5015\">4</sup> למה או' הוא ולא הם, גם צ\"ל שבתחלה א' הוא אהרן ומשה משמע דאהרן העיקר ובאמת ביצי\"מ הי' העיקר משה, ותירץ רבינו ז\"ל דלהוציא בנ\"י מאמ\"צ העיקר ע\"י אהרן וז\"ש הוא אהרן ומשה כו' הוציאו בנ\"י כו' אך לדבר אל פרעה משה העיקר<sup data-n=\"5016\">5</sup> וז\"ש הם המדברים כו' הוא משה ואהרן, והנה להבין זה צ\"ל תחילה מ\"ש בריש הפרשה ואלה ראשי בית אבותם וחשיב ראובן ושמעון ולוי ופירש\"י<sup data-n=\"5017\">6</sup> מפני שקנתרם<sup data-n=\"5018\">7</sup> יעקב לפני מותו לכן חזר וייחסם כאן להודיע שהם חשובים. ובפ\"י<sup data-n=\"5019\">8</sup> פי' שהוא להודיע שמשה הוא דור שביעי לאברהם וכל השביעין חביבין<sup data-n=\"5020\">9</sup> כמו בימים הז' שבת וכתי' ויברך אלקים את יום השביעי ויקדש אותו<sup data-n=\"5021\">10</sup>, בחדשים כתי' ובחדש השביעי באחד לחדש<sup data-n=\"5022\">11</sup> שבו ר\"ה ויוהכ\"פ וסוכות, בשנה כתי' ובשנה השביעית שבת שבתון יהי' לארץ<sup data-n=\"5023\">12</sup> והוא שנת השמיטה, וא\"כ הרי משה לגבי",[["5012","1","<b>הוא אהרן ומשה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nהנחה זו הובא בהנחה שלאח\"ז ד\"ה אז ישיר משה על יד הערה 23."],["5013","2","<b>הוא אהרן ומשה . . מאמ\"צ</b>: וארא ו, כו."],["5014","3","<b>הם המדברים . . משה ואהרן</b>: שם ו, כז."],["5015","4","<b>הוא אהרן ומשה . . ואי' בזהר</b>: וארא כו, ב. כז, א (אוה\"ת וארא ע' רכו)."],["5016","5","<b>רבינו ז\"ל . . אל פרעה משה העיקר</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכב ואילך. ע' קלג (תקס\"ב ח\"א ס\"ע רצא ואילך). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540801\" data-slug=\"torat-chaim\" data-id=\"2300540801\">תו\"ח וארא ח\"א פב, ב</a>. אוה\"ת שם ע' רכה."],["5017","6","<b>ואלה ראשי בית אבותם . . ופירש\"י</b>: וארא ו, יד [ושם: אלה]. פסיקתא רבתי פסקא ז ויהי המקריב. וראה רשב\"ם בשם המכילתא. ראה גם אוה\"ת וארא ע' רח."],["5018","7","<b>שקנתרם</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 8."],["5019","8","<b>ובפ\"י</b>: ובספר פנים יפות — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 11."],["5020","9","<b>וכל השביעין חביבין</b>: ויק\"ר פכ\"ט, יא."],["5021","10","<b>ויברך אלקים . . ויקדש אותו</b>: בראשית ב, ג."],["5022","11","<b>ובחדש השביעי באחד לחדש</b>: פינחס כט, א."],["5023","12","<b>ובשנה השביעית . . יהי' לארץ</b>: בהר כה, ד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 15."]]],[2001910480,"אברהם כמו שבת<sup data-n=\"5024\">13</sup> לגבי ששת יומין דחול, וצ\"ל הלא מצינו מדרש סותר לזה דאי' במדרש<sup data-n=\"5025\">14</sup> ע\"פ אל תקרב הלום<sup data-n=\"5026\">15</sup> במקום גדולים אל תעמוד<sup data-n=\"5027\">16</sup>, דאברהם א' הנני<sup data-n=\"5028\">17</sup> לכהונה ומל' ומשה א' ג\"כ הנני<sup data-n=\"5029\">18</sup> א\"ל הקב\"ה במקום גדולים אל תעמוד, הרי אברהם למעלה במדריגה ממשה. והנה יובן זה מאופני הגילוים דהנה כתי' וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי ה' לא נודעתי להם<sup data-n=\"5030\">19</sup> וידוע הקושי' דהרי מצינו שם ה' גם גבי האבות דכתי' ויאמר ה' אל אברם<sup data-n=\"5031\">20</sup> הרי גם כשנק' אברם כתי' בי' הוי' וירא אליו הוי'<sup data-n=\"5032\">21</sup>, וכתי' אלה תולדות השמים והארץ בהבראם<sup data-n=\"5033\">22</sup> באברהם<sup data-n=\"5034\">23</sup>, וכתי' ביום עשות הוי' אלקים<sup data-n=\"5035\">24</sup> ארץ ושמים. והנה צ\"ל תחילה ביאור ב' שמות אלו הוי' ואלקים*, הנה אלקים ל' רבים<sup data-n=\"5036\">26</sup> וכמ\"ש אלקים קדושים<sup data-n=\"5037\">27</sup>, והוי' אחד, וצ\"ל מהו\"ע אלקים רבים. והענין דהנה כתי' גדול ה' ומהולל מאד<sup data-n=\"5038\">28</sup> ולגדולתו אין חקר ולכאורה אינו מובן דתחילה אמר ומהולל מאד משמע דשייך הילול בה' ואח\"כ אמר ולגדולתו אין חקר.\n<b>אך</b> הנה ארז\"ל אימתי הוא גדול כשהוא בעיר אלקינו<sup data-n=\"5039\">29</sup>, דבהוי' עצמו הרי לית מח' תפיסא בי'<sup data-n=\"5040\">30</sup> כלל אך בשם אלקים ניכר התפשטות גדולתו, וענין עיר אלקינו הוא כללות עולם הדיבור כמו העיר שהוא קיבוץ בתים הרבה ובית הוא קיבוץ אבנים הרבה כמו\"כ האותיות נק' אבנים דכמו האבן דומם כמו\"כ האותיות דוממים<sup data-n=\"5041\">31</sup> וצירופי אותיות נק' בית, וכללות עולם הדיבור נק' עיר אלקינו, ומ\"מ ולגדולתו אין\n\n*)בשולי היריעה בצד השמאלי של הגליון נרשם כאן:\nתו\"א דנ\"ח ע\"ב",[["5024","13","<b>משה לגבי אברהם כמו שבת</b>: ראה גם אוה\"ת וארא ע' רכח. תשא ע' ב'יט. לקמן בסיום המאמר."],["5025","14","<b>דאי' במדרש</b>: ב\"ר פנ\"ה, ו. שמו\"ר ספ\"ב."],["5026","15","<b>אל תקרב הלום</b>: שמות ג, ד."],["5027","16","<b>במקום גדולים אל תעמוד</b>: משלי כה, ו [ושם: ובמקום]."],["5028","17","<b>דאברהם א' הנני</b>: וירא כב, א."],["5029","18","<b>ומשה א' ג\"כ הנני</b>: שמות ג, ד."],["5030","19","<b>וארא . . לא נודעתי להם</b>: וארא ו, ג. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 24."],["5031","20","<b>ויאמר ה' אל אברם</b>: לך יב, א."],["5032","21","<b>וירא אליו הוי'</b>: וירא יח, א. כתוב זה הוא לאחר שנק' אברהם — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 25."],["5033","22","<b>אלה תולדות השמים והארץ בהבראם</b>: בראשית ב, ד."],["5034","23","<b>בהבראם באברהם</b>: ב\"ר פי\"ב, ט. זהר לך פו, ב ובדרך אמת אות א. שמיני לח, א. ראה גם סה\"מ תרל\"ו ח\"ב ע' רנב."],["5035","24","<b>ביום עשות הוי' אלקים</b>: בראשית ב, ד."],["5036","26","<b>אלקים ל' רבים</b>: רש\"י וירא כ, יג. וישלח לה, ז. ראה (בנוסף לתו\"א כאן) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540095\" data-slug=\"torat-chaim\" data-id=\"2300540095\">תו\"ח וארא ס, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380212\" data-slug=\"likkutei-torah\" data-id=\"4001380212\">לקו\"ת אמור לא, ג</a>. אוה\"ת וארא ע' רכג. סה\"מ פר\"ת כאן ע' רלא."],["5037","27","<b>אלקים קדושים</b>: יהושע כד, יט."],["5038","28","<b>גדול ה' ומהולל מאד</b>: תהלים קמה, ג."],["5039","29","<b>אימתי הוא גדול כשהוא בעיר אלקינו</b>: תהלים מח, ב. ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ."],["5040","30","<b>לית מח' תפיסא בי'</b>: ת\"ז בהקדמה יז, א."],["5041","31","<b>האותיות נק' אבנים . . דוממים</b>: ראה ס\"י פ\"ד, מי\"ב. מאמרי אדה\"א נ\"ך ע' תקלב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א ויצא כב, א</a>. תו\"ח שם קסד, סע\"א ואילך."]]],[2001910481,"חקר דאף דמה רבו מעשיך ה'<sup data-n=\"5042\">32</sup> ומה גדלו מעשיך<sup data-n=\"5043\">33</sup> מ\"מ אינם בערך לגבי בחי' מאד עמקו מחשבותיך. וענין מה רבו מעשיך הם ריבוי הנבראים<sup data-n=\"5044\">34</sup> דצח\"ם<sup data-n=\"5045\">35</sup> ובהם יש ג\"כ כמה מינים כמו באילן יש תפוחים ואגוזים שטעמם משונה, ושקדים יש להם טעם אחר, ושרש הטעמים הוא מהמזל כאמרז\"ל אין לך עשב<sup data-n=\"5046\">36</sup> מלמטה שאין לו מזל למעלה המכה בו ואומר לו גדל, וכללות החיות נמשך מפסולת דתענוג העליון וכמ\"ש וכל קרבי שם קדשו<sup data-n=\"5047\">37</sup> שיש קרביים עליונים שמבררי', והפסולת הוא החיות מכל התענוגים גשמים וז\"ש נטה ימינו וברא שמים<sup data-n=\"5048\">38</sup> נטה שמאלו וברא ארץ הרי ארץ מבחי' שמאל ולכן ר\"ע כשראה כרך גדול של רומי כו' שחק אם לעוברי רצונו<sup data-n=\"5049\">39</sup> כך נמשך מחיצוניות תענוג העליון לעושי רצונו שיומשך מפנימיות תענוג העליון עאכו\"כ. מה גדלו מעשיך הם גדולי הנבראים<sup data-n=\"5050\">40</sup>, נשמות ומלאכים ובזה יש ג\"כ ריבוי מד' דאמרז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות<sup data-n=\"5051\">41</sup> ולכאו' מה צריך הצדיק ש\"י עולמות, והענין דהנה קנ\"ה חכ' וקנ\"ה בינה<sup data-n=\"5052\">42</sup> בגימ' יש<sup data-n=\"5053\">43</sup> וזהו להנחיל אוהבי יש<sup data-n=\"5054\">44</sup> דתרי\"ג מצות דאורייתא וז\"מ דרבנן הם תר\"ך<sup data-n=\"5055\">45</sup> ומה שיכול להגלה<sup data-n=\"5056\">46</sup> הוא מחצה התחתון דכתר וזהו ש\"י אורות מכ\"ע והם זיו תורתן ועבודתן<sup data-n=\"5057\">47</sup> והש\"י עולמות שנמשכים מבחי' חו\"ב הם כלים לש\"י אורות אלו, לכן כל צדיק יש לו מדור לפי כבודו<sup data-n=\"5058\">48</sup> לפ\"ע עבודה דעוה\"ז, וזהו אלקים ל' רבים שיש בזה ריבוי מד', וגם אהוי\"ר דעוה\"ז הם מש' אלקים דביראה כתיב אלקים עשה שיראו מפניו<sup data-n=\"5059\">49</sup> וכתי' את אלקי' ירא<sup data-n=\"5060\">50</sup>, את הוי' אלקיך תירא<sup data-n=\"5061\">51</sup> דכשהוי' דלית מח' תפיסא בי' נמשך ע\"י בחי' אלקיך",[["5042","32","<b>דמה רבו מעשיך ה'</b>: תהלים קד, כד."],["5043","33","<b>ומה גדלו מעשיך</b>: שם צב, ו."],["5044","34","<b>מה רבו . . ריבוי הנבראים</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תצד. וש\"נ."],["5045","35","<b>ריבוי הנבראים דצח\"ם</b>: ראה גם סה\"מ תר\"ם ח\"א ע' י. וש\"נ."],["5046","36","<b>אין לך עשב</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג."],["5047","37","<b>וכל קרבי שם קדשו</b>: תהלים קג, א [בהשמטת תיבת את]. ראה גם שע\"ת סט, א ובהנסמן במ\"מ לשם."],["5048","38","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א כאן בפנים. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א ובהערה 81."],["5049","39","<b>ר\"ע . . אם לעוברי רצונו</b>: ראה מכות בסופה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380445\" data-slug=\"likkutei-torah\" data-id=\"4001380445\">לקו\"ת בהעלותך לג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">שלח מז, א</a>."],["5050","40","<b>מה גדלו . . גדולי הנבראים</b>: ראה לעיל הערה 35."],["5051","41","<b>עתיד . . ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["5052","42","<b>קנ\"ה חכ' וקנ\"ה בינה</b>: משלי ד, ה [ושם: קנה]."],["5053","43","<b>קנ\"ה . . בגימ' יש</b>: ראה פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, סע\"א]. שער יוה\"כ שכ\"ז, פ\"ה. שער הפסוקים משלי ס\"ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרס. תקע\"א ע' עה. מאמרי אדה\"א דברים ח\"א ע' טז. וש\"נ. אוה\"ת בהעלותך ע' תטז."],["5054","44","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["5055","45","<b>דתרי\"ג . . וז\"מ . . תר\"ך</b>: ראה לעיל הנחה ד\"ה קדש ישראל לה' הערות 131-135."],["5056","46","<b>להגלה</b>: אינו ברור בצילום גוכתי\"ק."],["5057","47","<b>זיו תורתן ועבודתן</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a>."],["5058","48","<b>כל צדיק . . לפי כבודו</b>: ראה שבת קנב, א. רו\"ר פ\"ג, ד."],["5059","49","<b>אלקים עשה שיראו מפניו</b>: קהלת ג, יד [ושם: והאלקים . . מלפניו]."],["5060","50","<b>את אלקי' ירא</b>: קהלת יב, יג [ושם: האלקים]."],["5061","51","<b>את הוי' אלקיך תירא</b>: ואתחנן ו, יג. עקב י, כ."]]],[2001910482,"אז שייך ירא ה' א\"כ אפילו יראה בשת<sup data-n=\"5062\">52</sup> הוא ע\"י שם אלקים, וכן אהבה כתי' הללוהו בגבורותיו<sup data-n=\"5063\">53</sup> הללוהו כרוב גודלו וכן כתי' ואהבת את הוי' אלקיך<sup data-n=\"5064\">54</sup> שהוי' דלית מח' תפיסא בי' יהי' בבחי' אלקיך ומזה יהי' אהבה, וזהו וארא אל אברהם אל יצחק ואל יעקב באל שדי, אברהם יצחק יעקב<sup data-n=\"5066\">56</sup> הם חו\"ג ורחמים<sup data-n=\"5065\">55</sup> ולכן יש לכל ישראל ג' בחי' אלו בירושה מאבותינו<sup data-n=\"5067\">57</sup>.\n<b>אך</b> הנה יש ב' בחי' דהנה כתי' הנך יפה רעיתי<sup data-n=\"5068\">58</sup> הנך יפה עיניך יונים, יפה הוא שיש בו ג' גוונים<sup data-n=\"5069\">59</sup> דבגוון א' אינו שייך יופי כ\"א התכללות ג' גוונים וזהו אהוי\"ר ורחמים, ויש אהוי\"ר מלמטלמ\"ע<sup data-n=\"5070\">60</sup> וזהו הנך יפה רעיתי ויש אהוי\"ר ורחמים מלמעלמ\"ט וזהו הנך יפה עיניך יונים, ולחבר אהוי\"ר ורחמים דלמעלה באהוי\"ר דלמטה זהו באל שדי דהשין ג' קוי\"ן<sup data-n=\"5071\">61</sup> מורה על בחי' אהוי\"ר ורחמים וד' י' הוא משארז\"ל שאמר לעולמו די<sup data-n=\"5072\">62</sup> והוא מקור הנבראים ה\"ה מחבר ב' בחי' הנ\"ל, וזהו היא מתהלכת בין החיות<sup data-n=\"5073\">63</sup>, דיש חיון עילאין וחיון תתאין<sup data-n=\"5074\">64</sup>, חיון תתאה הוא מרכבתא דאבות הן המרכבה<sup data-n=\"5076\">66</sup> דאבות עצמן הם בבריאה<sup data-n=\"5077\">67</sup>, וחיון עילאין הוא מרכבתא עילאה<sup data-n=\"5075\">65</sup> דאצי', ולחבר ב' בחי' אלו זהו היא מתהלכת בין החיות הוא בחי' מל'<sup data-n=\"5078\">68</sup> שמחבר ב' בחי' אלו. וב' בחי' יופי בעבודה הם פסוד\"ז וק\"ש, פסוד\"ז הוא בחי' גדול ה' ומהולל מאד, וק\"ש הוא אהוי\"ר הבאה מלמעלה.\n<b>ועפ\"ז</b> יובן הגם דגבי אבות כתי' ג\"כ הוי' אך הוא ע\"י שם אלקים וזהו ביום עשות הוי' אלקים ארץ ושמים וכמ\"ש שמש ומגן ה' אלקים<sup data-n=\"5079\">69</sup> כמו המגן שמכסה",[["5062","52","<b>יראה בשת</b>: ראה ת\"ז בהקדמה ה, ב. תכ\"ח. מאמרי אדה\"א בראשית ע' מ."],["5063","53","<b>הללוהו בגבורותיו</b>: תהלים קנ, ב."],["5064","54","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה. עקב יא, א."],["5066","56","<b>יעקב . . ורחמים</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["5065","55","<b>אברהם יצחק יעקב הם חו\"ג ורחמים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 74."],["5067","57","<b>חו\"ג ורחמים . . בירושה מאבותינו</b>: ראה גם תו\"א ר\"פ וארא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540608\" data-slug=\"torat-chaim\" data-id=\"2300540608\">תו\"ח וארא ח\"א סה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540732\" data-slug=\"torat-chaim\" data-id=\"2300540732\">סח, א</a>."],["5068","58","<b>הנך יפה רעיתי</b>: שה\"ש א, טו. ד, א."],["5069","59","<b>יפה . . ג' גוונים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 79."],["5070","60","<b>אהוי\"ר מלמטלמ\"ע</b>: אוצ\"ל: אהוי\"ר ורחמים מלמטלמ\"ע."],["5071","61","<b>דהשין ג' קוי\"ן</b>: ראה מאו\"א מערכת אות השי\"ן ס\"א וביאיר נתיב שם."],["5072","62","<b>שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["5073","63","<b>היא מתהלכת בין החיות</b>: יחזקאל א, יג."],["5074","64","<b>חיון עילאין וחיון תתאין</b>: ראה זהר ויקהל ריא, א. ריג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">סידור שחרית סד, א</a>. ביאוה\"ז בשלח מב, סע\"ב ואילך. ויקרא סב, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שט. מאמרי אדה\"א ויקרא ח\"ב ע' תסט ואילך."],["5076","66","<b>דאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["5077","67","<b>דאבות עצמן הם בבריאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540348\" data-slug=\"torat-chaim\" data-id=\"2300540348\">תו\"ח וארא ח\"א סב, א</a> ובהנסמן שם. (לעיל בחלק המאמרים) מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 72."],["5075","65","<b>מרכבתא דאבות . . מרכבתא עילאה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 86."],["5078","68","<b>היא . . מל'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 92."],["5079","69","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א ויצא כא, ד</a>. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."]]],[2001910483,"ומסתיר על אור השמש כמו\"כ שם אלקים מכסה ומסתיר על אור ה' וקדושתו, אבל ושמי הוי' קודם התלבשותו לא נודעתי להם כ\"א ביצי\"מ מ\"ת<sup data-n=\"5080\">70</sup> דכתי' לכן אמור לבנ\"י<sup data-n=\"5081\">71</sup> אני הוי', וידעו מצרים כי אני הוי'<sup data-n=\"5082\">72</sup>, דכתי' מה יתרון לאדם בכל עמלו שיעמול תחת השמש, שאני עמלא דאורייתא דלעילא משמשא<sup data-n=\"5083\">73</sup> שלמעלה מבחי' שמש ה' שמתלבש בהמגן ונרתק.\n<b>וביאור</b> הענין דהנה אי' במאמר אלי' אנת הוא חכים ולא בחכ' ידיעא מבין ולא בבינה ידיעא כו' וחשיב חסד דרועא ימינא כו' ואח\"כ אמר ולאו מכל אילין מדות איהו כלל<sup data-n=\"5084\">74</sup>, ולכאורה הול\"ל ולאו מכל אילין חו\"ב איהו כלל. והענין דהנה מדות הם שייכים לזולת<sup data-n=\"5085\">75</sup> דכשיש על מי להתרחם ועל מי להתחנן שייך רחום וחנון<sup data-n=\"5086\">76</sup> וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"5087\">77</sup> רחמים וחסדים הם שייכים לעולמות, וכתי' כי אמרתי עולם חסד יבנה ויש בזה ב\"פ<sup data-n=\"5088\">78</sup> א' שצריך לבנות העולם במידת החסד ב' שכדי לברוא העולם צריכים לבנות מדת החסד, הרי שהמדות שייכים לזולת, משא\"כ מוחין אינם שייכים לעולם כמובן, וזהו\"ע האבות שהם מדות אבל בחי' ה' בחכ'<sup data-n=\"5089\">79</sup> לא נתגלה להם דבתומ\"צ מתגלה עצם החכ' דכתי' הראיני נא את כבודך<sup data-n=\"5090\">80</sup> כו'<sup data-n=\"5091\">81</sup> וראית את אחורי<sup data-n=\"5092\">82</sup> ופני לא יראו, קשר של תפילין הראה לו<sup data-n=\"5093\">83</sup>, שביקש הראיני נא את כבודך הוא בחי' ח\"ע<sup data-n=\"5094\">84</sup> והוא בחי' תפילין דאמרז\"ל תפילין דמארי עלמא<sup data-n=\"5095\">85</sup>, מארי עלמא הם מדות ותפילין דמארי עלמא הו\"ע המשכת מוחין למדות, וכן הקב\"ה מניח תפילין<sup data-n=\"5096\">86</sup> קב\"ה הוא בחי' ז\"א ומל' מניח תפילין הוא",[["5080","70","<b>מ\"ת</b>: אוצ\"ל: ומ\"ת."],["5081","71","<b>לכן אמור לבנ\"י</b>: וארא ו, ו."],["5082","72","<b>וידעו מצרים כי אני הוי'</b>: וארא ז, ה. ועוד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 94."],["5083","73","<b>מה יתרון לאדם . . דלעילא משמשא</b>: קהלת א, ג. זהר ויחי רכג, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540452\" data-slug=\"torat-chaim\" data-id=\"2300540452\">תו\"ח וארא ח\"א סג, סע\"ב</a> ואילך ובהנסמן בריש המאמר שם."],["5084","74","<b>אנת הוא חכים . . ולאו . . כלל</b>: ראה ת\"ז בהקדמה יז, ב [בהוספת תיבת: הוא — כ\"ה בסידור אדה\"ז סדר מנחת ערב שבת. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 101]."],["5085","75","<b>מדות הם שייכים לזולת</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה־ ח\"ב ע' תקז. וש\"נ."],["5086","76","<b>רחום וחנון</b>: תשא לד, ו. תהלים פו, טו. קג, ח."],["5087","77","<b>זכור רחמיך . . המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 32 ואילך. לקמן בהנחה שם על יד הערה 27. ובחלק ההנחות שם על יד הערה 32."],["5088","78","<b>כי אמרתי . . ב\"פ</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערות 105-106."],["5089","79","<b>ה' בחכ'</b>: לשון הכתוב משלי ג, יט."],["5090","80","<b>הראיני נא את כבודך</b>: תשא לג, יח."],["5091","81","<b>כו'</b>: כ\"ה בגוכתי\"ק."],["5092","82","<b>וראית את אחורי</b>: תשא שם, כג."],["5093","83","<b>קשר של תפילין הראה לו</b>: ראה ברכות ז, א."],["5094","84","<b>כבודך . . ח\"ע</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 115 ואילך."],["5095","85","<b>תפילין דמארי עלמא</b>: ראה ברכות ו, א. סה\"מ מלוקט ב' ע' פז הערה 10."],["5096","86","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ובהערה 126."]]],[2001910484,"המשכת מוחין בז\"א, וא\"ל כי לא יראני אדם וחי<sup data-n=\"5097\">87</sup> וראית את אחורי קשר של תפילין הראה לו הוא בחי' מל' דתבונה<sup data-n=\"5098\">88</sup>, וישראל כשמניח תפילין ה\"ה ממשיך בחי' זו שלא השיג משה בבחי' ראי' כ\"א כשהניח תפילין הרי לא גרע מכל ישראל אבל בבחי' ראי' לא השיג וכ\"ש שהאבות לא השיגו בחי' זו, וישראל ע\"י שמניחים ממשיכים בחי' זו.\n<b>ועפ\"ז</b> מ\"ש<sup data-n=\"5099\">*89</sup> הוא אהרן ומשה דביצי\"מ העיקר אהרן, דאהרן הוא שושבינא דמטרוניתא<sup data-n=\"5100\">89</sup> שמעלה נש\"י לכן להוציא מאמ\"צ הם המצרים וגבולים<sup data-n=\"5101\">90</sup> הוא ע\"י אהרן, אך לדבר אל פרעה משה העיקר שהוא שושבינא דמלכא<sup data-n=\"5102\">91</sup>, דפרעה אותיות הערף<sup data-n=\"5103\">92</sup> לכן יצא בגסות וגיאות וא' מי הוי' אשר אשמע בקולו, לא ידעתי את הוי'<sup data-n=\"5104\">93</sup>, וכדי להשפיל הגיאות צריכים להמשיך מבחי' כי גאה גאה שמתגאה על גותניא<sup data-n=\"5105\">94</sup>, וכדי להמשיך בחי' הוא<sup data-n=\"5106\">95</sup> ע\"י משה שהוא בחי' ביטול דחכ'<sup data-n=\"5107\">96</sup> הוא כח מ\"ה<sup data-n=\"5108\">97</sup> אחד האמת שבו שורה אוא\"ס* ומשה הי' ג\"כ בחי' מה כמ\"ש ואנחנו מ\"ה<sup data-n=\"5109\">98</sup> לכן הי' כלי לבחי' כי גאה גאה, הגם דואנחנו מ\"ה קאי גם על אהרן אך אהרן הי' ב\"ן דמ\"ה ומשה מ\"ה דמ\"ה<sup data-n=\"5110\">99</sup>, לכן לדבר אל פרעה כתי' הוא משה ואהרן. ומ\"ש הוא ולא הם, הענין דלאחר החטא כתי' את המאור הגדול ואת המאור הקטן וזהו\"ע הוי' ואלקים<sup data-n=\"5111\">100</sup>, אבל\n\n*)על גליון היריעה בצד הימיני של שורה זו נרשם:\nסש\"ב פי\"ח",[["5097","87","<b>כי לא יראני אדם וחי</b>: תשא לג, כ [ושם: האדם]."],["5098","88","<b>קשר של תפילין . . מל' דתבונה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 122."],["5099","*89","<b>ועפ\"ז מ\"ש</b>: אוצ\"ל: ועפ\"ז יובן מ\"ש."],["5100","89","<b>דאהרן הוא שושבינא דמטרוניתא</b>: ראה זהר רע\"מ ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["5101","90","<b>מאמ\"צ הם המצרים וגבולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["5102","91","<b>משה . . שושבינא דמלכא</b>: ראה זהר שם. מצורע נג, ב. רע\"מ שופטים ערה, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a> הערה 510."],["5103","92","<b>דפרעה אותיות הערף</b>: ראה לקו\"ת להאריז\"ל שמות עה\"פ (א, ח) ויקם מלך חדש בתחילתו. שער הפסוקים פ' וישב (לט, א) סט\"ל. סה\"מ תר\"ם ח\"ב ע' תרנה. וש\"נ."],["5104","93","<b>מי הוי' . . את הוי'</b>: שמות ה, ב."],["5105","94","<b>כי גאה . . על גותניא</b>: בשלח טו, א. ראה ת\"א שם."],["5106","95","<b>בחי' הוא</b>: אוצ\"ל: בחי' זו הוא."],["5107","96","<b>משה . . דחכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["5108","97","<b>דחכ' הוא כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["5109","98","<b>ואנחנו מ\"ה</b>: בשלח טז, ז. ח [ושם: ונחנו — אבל עד\"ז מובא בעוד מקומות ומהם: לקמן הנחה ד\"ה את חג המצות תשמור על יד הערה 70 (ובחלק ההנחות שם על יד הערה 78). ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 76. הנסמן בסה\"מ תר\"ם ח\"א ע' שטו].\nראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ."],["5110","99","<b>אהרן הי' ב\"ן דמ\"ה ומשה מ\"ה דמ\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370444\" data-slug=\"torah-or\" data-id=\"3901370444\">תו\"א מג\"א צט, ג</a>. אוה\"ת תצוה ע' א'תרו. ע' א'תרכג. סה\"מ תר\"ם ח\"א ע' קעח. וש\"נ."],["5111","100","<b>את המאור הגדול . . הקטן . . הוי' ואלקים</b>: בראשית א, טז [בדילוג]. זהר בראשית כ, א."]]],[2001910485,"קודם החטא כתי' את שני המאורות הגדולים<sup data-n=\"5112\">101</sup> והו\"ע מ\"ש וידעת היום<sup data-n=\"5113\">102</sup> והשבת אל לבבך כי הוי' הוא אלקים כולא חד<sup data-n=\"5114\">103</sup>, ולכן גבי משה ואהרן כתי' הוא שהוא בחי' כולא חד (אפ\"ל אהרן ב\"ן דמ\"ה ומשה מ\"ה דמ\"ה כנ\"ל זהו\"ע הוי' ואלקים וכתי' הוא להורות דכולא חד).\n<b>אך</b> עדיין צ\"ל דמשמע דמשה לגבי אברהם הוא כמו שבת לגבי חול ובאמת אי' במדרש אל תקרב הלום במקום גדולים אל תעמוד, והנה להבין ההפרש בין משה ואברהם צ\"ל תחילה ההפרש בין אברהם ואהרן, דאברהם הי' מרכבה לבחי' חסד<sup data-n=\"5115\">104</sup> וגם אהרן הי' בחי' חסד<sup data-n=\"5116\">105</sup> ואי' בזהר אית חסד ואית חסד<sup data-n=\"5117\">106</sup> אית חסד דאיקרי חסד עולם ואית חסד דאיקרי רב חסד<sup data-n=\"5118\">107</sup>, והנה גבי אברהם כתי' הלוך ונסוע הנגבה<sup data-n=\"5119\">108</sup> שהמשיך א\"ע<sup data-n=\"5120\">109</sup> לבחי' מנורה בדרום<sup data-n=\"5121\">110</sup>, ואהרן להיכן שאברהם המשיך א\"ע שם התחיל ואדרבה כתי' בהעלותך את הנרות<sup data-n=\"5122\">111</sup> שהעלה את הנרות, והנה כתי' אלה תולדות השמים והארץ בהבראם תולדות מלא ו' כתי' דעולם על מילואו נברא<sup data-n=\"5124\">113</sup> אך אדה\"ר ע\"י חטא עה\"ד נחסר הו'<sup data-n=\"5123\">112</sup>, אך בהבראם הוא אברהם וכתי' מלא ו' היינו שהמשיך בחי' ו' הוא בחי' מדות שהודיע אלקותו בעולם<sup data-n=\"5125\">*114</sup>, ולכן הוא בחי' חסד עולם שהמשיך בחי' חסד בעולם, וזהו ששת יומין דחול דכל יומא ויומא עביד עבידתא<sup data-n=\"5126\">114</sup>, אבל משה הוא בחי' שבת שהוא שביעי שהוא בחי' בינה<sup data-n=\"5127\">115</sup>",[["5112","101","<b>את שני המאורות הגדולים</b>: בראשית שם. ראה רש\"י שם מחולין ס, ב."],["5113","102","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם סה\"מ תר\"ם ח\"א ע' קט ואילך."],["5114","103","<b>כי הוי' הוא אלקים כולא חד</b>: ראה זהר בהקדמה יב, א. וארא כו, ב. תרומה קסא, א ואילך. רע\"מ ואתחנן רסד, א. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540095\" data-slug=\"torat-chaim\" data-id=\"2300540095\">תו\"ח וארא ח\"א ס, א</a>. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ."],["5115","104","<b>דאברהם . . חסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["5116","105","<b>אהרן . . חסד</b>: ראה ת\"י ברכה לג, ח. שמו\"ר פ\"ה, י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540198\" data-slug=\"torat-chaim\" data-id=\"2300540198\">תו\"ח שמות ח\"א לז, ג</a>. וש\"נ."],["5117","106","<b>אית חסד ואית חסד</b>: זהר אד\"ר נשא קלג, ב. ראה אגה\"ק ס\"י. סוסי\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעז. וש\"נ."],["5118","107","<b>דאיקרי רב חסד</b>: שם אמר חסד דלגאו אך פשוט דר\"ל רב חסד דהרי פי' זה על תיקון השישי מי\"ג מדה\"ר שהוא ורב חסד — אוה\"ת תצוה ע' א'תקפז [ושם מציין: דקל\"ז ע\"ב. וכנשצ\"ל כבהערה שלפנ\"ז: קלג, ב]."],["5119","108","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר לך פ, א. פד, א. אוה\"ת לך כרך ד ע' 1398."],["5120","109","<b>א\"ע</b>: את עצמו."],["5121","110","<b>מנורה בדרום</b>: תרומה כו, לה. פקודי מ, כד. יומא לג, ריש ע\"ב."],["5122","111","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה אוה\"ת וארא ע' קמד."],["5124","113","<b>דעולם על מילואו נברא</b>: ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם). ראה גם תו\"ח ח\"ש קלד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש בראשית כרך כה ע' 14</a> ואילך."],["5123","112","<b>אלה תולדות . . מלא ו' . . נחסר הו'</b>: ראה ב\"ר פי\"ב, ו. לקמן הנחה ד\"ה כי תבואו וכו' ושבתה הארץ ובהערה 101."],["5125","*114","<b>שהודיע אלקותו בעולם</b>: ראה סוטה י, ריש ע\"ב. רמב\"ם הל' ע\"ז ספ\"א."],["5126","114","<b>דכל יומא . . עבידתא</b>: ראה זהר ויגש רה, סע\"א. אמור צד, ריש ע\"ב. השמטות לזח\"א רסד, ב."],["5127","115","<b>שביעי . . בינה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 150."]]],[2001910486,"ושבתא דיומא<sup data-n=\"5128\">116</sup> בחי' מוחין דאבא<sup data-n=\"5129\">117</sup>, אך א\"כ הרי ג\"כ שביעי וצ\"ל ההפרש כמו בין יו\"ט לשבת<sup data-n=\"5130\">118</sup>, דיו\"ט בעצם הוא מוחין דאימא רק שהוא מקרא קדש<sup data-n=\"5131\">119</sup> שקוראין וממשיכים מבחי' קדש, ושבת הוא עצם קדש כי קדש הם<sup data-n=\"5132\">120</sup>, בחי' מוחין דאבא, הרי שמשה למעלה במד' מאברהם, ומ\"מ א\"ל אל תקרב הלום כו' דמשה שהי' בחי' קדש נתנו לו במתנה וכמ\"ש לך רד כלום נתתי<sup data-n=\"5133\">121</sup> לך גדולה אלא בשביל ישראל ונטלו ממנו אלף<sup data-n=\"5134\">122</sup> ובשבת ניתנו לו במתנה, אך באברהם הי' זה ע\"י עבודתו וכמ\"ש התהלך לפני והי' תמים<sup data-n=\"5135\">123</sup>, הגם דגבי נח כתי' ג\"כ את האלקים התהלך נח<sup data-n=\"5136\">124</sup> הרי את האלקים כתי' שהי' צריך סיוע אבל גבי אברהם כתי' התהלך כו' מעצמו לכן אחד הי' אברהם<sup data-n=\"5137\">125</sup> ונק' אדם הגדול בענקים<sup data-n=\"5138\">126</sup>, ועפ\"ז יובן אף שמשה הי' למעלה במדרי' מאברהם אך הי' זה בדרך מתנה אבל אברהם הי' ע\"י עבודתו הגיע למדרי' זו, לכן אחד הי' אברהם ונק' אדם הגדול בענקים כו'.\n\nנרשם בשולי היריעה ולא נסמן מקומו בפנים:\nדיש דחילו ורחימא ורחימו ודחילו, דחילו ורחימו בחי' ו\"ה [וזהו מדרי' האבות] ורחימו ודחילו י\"ה [וזהו מדרי' משה].",[["5128","116","<b>ושבתא דיומא</b>: זהר בהקדמה ה, ב."],["5129","117","<b>ושבתא . . מוחין דאבא</b>: ראה בהערה שלאח\"ז."],["5130","118","<b>ההפרש כמו בין יו\"ט לשבת</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">בחוקותי מז, ג</a>. שע\"ת צח, ב (בשם הע\"ח). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. סה\"מ תרכ\"ז ע' תפט. וש\"נ."],["5131","119","<b>מקרא קדש</b>: בא יב, טז. ועוד."],["5132","120","<b>כי קדש הם</b>: לשון הכתוב תצוה כט, לג. ואולי צ\"ל: כי קדש היא — תשא לא, יד."],["5133","121","<b>לך רד כלום נתתי</b>: תשא לב, ז. ברכות לב, א. רש\"י תשא שם."],["5134","122","<b>ונטלו ממנו אלף</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381101\" data-slug=\"likkutei-torah\" data-id=\"4001381101\">לקו\"ת ברכה צג, ג</a>־ היום יום יז תמוז שמציין לפע\"ח שער השבת פ\"ח. סה\"מ תרל\"ח ע' רלא. וש\"נ."],["5135","123","<b>התהלך לפני והי' תמים</b>: לך יז, א. ראה הערה הבאה."],["5136","124","<b>את האלקים התהלך נח</b>: נח ו, ט. ראה תנחומא נח ה. ב\"ר פ\"ל, י. רש\"י נח שם."],["5137","125","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["5138","126","<b>אדם הגדול בענקים</b>: יהושע יד, טו [ושם: האדם] וברש\"י שם (בשם מדרש אגדה) ובאיוב לב, ב. ב\"ר פי\"ד, ו. במדב\"ר פי\"ג, ג. סה\"מ תרל\"ח ע' ר. וש\"נ."]]],[2001910487,"<h3>אז ישיר משה</h3>\n<b>ש\"פ בשלח</b>\n<b>אז</b> ישיר משה<sup data-n=\"5139\">1</sup> ובנ\"י את השירה הזאת, ולכאורה הול\"ל ישירו ל' רבים<sup data-n=\"5140\">2</sup> ומהו אומרו ישיר ל' יחיד. והענין דהנה אי' במדרש ע\"פ כמגדל דוד<sup data-n=\"5141\">3</sup> צאורך<sup data-n=\"5142\">4</sup>, הגדיל אתכם דוד בספרו ובמה הגדיל אתכם דוד בספרו דכתי' לגוזר ים סוף לגזרים<sup data-n=\"5143\">5</sup> כי לעולם חסדו<sup data-n=\"5144\">6</sup>. וצ\"ל הלא בתורה כתי' יותר מענין זה<sup data-n=\"5145\">7</sup> ואתה הרם את מטך ונטה ידך על הים ובקעהו ויבואו בני ישראל בתוך הים ביבשה<sup data-n=\"5146\">8</sup>, ואח\"כ כתי' ג\"כ ויבואו בנ\"י בתוך הים ביבשה והמים להם חומה מימינם ומשמאלם<sup data-n=\"5147\">9</sup>, ומדבר מזה פ' שלימה בתורה ולמה א' הגדיל אתכם דוד בספרו, אך מ\"מ מובן ממדרש זה דישראל הם למעלה במדריגה מהים, דבאמת יש בזה מדרשות חלוקות אם הים למעלה מישראל והם נתעלו במה שעברו בתוך הים, או ישראל גבוהים במעלה ומדריגה מהים, דהנה אי' במדרש ראה הפחות שבפחותים בימי משה מה שלא ראו הנביאים<sup data-n=\"5148\">10</sup>, ורש\"י ז\"ל פי' ע\"פ זה אלי ואנוהו ראתה<sup data-n=\"5149\">11</sup> שפחה בים מה שלא ראו הנביאים, והוא ממכילתא, דגבי נביאים כתי' ביד הנביאים אדמה<sup data-n=\"5150\">12</sup> בחי' כדמותינו<sup data-n=\"5151\">13</sup> אבל בקרי\"ס הי' גילוי דבחי' זה, א\"כ הרי נתעלו ישראל במה שעברו בתוך הים, וכן אי' במדרש כמה גדולים יורדי הים<sup data-n=\"5152\">14</sup> שכמה נתחבט משה רבן של כל הנביאים<sup data-n=\"5153\">15</sup> ובקש הראיני נא את כבדך<sup data-n=\"5155\">17</sup><sup data-n=\"5154\">16</sup> א\"ל",[["5139","1","<b>אז ישיר משה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nלקמן על יד הערה 23 מזכיר את ההנחה שלפנ\"ז ד\"ה הוא אהרן ומשה. על יד הערות 85-86 ד\"ה שובה, כנשר (תרמ\"א — עיי\"ש). על יד הערה 154 ד\"ה אז ישיר מם."],["5140","2","<b>אז ישיר . . הזאת . . ישירו ל' רבים</b>: בשלח טו, א. ראה שמו\"ר פכ\"ג, ט."],["5141","3","<b>במדרש ע\"פ כמגדל דוד</b>: שה\"ש ד, ד. ראה שהש\"ר שם."],["5142","4","<b>צאורך</b>: אוצ\"ל: צוארך."],["5143","5","<b>לגוזר ים סוף לגזרים</b>: תהלים קלו, יג."],["5144","6","<b>כי לעולם חסדו</b>: תיבות אלו לא הובאו במדרש שם. וכן אינם מופיעים (לעיל בחלק המאמרים) בהמאמר כאן."],["5145","7","<b>יותר מענין זה</b>: אולי כצ\"ל. בתחילה נכתב: יותר מזה, ובין השיטין ניתוסף תיבת מענין, ולא מחק ה”מ\" מתיבת מזה."],["5146","8","<b>ואתה הרם . . ביבשה</b>: בשלח יד, טז [ושם: את ידך]."],["5147","9","<b>ויבואו בנ\"י . . ומשמאלם</b>: שם שם, כב."],["5148","10","<b>ראה הפחות . . הנביאים</b>: דב\"ר פ\"ז, ח — ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 7."],["5149","11","<b>ורש\"י . . זה אלי ואנוהו ראתה</b>: בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך."],["5150","12","<b>ביד הנביאים אדמה</b>: הושע יב, יא [ושם: וביד — אבל כ\"ה גם לקמן בפיסקא והנה לפ\"ז. סה\"מ תרל\"ח ע' תכד וע' תמב. מאמרי אדה\"א שמות ח\"ב ע' תקנא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540374\" data-slug=\"torat-chaim\" data-id=\"2300540374\">תו\"ח בא ח\"א צט, ב</a>. וש\"נ]."],["5151","13","<b>כדמותינו</b>: לשון הכתוב בראשית א, כו. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א."],["5152","14","<b>כמה גדולים יורדי הים</b>: ראה שמו\"ר פכ\"ג, טו. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ז. סה\"מ תרל\"א ח\"א ע' רסז ואילך."],["5153","15","<b>משה רבן של כל הנביאים</b>: לשון שמו\"ר פכ\"א, ד. דב\"ר פ\"ב, א. רמב\"ם הל' יסודי התורה פ\"ז, ה\"ו."],["5155","17","<b>כבדך</b>: כ\"ה בתשא שם. ובסמוך בפנים: כבודך."],["5154","16","<b>הראיני נא את כבדך</b>: תשא לג, יח."]]],[2001910488,"וראית את אחורי<sup data-n=\"5156\">18</sup> ופני לא יראו ויורדי הים כל אחד מראה באצבע<sup data-n=\"5157\">19</sup> זה אלי ואנוהו, (ה' משה בקש הראיני נא את כבודך הוא בחי' חכ' כבוד בגימ' לב<sup data-n=\"5158\">20</sup>, ל\"ב נת\"ח<sup data-n=\"5159\">21</sup> וכמבואר במ\"א וא\"ל וראית אחוריי הוא בחי' מל' דתבונה<sup data-n=\"5160\">22</sup> וכמשנ\"ת בד\"ה הוא אהרן ומשה<sup data-n=\"5161\">23</sup> כו', ויורדי הים כתי' בהם כ\"א מראה באצבע זה אלי כו' זה הוא בחי' חכ'<sup data-n=\"5162\">24</sup> וכן משה שהוא בחי' חכ'<sup data-n=\"5163\">25</sup> כי מן המים משתיהו<sup data-n=\"5164\">26</sup> נתנבא בזה<sup data-n=\"5165\">27</sup> כמ\"ש בתו\"א בד\"ה בחודש השלישי<sup data-n=\"5166\">28</sup> כו', וכ\"א מראה באצבע זה כו' שהי' אצלם בבחי' ראי', והגם דמשה ג\"כ נתנבא בזה וית\"ל דנבואה הוא גילוי ההעלם<sup data-n=\"5167\">29</sup> (וגם נשמת משה הוא מבחי' חכ' ומשה משה לא פסיק טעמא בנייהו וכמ\"ש במדר'<sup data-n=\"5168\">30</sup>) י\"ל שהי' רק בבחי' השגת המציאות ולא בחי' ראיית המהות (וראי' שהרי בקש הראיני נא את כבודך כו') משא\"כ גבי ישראל בקרי\"ס הי' בבחי' ראיית המהות כו' ע'), מזה ג\"כ מובן שהים למעלה מישראל, ואי' במדרש שאמר הים למשה<sup data-n=\"5169\">31</sup> שהוא גבוה ממנו שנברא בג' ומשה נברא בשישי. ולפעמים מצינו שישראל גבוה מהים דכתי'<sup data-n=\"5170\">32</sup> בוקע הים לפני משה<sup data-n=\"5171\">33</sup> שנתבטל לפני בחי' משה וכתי' וישב הים לפנות בקר לאיתנו<sup data-n=\"5172\">34</sup> לתנאו<sup data-n=\"5173\">35</sup> שהתנה עמו שיקרע לפני ישראל, וכן ממ\"ש במדרש הגדיל אתכם דוד בספרו משמע שישראל גבוהים למעלה מהים [ולפ\"ז צ\"ל למה עברו בתוך הים מאחר שהם גבוהים במעלה מהים].\n<b>והנה</b> כענין מחלוקת זו מצינו בתורה וישראל איזה מהם למעלה יותר<sup data-n=\"5174\">36</sup>, דאי' בתדב\"א שני דברים קדמו לעולם<sup data-n=\"5175\">37</sup> תורה וישראל וא\"י איזה מהם קדום אומר",[["5156","18","<b>וראית את אחורי</b>: תשא שם, כג."],["5157","19","<b>כל אחד מראה באצבע</b>: ראה שמו\"ר פכ\"ג, טו."],["5158","20","<b>כבוד בגימ' לב</b>: זהר רע\"מ צו לג, א."],["5159","21","<b>כבוד . . ל\"ב נת\"ח</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a>. מאמרי אדה\"א בראשית ע' ג ואילך."],["5160","22","<b>וראית . . מל' דתבונה</b>: ראה הערה שלאח\"ז."],["5161","23","<b>וכמשנ\"ת בד\"ה הוא אהרן ומשה</b>: ראה לעיל בהנחה שם על יד הערה 88. ובחלק המאמרים בהמאמר שם ובהערה 122."],["5162","24","<b>זה . . חכ'</b>: ראה תו\"א דבסמוך בפנים ושם: יחו\"ע."],["5163","25","<b>משה . . חכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["5164","26","<b>כי מן המים משתיהו</b>: שמות ב, י."],["5165","27","<b>נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29. אוה\"ת מטות ע' א'תצד. וראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' פ\"א."],["5166","28","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">תו\"א</a> בד\"ה בחודש השלישי</b>: יתרו סז, סע\"ג."],["5167","29","<b>וית\"ל דנבואה הוא גילוי ההעלם</b>: לקמן בפיסקא והנה לפ\"ז. הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ על יד הערה 33. ובמאמר שם רפ\"ב."],["5168","30","<b>ומשה משה לא פסיק טעמא . . במדר'</b>: שמות ג, ד. זהר וירא קכ, ב. נשא אד\"ר קלח, א. בלק קפז, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550300\" data-slug=\"torat-chaim\" data-id=\"2300550300\">תו\"ח משפטים ח\"ב רפג, ג</a>. וש\"נ. סה\"מ תר\"ל ע' נו ואילך."],["5169","31","<b>שאמר הים למשה</b>: שמו\"ר פכ\"א, ו."],["5170","32","<b>דכתי'</b>: מצינו בכמה מקומות בחז\"ל על נוסח תפלה עתיקה הביטוי ”דכתיב\" (זח\"א לד, א. ובכ\"מ. תוד\"ה נשים ברכות כ, ב) — סה\"מ תש\"ט ע' 150 בהערה ע\"ש. הערות ותיקונים לתניא ספל\"ו."],["5171","33","<b>בוקע הים לפני משה</b>: ע\"פ נוסח ברכת אמת ואמונה (תפלת ערבית)."],["5172","34","<b>וישב הים . . לאיתנו</b>: בשלח יד, כז."],["5173","35","<b>לאיתנו לתנאו</b>: ראה שמו\"ר פכ\"א, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061097\" data-slug=\"likkutei-sichot\" data-id=\"1300061097\">לקו\"ש בשלח כרך ו' ע' 86</a> ואילך. וש\"נ."],["5174","36","<b>בתורה וישראל . . למעלה יותר</b>: ראה גם (בנוסף להערה 1 ובהנסמן שם) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">יז, ד</a> ואילך."],["5175","37","<b>דאי' בתדב\"א שני דברים קדמו לעולם</b>: רבא קרוב לספי\"ד בשינויים. ראה גם סה\"מ תר\"ם ח\"ב ס\"ע תקכא ואילך. וש\"נ."]]],[2001910489,"אני ישראל קדום, וכל התורה כולה כתי'<sup data-n=\"5176\">38</sup> צו אל בנ\"י<sup data-n=\"5177\">39</sup> דבר אל בנ\"י<sup data-n=\"5178\">40</sup> הרי ישראל קדום, וכ\"ה במדרש דז' דברים קדמו לעולם תורה וג\"ע<sup data-n=\"5180\">42</sup> וכסה\"כ כו' ומחשבתן של ישראל<sup data-n=\"5179\">41</sup> קדום לכל דבר הרי קדמו לתורה ג\"כ, ואמרז\"ל ע\"פ תורה צוה לנו משה מורשה<sup data-n=\"5181\">43</sup> א\"ת מורשה אלא מאורשה<sup data-n=\"5182\">44</sup> שתורה נק' בשם כלה וכנס\"י נק' חתן שמשפיעים בתורה הרי ישראל למעלה מהתורה, ובזהר אי' תלת קשרין<sup data-n=\"5183\">45</sup> מתקשרין דא בדא ישראל מתקשראין באורייתא ואורייתא בקוב\"ה דתורה הוא ממוצע שמחבר ישראל עם הקב\"ה הרי תורה למעלה מישראל. והנה באמת שניהם אמת דאלו ואלו דברי אלקים חיים<sup data-n=\"5184\">46</sup>. ויובן בהקדם ענין הידוע דלא כל הנשמה מתלבשת בגוף<sup data-n=\"5185\">47</sup> כ\"א הארה ומקצת מהנשמה, דמלאך בשליש עולם עומד<sup data-n=\"5186\">48</sup> ומכ\"ש הנשמה שלמעלה מהמלאך<sup data-n=\"5187\">49</sup> דמלאכים הם מחיצוניות הכלים ונשמות מפנימיות הכלים<sup data-n=\"5188\">50</sup>, כ\"ש שהגוף קטן מהכיל את הנשמה, אלא מה שמתלבשת בגוף הוא רק הארה ומקצת מהנשמה אבל עיקר הנשמה היא למעלה, וע\"ז כתי' ונוזלים מלבנון<sup data-n=\"5189\">51</sup> ששרשה מבחי' לובן העליון<sup data-n=\"5190\">52</sup> ומשם נוזל ונוטף בהנשמה המלובשת בגוף, וזהו שנופל לאדם הרהורי תשובה דאע\"ג דאיהו לא חזי מזליהו חזי<sup data-n=\"5191\">53</sup>, והלא אין מזל לישראל<sup data-n=\"5192\">54</sup>, אלא קאי על",[["5176","38","<b>וכל התורה כולה כתי'</b>: ראה ב\"ר פ\"א, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. סה\"מ תר\"ם שם ע' תקכב הערה 358."],["5177","39","<b>צו אל בנ\"י</b>: כ\"ה גם בסה\"מ תר\"ם ח\"ב ע' תשדמ וש\"נ. לקמן הנחה ד\"ה והמים להם חומה על יד הערה 44. ואוצ\"ל: צו את בנ\"י — ויקרא כד, ב. ועוד."],["5178","40","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["5180","42","<b>וג\"ע</b>: ראה פדר\"א פ\"ג וברד\"ל שם אות יד."],["5179","41","<b>במדרש דז' דברים . . ומחשבתן של ישראל</b>: ראה ב\"ר פ\"א, ד. פי' מהרז\"ו הארוך שם. מאמרי אדה\"א דברים ח\"ב ע' שע בהערה. סה\"מ תרל\"ט ח\"ב ע' תנד. וש\"נ."],["5181","43","<b>תורה צוה לנו משה מורשה</b>: ברכה לג, ד."],["5182","44","<b>א\"ת מורשה אלא מאורשה </b> [ראה לקמן בפיסקא ”אך צ\"ל\" ושם נרשם: מאורסה]<b></b>: ברכות נז, א. ראה גם שער האמונה סט, א הערה 12. סה\"מ תרל\"ח ע' קנה."],["5183","45","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צט. קונטרסים ע' שלט."],["5184","46","<b>דאלו ואלו . . חיים</b>: ערובין יג, ב. ראה גם מאמרי אדה\"א נ\"ך ע' שלט ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550478\" data-slug=\"torat-chaim\" data-id=\"2300550478\">תו\"ח תצוה ח\"ב שמט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151245\" data-slug=\"likkutei-sichot\" data-id=\"1300151245\">לקו\"ש ויצא כרך טו ע' 233</a> ואילך. וש\"נ."],["5185","47","<b>דלא כל הנשמה מתלבשת בגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370387\" data-slug=\"torah-or\" data-id=\"3901370387\">תו\"א תשא פו, ב</a>. (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה הערה 17."],["5186","48","<b>דמלאך בשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. מורה נבוכים ח\"ב, פ\"י. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, סע\"ד</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' ק [ובמהדורת תשס\"ד ח\"א ע' רד] ”שהוא ק\"ס שנה\". סידור שער החנוכה רעו, א ”קס\"ו וב\"ש שנה\"."],["5187","49","<b>הנשמה שלמעלה מהמלאך</b>: ראה גם לעיל הנחה ד\"ה קדש ישראל לה' והערה 46."],["5188","50","<b>דמלאכים הם מחיצוניות . . מפנימיות הכלים</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 35."],["5189","51","<b>ונוזלים מלבנון</b>: שה\"ש ד, טו [ושם: מן לבנון — ראה לקמן הנחה ד\"ה כי תשא על יד הערה 81. סה\"מ תרצ\"ב ע' קיז. סה\"מ תר\"ם ח\"ב ע' תתג. וש\"נ]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת האזינו עא, ד</a> ואילך."],["5190","52","<b>מלבנון . . לובן העליון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפ. תקס\"ב ח\"א ע' פו. תקס\"ד ע' קעד."],["5191","53","<b>דאע\"ג . . מזליהו חזי</b>: מגילה ג, א."],["5192","54","<b>אין מזל לישראל</b>: שבת קנו, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שפ. וש\"נ."]]],[2001910490,"שרש ומקור הנשמה שהיא רואה ושומעת כל הכרוזים<sup data-n=\"5193\">55</sup> העליונים. וכן משארז\"ל בכ\"י ב\"ק יוצאת ומכרזת בהר חורב אוי לו לבריות מעלבונה של תורה<sup data-n=\"5194\">56</sup>, שרש ומקור הנשמה שומעת וגם רואה ומזה נופל לאדם הרהורי תשובה. וע\"פ הקדמה זו יובן מה שלפעמים מבואר דתורה למעלה מישראל, ולפעמים מבואר דישראל למעלה מבחי' תורה, דמ\"ש דתורה למעלה מישראל היינו מחלק הנפש המלובש בגוף ועז\"א תלת קשרין מתקשרין דא בדא ישראל באורייתא ואורייתא בקוב\"ה שהתורה הוא הממוצע לחבר הנשמה המלובש בגוף עם הקב\"ה, דתורה הוא לבושו של הקב\"ה<sup data-n=\"5195\">57</sup> וכמ\"ש עוטה אור כשלמה<sup data-n=\"5196\">58</sup>, והנה כתי' הליכות עולם לו<sup data-n=\"5197\">59</sup> הליכות ל' רבים שיש ב' הליכות<sup data-n=\"5198\">60</sup> א' מלמטלמ\"ע והו\"ע התפלה<sup data-n=\"5199\">61</sup> ב' הילוך מלמעלמ\"ט והוא בחי' תורה שעי\"ז נמשך המשכות אלקות באדם וזהו שהתורה היא ממוצע בין הקב\"ה לישראל, וב' בחי' אור ושלמה שבתורה הם מפני שהוא ממוצע וצריך לכלול מב' הבחי'<sup data-n=\"5200\">62</sup> וזהו בחי' אור שבתורה שהרי מקשרת הקב\"ה כו' והוא בחי' בבע\"ג ובלתי ב\"ת שאין בו השגה והגבלה, ושלמה הוא מה שמקשר ישראל כו' והוא מה שהתורה נתלבשה בדברים גשמים ובהגבלה וכמו אלו טריפות ואח\"כ אלו כשירות<sup data-n=\"5201\">63</sup> שהוא הגבלה כו'.\n<b>(ואפ\"ל</b> ב' בחי' אלו אור ושלמה הם ב' בחי' סתים וגליא שבתורה, סתים הוא בחי' פנימיות התורה שבה התגלות אוא\"ס עצומ\"ה לא ידע אנוש ערכה<sup data-n=\"5202\">64</sup> אלקים הבין דרכה<sup data-n=\"5203\">65</sup> כו' דפנימיות אבא פנימיות ע\"י<sup data-n=\"5204\">66</sup> דהתענוג הוא במוח החכ'<sup data-n=\"5205\">67</sup> קר ולח<sup data-n=\"5206\">68</sup>",[["5193","55","<b>שהיא רואה ושומעת כל הכרוזים</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 41."],["5194","56","<b>בכ\"י ב\"ק . . של תורה</b>: ראה אבות פ\"ו, ה\"ב."],["5195","57","<b>דתורה הוא לבושו של הקב\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא פנ\"ב</a>."],["5196","58","<b>דתורה . . עוטה אור כשלמה</b>: תהלים קד, ב. ראה גם לקו\"ת שמע\"צ פו, א. מאמרי אדה\"ז תק\"ע ע' פג. סידור שער הציצית ג, סע\"ד. אמרי בינה שם פג, ג. ש\"א לט, א ובהערה 1. סה\"מ תרנ\"ה כאן ע' פב בשולי הגליון."],["5197","59","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["5198","60","<b>שיש ב' הליכות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א וישב ל, ד</a>. מאמרי אדה\"ז תקס\"ט ע' קלא ואילך ובהנסמן שם. תו\"א מקץ לח, ג. שע\"ת קב, ג. סה\"מ תרל\"ג ח\"ב ע' תכג ואילך (ובהנסמן בריש המאמר שם). תר\"ם ח\"ב ע' תרמה."],["5199","61","<b>מלמטלמ\"ע והו\"ע התפלה</b>: ראה גם סה\"מ תרס\"ה כאן ריש ע' קכב."],["5200","62","<b>ממוצע . . מב' הבחי'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. סידור שער הל\"ג בעומר שו, ב. אוה\"ת בשלח ע' תקע ואילך."],["5201","63","<b>אלו טריפות . . אלו כשירות</b>: ראה חולין פ\"ג, מ\"א. מ\"ב."],["5202","64","<b>לא ידע אנוש ערכה</b>: איוב כח, יג."],["5203","65","<b>אלקים הבין דרכה</b>: איוב שם, כג."],["5204","66","<b>דפנימיות אבא פנימיות ע\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541072\" data-slug=\"torat-chaim\" data-id=\"2300541072\">תו\"ח שמות ח\"א כג, א</a> הערה 951. סה\"מ תרל\"א ח\"א ע' עז. וש\"נ. תר\"ם ח\"א ע' קצא.\nבמקור הדברים במאמרי אדה\"ז שם נדפסו שני נוסחאות מדרוש זה. הנה בהנחת כ\"ק אדמו\"ר האמצעי מובא זה בשם ”הפע\"ח\". לאידך בהנחת אחיו הר\"מ הביאו בשם ”הע\"ח\". בסה\"מ תרל\"א הנ\"ל הובא זה בשם ”הע\"ח\" וכ\"ה בכ\"מ ומהם: מאמרי אדה\"א דברים ח\"ג ע' תתנא ושם: ”כמ\"ש בע\"ח בכמה דוכתי בשם רבו\". וש\"נ."],["5205","67","<b>דהתענוג הוא במוח החכ'</b>: ראה גם סידור כונת המקוה קנו, א. עניני סעודת שבת קעג, ג. שער הסוכות רנט, ב [נדפס גם במאמרי אדה\"ז תקס\"ב ח\"א ע' כג]. מאמרי אדה\"ז תקס\"ה ח\"א ע' קנא. אוה\"ת שמות כרך ז ס\"ע ב'תקכה ואילך."],["5206","68","<b>במוח החכ' קר ולח</b>: ראה מאמרי אדה\"א בראשית ע' תעא ואילך. הנחות תקע\"ז ע' קמז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540084\" data-slug=\"torat-chaim\" data-id=\"2300540084\">תו\"ח שמות ח\"א כז, ג</a> ובהנסמן במקומות הנ\"ל."]]],[2001910491,"וכמבואר במ\"א. ואפ\"ל דהנה במ\"ת הי' קבלת פנימיות התורה ג\"כ דלע\"ל דכתי' ישקני מנשיקות פיהו<sup data-n=\"5207\">69</sup> ופרש\"י ז\"ל שיתגלו פנימיות טעמי תומ\"צ<sup data-n=\"5208\">70</sup> ומ\"מ לא יהי' עוד הפעם מ\"ת<sup data-n=\"5209\">71</sup>. דבמ\"ת נכלל פנימיות התורה ג\"כ, וזהו שכ' גבי מ\"ת ואשא אתכם על כנפי נשרים<sup data-n=\"5210\">72</sup> שהוא בחי' ת\"ת<sup data-n=\"5211\">73</sup> ות\"ת עולה עד הכתר<sup data-n=\"5212\">74</sup> שזהו ואביא אתכם אלי<sup data-n=\"5213\">75</sup> אלי דוקא כדי שיקבלו גם בחי' פנימיות התורה, וכתי' ישאהו על אברתו<sup data-n=\"5214\">76</sup>, אברתו הוא בחי' רמ\"ח פקודין רמ\"ח אברין דמלכא<sup data-n=\"5215\">77</sup>, וזהו ישאהו על אברתו למעלה מבחי' רמ\"ח פקודין כו' שזהו בחי' מצות ה' כמשנת\"ל<sup data-n=\"5216\">78</sup>, ואפ\"ל דישראל עלו במח' בחי' חכ'<sup data-n=\"5217\">79</sup> וכמ\"ש בנים אתם<sup data-n=\"5218\">80</sup> כו' ישראל שנק' ראשית<sup data-n=\"5219\">81</sup> כו' וזהו ואשא כו' שיהיו בחי' ראש אותיות אשר<sup data-n=\"5220\">82</sup> תענוג<sup data-n=\"5221\">83</sup> העליון שימשיכו מבחי' סתים דתורה, וכן מ\"ש ישאהו על אברתו להמשיך מבחי' מצותי לבחי' מצות ה'<sup data-n=\"5222\">84</sup>, ועמ\"ש במ\"א (בד\"ה שובה<sup data-n=\"5223\">85</sup>, כנשר<sup data-n=\"5224\">86</sup>)",[["5207","69","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["5208","70","<b>ופרש\"י ז\"ל שיתגלו פנימיות טעמי תומ\"צ</b>: ראה שה\"ש שם. וראה גם אותיות דר\"ע אות ז [נדפס גם באוצר המדרשים (אייזענשטיין) ח\"ב ע' 414]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a>. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תעג ואילך. ח\"ב ע' תקצ. וש\"נ. סה\"מ תר\"ם ח\"א ע' עז. וש\"נ. לעיל (בחלק המאמרים) מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה 89."],["5209","71","<b>לא יהי' עוד הפעם מ\"ת</b>: ראה (לקמן בחלק ההנחות) הנחה ד\"ה שוש תשיש הב' על יד הערה 76. סה\"מ תר\"ם ח\"א ס\"ע רפד. סה\"מ מלוקט א' ע' צז. ע' תסא. שם ה' ע' רעא ושם מציין: ”סה\"מ תרנ\"ו ע' שנו. תרס\"ו ע' כג. שם ע' תקמו. תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"ה ע' קצט. ה'תש\"ט ע' 57 (הב') ועוד\". סה\"מ תרמ\"ז ע' פז. תרס\"ג ח\"ב ע' רנט. תרפ\"א ע' קסז. וראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' תרפו. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרכה."],["5210","72","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["5211","73","<b>נשרים . . ת\"ת</b>: ראה ת\"ז ת\"ע קלג, ב. ז\"ח יתרו לא, ג. פרדס שערה\"כ שכ\"ג, פי\"ד מערכת נשר. המשך תער\"ב ח\"ב ע' תרסט."],["5212","74","<b>ות\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב)."],["5213","75","<b>ואביא אתכם אלי</b>: המשך הכתוב ואשא אתכם."],["5214","76","<b>ישאהו על אברתו</b>: האזינו לב, יא. ראה זהר רע\"מ פינחס רלח, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370524\" data-slug=\"torah-or\" data-id=\"3901370524\">תו\"א מג\"א קיז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380662\" data-slug=\"likkutei-torah\" data-id=\"4001380662\">לקו\"ת מטות פה, א</a>. סה\"מ תרכ\"ז ע' ער. תר\"ם ח\"ב ע' תקנד. ע' תשעז. ע' תתקכח."],["5215","77","<b>רמ\"ח פקודין רמ\"ח אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5216","78","<b>מצות ה' כמשנת\"ל</b>: בפיסקא וביאור הענין."],["5217","79","<b>דישראל עלו במח' בחי' חכ'</b>: ראה ב\"ר פ\"א, ד. לעיל הנחה ד\"ה הקבצו ושמעו ובהערה 53."],["5218","80","<b>בנים אתם</b>: פ' ראה יד, א."],["5219","81","<b>ישראל שנק' ראשית</b>: תנחומא — באבער — בראשית ג. וש\"נ. אלפא ביתא דר\"ע אות ב ד\"א בי\"ת [נדפס גם באוצר המדרשים אייזענשטיין ח\"ב ע' 411]. רש\"י ולק\"ט ר\"פ בראשית. רש\"י סנהדרין צא, ב ד\"ה מששת. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשי."],["5220","82","<b>ראש אותיות אשר</b>: ראה זהר בראשית טו, סע\"א. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ב. סה\"מ תר\"ם ח\"א ע' קסג. וש\"נ."],["5221","83","<b>אשר תענוג</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות יח, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370238\" data-slug=\"torah-or\" data-id=\"3901370238\">ויצא כג, ג</a>. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."],["5222","84","<b>מצותי לבחי' מצות הוי'</b>: ראה לקמן פיסקא וביאור הענין ובהערה 128."],["5223","85","<b>בד\"ה שובה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה דשנת תרמ\"א אינה תח\"י. ראה סה\"מ תרמ\"ד ע' שנט (מהדורת תשס\"ב) ושם: ”דזהו מ\"ש מח' ש\"י קדמה לכל דבר פי' דבר הוא הצמצום כמ\"ש בד\"ה יונתי ר\"מ (בהרישומים דשובה)\" והכוונה לד\"ה כנשר שנסמן בהערה שלאח\"ז."],["5224","86","<b>בד\"ה . . כנשר</b>: תרמ\"א. ראה סה\"מ תר\"ם ח\"ב ס\"ע תקנו ואילך. ס\"ע תתקלט ואילך."]]],[2001910492,"בענין מח' של ישראל קדמה לכל דבר, דבר הוא סוכ\"ע וכמבואר במ\"א בענין דבר מתוך דבר, תוך דבר ממכ\"ע דבר סוכ\"ע<sup data-n=\"5225\">87</sup>, כי דבר הוא בחי' עיגול הגדול שלפני הקו<sup data-n=\"5226\">88</sup> ומחשבתן של ישראל קדום גם לבחי' עיגול הגדול שלפני הקו, והנה אמרז\"ל במי נמלך<sup data-n=\"5227\">89</sup> בנשמותיהן של צדיקים, ענין ההמלכה הוא כמו עד\"מ אדם שמיישב בינו לעצמו אם יעשה דבר פלוני א\"ל והמלכה זו הוא בהעלם עצמו עדיין וכמו\"כ יובן למעלה דכדי שיהי' רצון לרצון לבריאות העולמות<sup data-n=\"5228\">90</sup> כביכול המליך בעצמו, ובחי' זו למעלה גם מבחי' עלה ברצונו<sup data-n=\"5229\">91</sup> כו' שהוא גילוי משא\"כ ענין ההמלכה הוא כביכול בעצמותו עדיין והו\"ע בחי' אור המאיר לעצמו כו' וע\"ז אמרו ז\"ל במי נמלך בנשמותיהן של צדיקים (דעיקר הכוונה בשביל קיום התומ\"צ לו דירה<sup data-n=\"5231\">93</sup> כו' וזהו צדיק<sup data-n=\"5230\">92</sup> וכתי' ועמך כולם צדיקים<sup data-n=\"5232\">94</sup> וע' בד\"ח שהת\"פ א\"ב<sup data-n=\"5233\">95</sup>) א\"כ שרש ומקור הנשמה הוא למעלה גם מבחי' עלה ברצונו כו' ואפ\"ל כמו\"כ הו\"ע משארז\"ל מח' של ישראל קדום לכל דבר כו' מבחי' עלה ברצונו כו' וגם מבחי' תומ\"צ<sup data-n=\"5234\">96</sup> כו' וד\"ל. ולפ\"ז י\"ל פי' ואשא כו' ישאהו כו' קאי על חלק הנפש המלובש בגוף (שעדיין לא ניתנה התורה) לקבל גם בחי' פנימיות התומ\"צ כו' וד\"ל) וזהו משארז\"ל הלואי אותי עזבו ותורתי שמרו<sup data-n=\"5235\">97</sup> המאור שבה מחזירו למוטב<sup data-n=\"5236\">98</sup> והיינו מצד בחי' אור שבתורה הוא מחזירו למוטב.\n<b>וסדר</b> העבודה הנה אמרז\"ל מעיקרא כי עביד איניש אדעתי' דנפשי' עביד<sup data-n=\"5237\">99</sup> ואח\"כ צ\"ל לימוד התורה לשמה<sup data-n=\"5238\">100</sup>, דתחילה צ\"ל ענין התורה לקשר חלק הנפש",[["5225","87","<b>תוך דבר ממכ\"ע דבר סוכ\"ע</b>: ראה סה\"מ תרל\"ח ע' רכב ואילך ובהנסמן שם. לעיל הנחה ד\"ה קדש ישראל לה' על יד הערה 169. ובהמאמר שם על יד הערה 163."],["5226","88","<b>עיגול הגדול שלפני הקו</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["5227","89","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161500\" data-slug=\"likkutei-sichot\" data-id=\"1300161500\">לקו\"ש</a> פ' החודש כרך טז ע' 487 בהערה."],["5228","90","<b>לבריאות העולמות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310026\" data-slug=\"tanya\" data-id=\"3401310026\">תניא פכ\"א כז, א</a> ובליקוטי לוי יצחק שם. ראה גם לקמן הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ על יד הערה 37. ד\"ה תקעו בחדש שופר על יד הערה 42. לעיל (בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א ובהערה 117. סה\"מ תר\"ם ח\"ב ע' תתנא וע' תתקמב."],["5229","91","<b>עלה ברצונו</b>: ראה ע\"ח שער הכללים בתחילתו. דרוש עגו\"י ש\"א, ענף ב."],["5231","93","<b>לו דירה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ספ\"א. וש\"נ."],["5230","92","<b>קיום התומ\"צ . . צדיק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380688\" data-slug=\"likkutei-torah\" data-id=\"4001380688\">לקו\"ת מסעי צא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">שה\"ש טז, ג</a>. סה\"מ תרל\"ח ע' תז. וש\"נ. לעיל (בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א רפ\"ב."],["5232","94","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["5233","95","<b>בד\"ח שהת\"פ א\"ב</b>: בספר דרך חיים שער התפלה [דרוש השני ד\"ה הנה כתיב דומה דודי לצבי פרקים] א\"ב."],["5234","96","<b>מח' . . קדום לכל דבר . . מבחי' תומ\"צ</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' קעא. במדבר ח\"ב ע' תקנח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680248\" data-slug=\"torat-chaim\" data-id=\"2300680248\">תו\"ח תולדות קנב, רע\"ד</a>."],["5235","97","<b>הלואי אותי עזבו ותורתי שמרו</b>: פי' הכתוב ירמי' טז, יא [ושם: ואותי . . ואת תורתי לא שמרו]."],["5236","98","<b>המאור שבה מחזירו למוטב</b>: ראה פתיחתא דאיכ\"ר ב. ירושלמי חגיגה פ\"א, ה\"ז. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה ספ\"ב. וש\"נ."],["5237","99","<b>מעיקרא . . דנפשי' עביד</b>: פסחים סח, ע\"ב. ראה גם (בנוסף להערה 1 ובהנסמן שם) מאמרי אדה\"א שמות ח\"ב ע' שסז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540979\" data-slug=\"torat-chaim\" data-id=\"2300540979\">תו\"ח בשלח ח\"א רלז, א</a>."],["5238","100","<b>לימוד התורה לשמה</b>: ראה פע\"ח שער הנהגת הלימוד. (בנוסף להערה 1 ובהנסמן שם) מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. שה\"א סט, ב ובהערה 26. סה\"מ תרכ\"ז ס\"ע רסח ואילך. וש\"נ. תרל\"ג ח\"ב ע' שעד ואילך בשולי היריעה. לקמן הנחה ד\"ה וברך את לחמך על יד הערה 45."]]],[2001910493,"המלובש<sup data-n=\"5239\">*101</sup> עם הקב\"ה (עמ\"ש בתו\"א בד\"ה בחדש השלישי<sup data-n=\"5240\">101</sup>) וזהו אדעתי' דנפשי' פי' לקשר נפשו, ואח\"כ צ\"ל לימוד התורה לשמה לשם התורה. והענין דהנה התורה למטה נתלבשה בדברים גשמים המחליף פרה בחמור<sup data-n=\"5241\">102</sup>, וכמו\"כ ד' רשויות דשבת<sup data-n=\"5242\">103</sup> רה\"ר רה\"י שהם דברים גשמים, וכמו\"כ יש תורה למעלה ג\"כ ברוחניות רה\"ר הוא בחי' עולם התהו ורה\"י הוא בחי' עולם התיקון<sup data-n=\"5243\">104</sup>, וזהו לשם התורה להמשיך מבחי' תורה שלמעלה בתורה שלמטה. ועוי\"ל פי' לשם התורה כמ\"ש בספר הבהיר דוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"5244\">105</sup>, הרי גם תורה של מעלה צריכים לחבר בהקב\"ה, וזהו לשם התורה להמשיך המשכות אוא\"ס בתורה (אפ\"ל דאי' בזהר תלת קשרין כו' וכולהון דרגין על דרגין סתים וגליא, וזהו פי' לשם התורה להמשיך המשכות אוא\"ס בחי' סתים בתורה). והגם שאמרז\"ל ג' שעות הראשונות הקב\"ה יושב ועוסק בתורה<sup data-n=\"5245\">106</sup> וא\"כ מהו\"ע העבודה כו' י\"ל ע\"ז ב' תירוצים, דמה שהקב\"ה יושב ועוסק בתורה היינו ההמשכה בבחי' אור דתורה והעבודה הוא להמשיך גם בבחי' שלמה דתורה, ועוי\"ל דמה שהקב\"ה יושב ועוסק בתורה הוא רק ג' שעות הראשונות, אך ע\"י והגית בו יומם ולילה<sup data-n=\"5246\">107</sup> ממשיכים כל היום המשכת אוא\"ס בתורה.\n<b>אך</b> צ\"ל איך יש בכח ישראל להמשיך המשכות אוא\"ס בתורה, הענין הוא דהנה אמרז\"ל בראשית בשביל התורה<sup data-n=\"5247\">108</sup> שנק' ראשית, וגם מה שארז\"ל תורה קדמה לעולם<sup data-n=\"5248\">109</sup> הוא ג\"כ כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"5249\">110</sup>, וישראל הוא לי ראש<sup data-n=\"5250\">111</sup> שלמעלה מראשית<sup data-n=\"5251\">112</sup>, דראש אותיות אשר שהוא השפעות התענוג העליון בבחי' התורה שנק' ראשית. ועפ\"ז מובן מ\"ש תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה שישראל ממשיכים המשכות אוא\"ס בתורה, וזהו מ\"ש זכרו תורת משה עבדו<sup data-n=\"5252\">113</sup> שנק'",[["5239","*101","<b>המלובש עם</b>: כ\"ה בגוכתי\"ק."],["5240","101","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו\"א</a> בד\"ה בחדש השלישי</b>: יתרו סז, סע\"א ואילך."],["5241","102","<b>המחליף פרה בחמור</b>: משנה ב\"מ ק, רע\"א. ראה גם (בנוסף להערה 1 ובהנסמן שם) סה\"מ תרל\"ה ח\"ב ע' תנב הערה 69. המשך וככה תרל\"ז פ\"ו. פ\"ז. סה\"מ תרל\"ח ע' קסא ואילך."],["5242","103","<b>ד' רשויות דשבת</b>: שבת ו, א."],["5243","104","<b>רה\"ר . . התהו ורה\"י . . התיקון</b>: כ\"ה בע\"ח שער שבה\"כ פ\"ב. ובלקוטי הש\"ס מהאריז\"ל [לשבת ו, א] מבואר דרה\"י עולם האצי' שהוא עיקר התיקון, ורה\"\"ר בריאה דז' מל' דתהו נפלו במקום עולם הבריאה כידוע, וכרמלית יצי', ומקום פטור עשי' — סה\"מ תרנ\"ה כאן ע' פג."],["5244","105","<b>בספר הבהיר דוד . . בהקב\"ה</b>: ראה ס' הבהיר סקצ\"ו ובאור בהיר לשם. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ה: ברע\"מ פ' פנחס דף רך\"ב ע\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a>. סה\"מ תר\"ם ח\"א ע' פד. וש\"נ."],["5245","106","<b>ג' שעות . . ועוסק בתורה</b>: ראה ע\"ז ג, ב. ראה גם סה\"מ תרס\"ה כאן ע' קכג ואילך."],["5246","107","<b>והגית בו יומם ולילה</b>: יהושע א, ח. ראה הל' ת\"ת לאדה\"ז פ\"ג, ה\"ה ואילך."],["5247","108","<b>בראשית בשביל התורה</b>: בראשית א, א. ראה רש\"י שם. לקו\"ש נח כרך ג ע' 755 בהערה."],["5248","109","<b>תורה קדמה לעולם</b>: פסחים נד, א."],["5249","110","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["5250","111","<b>וישראל הוא לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["5251","112","<b>ראש שלמעלה מראשית</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370312\" data-slug=\"torah-or\" data-id=\"3901370312\">תו\"א יתרו ע, א</a>. (לעיל בחלק המאמרים) מאמר ד\"ה ושאבתם מים בששון פ\"ג. וש\"נ."],["5252","113","<b>זכרו תורת משה עבדו</b>: מלאכי ג, כב [ושם: עבדי]."]]],[2001910494,"בשם תורת משה שהמשיך המשכות בתורה, וזהו מ\"ש כי אם בתורת ה' חפצו<sup data-n=\"5253\">114</sup> ובתורתו יהגה יומם ולילה, דתחילה צ\"ל בתורת ה' חפצו היינו לקשר חלק הנפש המלובש בגוף עם הקב\"ה ועי\"ז מתחבר עם שרש ומקור הנפש ואז לימוד התורה לשמה להמשיך המשכות אוא\"ס בתורה מבחי' תורתו. אך הרי הנשמה מלובשת בגוף ונה\"ב המעלים ומסתיר וגם ניזון מדברים גשמים ואיך יכול להמשיך מבחי' תורתו. הנה זהו מה שא' ר\"ש חדאי נפשאי<sup data-n=\"5254\">115</sup> לך קראי לך תנאי מעיקרא כי עביד כו' אדעתי' דנפשי' לקשר נפשו המלובש בגוף ואח\"כ להמשיך המשכות אוא\"ס כו'. והנה כשם שיש ב' בחי' אלו בתורה כמו\"כ ישנם במצות ג\"כ דהנה על המצות אנו מברכים אשר קדשנו במצותיו<sup data-n=\"5255\">116</sup> הרי המצות למעל' מישראל דקדשנו במצותיו, וע\"פ ועשיתם אתם<sup data-n=\"5256\">117</sup> אמרז\"ל אתם כתי' מעלה אני עליכם כאילו עשוני<sup data-n=\"5257\">118</sup> הרי ישראל למעלה מהמצות, והענין דמה שאומרים אשר קדשנו במצותיו הוא בחי' רמ\"ח פקודין רמ\"ח אברין דמלכא והוא בחי' המלך הקדוש<sup data-n=\"5258\">119</sup>, ומ\"מ ישראל עושין המצות דמספר דרמ\"ח פקודין כו' הוא דז\"א בעל ט\"ס<sup data-n=\"5259\">120</sup> טפ\"ט פ\"א רת\"ס רמ\"ג ה\"ח<sup data-n=\"5260\">121</sup> המגדילים רמ\"ח והוא מ\"ש על דמות הכסא<sup data-n=\"5261\">122</sup> דמות כמראה אדם עליו מלמעלה ולכאו' והלא אין לו דמות הגוף<sup data-n=\"5262\">123</sup> ולא גוף אלא שהוא בחי' רמ\"ח<sup data-n=\"5263\">124</sup> פקודין כו' אבל ישראל ממשיכים מבחי' א\"ס כי לא אדם הוא<sup data-n=\"5264\">125</sup> במצות.\n<b>וביאור</b> הענין הוא דהנה אנו אומרים בתפלת שבת ויו\"ט קדשנו במצותיך<sup data-n=\"5265\">126</sup> ולכאו' צ\"ל הלא קדשנו במצותיו, והענין דיש מצות ה'<sup data-n=\"5266\">127</sup> ומצותיו<sup data-n=\"5267\">128</sup>, מצות ה' הו\"ע רמ\"ח פקודין רמ\"ח אברים דמלכא, ומצותיו הוא מצות של מעלה,",[["5253","114","<b>כי אם בתורת ה' חפצו</b>: תהלים א, ב. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 78 ואילך."],["5254","115","<b>שא' ר\"ש חדאי נפשאי</b>: במאמרי אדה\"ז הקצרים ע' תקע כותב: בר\"א. ראה לעיל הערה 99."],["5255","116","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["5256","117","<b>ועשיתם אתם</b>: בחוקותי כו, ג."],["5257","118","<b>אתם . . כאילו עשוני</b>: ראה זהר בחוקותי קיג, סע\"א. ויק\"ר פל\"ה, ז. תנחומא תבא סוף ס\"א."],["5258","119","<b>המלך הקדוש</b>: לשון הגמ' ברכות יב, ב. ראה זהר בשלח נה, א ובמק\"מ שם."],["5259","120","<b>דז\"א בעל ט\"ס</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381201\" data-slug=\"likkutei-torah\" data-id=\"4001381201\">לקו\"ת שה\"ש יח, א</a> מציין: ”כמ\"ש במ\"א בד\"ה אלפי שנאן בפ' יתרו [<a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">תו\"א יתרו עב, א</a>] ועיין בזהר נח דס\"ה א' ובע\"ח שער א\"א פ\"ב\"."],["5260","121","<b>ט\"ס . . ה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370172\" data-slug=\"torah-or\" data-id=\"3901370172\">תו\"א מקץ לז, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">שע\"ת מב, ב</a> ובהערה 13."],["5261","122","<b>על דמות הכסא</b>: יחזקל א, כו [ושם: ועל]."],["5262","123","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם מס' סנהדרין פ\"י היסוד הג'. ראה גם סה\"מ תרל\"ח ע' צג. ע' ריז. וש\"נ. תר\"ם ח\"א ע' צב. וש\"נ."],["5263","124","<b>בחי' רמ\"ח</b>: תיבות אלו אינם ברורים בהצילום."],["5264","125","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["5265","126","<b>אנו אומרים . . קדשנו במצותיך</b>: בתפלת העמידה. ראה גם (בנוסף להערה 1 ובהנסמן שם) לקו\"ת ר\"פ בשלח. במדבר ט, ג. מאמרי אדה\"א שמות ח\"א ע' רה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450612\" data-slug=\"or-hatorah-hb\" data-id=\"8316450612\">אוה\"ת עקב ע' תריב</a>. פלח הרמון אמור ע' שנד."],["5266","127","<b>מצות ה'</b>: ויקרא ד, ב. יג. כד. ועוד."],["5267","128","<b>מצות ה' ומצותיו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380346\" data-slug=\"likkutei-torah\" data-id=\"4001380346\">לקו\"ת במדבר ט, ג</a>. סידור שער הציצית ד, ד. ה, ג. אמ\"ב שם פו, א. סה\"מ תרל\"ח ע' שלב. וש\"נ."]]],[2001910495,"הקב\"ה מניח תפילין<sup data-n=\"5268\">129</sup>, הקב\"ה מצלי<sup data-n=\"5269\">130</sup>, מגיד דבריו ליעקב<sup data-n=\"5270\">131</sup> חוקיו ומשפטיו לישראל מה שהוא עושה<sup data-n=\"5271\">132</sup> אומר לישראל לעשות, וענין מצות שלמעלה הוא דתרי\"ג מצות דאורייתא וז' מצות דרבנן הם תר\"ך עמודי אור<sup data-n=\"5272\">133</sup> דכתר וזהו\"ע מצות של מעלה תר\"ך<sup data-n=\"5273\">134</sup> אורות דכתר, וזהו שאנו מבקשים קדשנו במצותיך להמשיך מבחי' מצותיו בבחי' מצות ה', וזהו שאומרים בפ' שלישי דק\"ש וזכרתם את מצות ה'<sup data-n=\"5274\">135</sup> שהם בחי' דכר<sup data-n=\"5275\">136</sup> משפיע ואח\"כ אומרים למען תזכרו<sup data-n=\"5276\">137</sup> ועשיתם את כל מצותי שישראל הם משפיעים במצות, והענין דמצות ה' הם למעלה מהנשמה המלובשת בגוף וזהו וזכרתם את כל מצות ה', ואח\"כ למען תזכרו ועשיתם את כל מצותי שממשיכים מבחי' מצותי לבחי' מצות ה', וה\"ז ע\"ד והחיות נושאות את הכסא נושאות ומנושאות<sup data-n=\"5277\">138</sup>, וכן ארון נשא את נושאיו<sup data-n=\"5278\">139</sup> דבתחילה נשאו אותו ואח\"כ נשא את נושאיו.\n<b>והנה</b> לפ\"ז יובן בים ג\"כ, דהנה ים ויבשה הוא עלמא דאתכסי' ועלמא דאתגלי'<sup data-n=\"5279\">140</sup> ואמרז\"ל כל מה שיש ביבשה<sup data-n=\"5280\">141</sup> יש בים רק ברואים שבים הם מובלעים בים ודגים הפורשים מן הים נפסק חיותם משא\"כ ברואים שביבשה הגם שמקבלים חיות מן הארץ וכמ\"ש ארץ אשר ממנו תוצא לחם<sup data-n=\"5281\">142</sup> מ\"מ יכולים לחיות באויר וגם לשוט בספינה, וכמו\"כ יובן למעלה ברוחניות ישראל הם נק' ארץ וכמ\"ש כי תהיו אתם ארץ חפץ<sup data-n=\"5282\">143</sup> וכתי' והארץ לעולם עומדת<sup data-n=\"5283\">144</sup> וכתי' עמד וימודד ארץ<sup data-n=\"5284\">145</sup> ויש פי' א'",[["5268","129","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ובהערה 126."],["5269","130","<b>הקב\"ה מצלי</b>: ברכות ז, א: מכאן שהקב\"ה מתפלל. מאי מצלי. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830234\" data-slug=\"or-hatorah-hb\" data-id=\"8158830234\">אוה\"ת בלק ס\"ע תתקכ</a>. ע' תתקנד. סה\"מ תרכ\"ז ע' שנז. ע' תעז."],["5270","131","<b>מגיד דבריו ליעקב</b>: תהלים קמז, יט."],["5271","132","<b>מה שהוא עושה</b>: ראה שמו\"ר פ\"ל, ט."],["5272","133","<b>דתרי\"ג . . וז' . . תר\"ך עמודי אור</b>: ראה גם לעיל הנחה ד\"ה קדש ישראל לה' ובהערות 131-135."],["5273","134","<b>תר\"ך</b>: תיבה זו א) איננה ברורה כ\"כ. ב) אולי נמחקה."],["5274","135","<b>וזכרתם את מצות ה'</b>: שלח טו, לט [ושם: את כל. וכ\"ה בסמוך בפנים]."],["5275","136","<b>וזכרתם . . דכר</b>: ראה גם שמו\"א א, יא וזכרתני ובמדרש שמואל (פ\"ב שם) וזכרתני בזכרים."],["5276","137","<b>למען תזכרו</b>: שלח שם, מ. ראה גם (בנוסף להערה 1 ובהנסמן שם) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380493\" data-slug=\"likkutei-torah\" data-id=\"4001380493\">לקו\"ת שלח מה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380502\" data-slug=\"likkutei-torah\" data-id=\"4001380502\">מז, ג</a>."],["5277","138","<b>והחיות . . נושאות ומנושאות</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג. מאמרי אדה\"ז תקס\"ד ע' כג. שה\"א ע, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550497\" data-slug=\"torat-chaim\" data-id=\"2300550497\">תו\"ח פקודי ח\"ב תנט, א</a>. וש\"נ."],["5278","139","<b>ארון נשא את נושאיו</b>: ראה סוטה לה, א. מאמרי אדה\"א בראשית ע' שעג. וש\"נ."],["5279","140","<b>ים ויבשה . . ועלמא דאתגלי'</b>: ראה (בנוסף להערה 1 ובהנסמן שם) (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ז. ד\"ה הים ראה וינוס על יד הערה 16 ואילך. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540566\" data-slug=\"torat-chaim\" data-id=\"2300540566\">תו\"ח בשלח ח\"א קלח, ג</a> הערה 312. פלח הרמון ויקרא ע' פב. וש\"נ."],["5280","141","<b>כל מה שיש ביבשה</b>: חולין קכז, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a> הערה 770."],["5281","142","<b>ארץ אשר ממנו תוצא לחם</b>: איוב כח, ה [ושם: ארץ ממנה יצא לחם]."],["5282","143","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["5283","144","<b>והארץ לעולם עומדת</b>: קהלת א, ד."],["5284","145","<b>עמד וימודד ארץ</b>: חבקוק ג, ו. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 108."]]],[2001910496,"שמדדם אם יוכלו לקבל תורה, והוא בחי' עלמא דאתגלי', ובנ\"י הלכו ביבשה בתוך הים<sup data-n=\"5285\">*146</sup> הו\"ע גילוי ההעלם, דעלדאת\"כ<sup data-n=\"5286\">146</sup> הוא בחי' העלם ובקרי\"ס היו<sup data-n=\"5287\">*147</sup> גילוי עלדאת\"כ בעלמדאת\"ג<sup data-n=\"5288\">**147</sup>. וזהו ראתה שפחה על הים מה שלא ראו הנביאים, דנבואה הו\"ע גילוי ההעלם אך גבי נביאים כתיב ביד הנביאים אדמה אבל משה נתנבא בזה וזהו ראתה שפחה על הים מה שלא ראו הנביאים ומ\"מ כשהים ראה בנ\"י נתבטל לפניהם, דשרש ומקור הנשמה הוא למעלה מהים דאף עלמא דאתכסי' הרי נק' בשם עלמא אבל ישראל בשרשן הם למעלה אפי' מאותן ז' דברים שקדמו לעולם. ועוי\"ל דבין עלמא דאתכסיא ובין עלמא דאתגליא שרשן מבחי' דיבור אבל ישראל עלו במח' ששרשן ממח' ופי' עלה במח' הוא בחי' היותר עליונה שבמח'<sup data-n=\"5289\">147</sup>. ושרש הענין דים סוף הוא סופא דכל דרגין<sup data-n=\"5290\">148</sup> בחי' מלכותך מל' כל עולמים<sup data-n=\"5291\">149</sup> רק שהוא מה שכונס ומעלים בתוכו אורות אצי', משא\"כ בישראל כתי' בעבר הנהר ישבו אבותיכם<sup data-n=\"5292\">150</sup> נהר הוא בחי' בינה<sup data-n=\"5293\">151</sup> ועבר הנהר הוא למעלה מבינה, לכן הים כשראה את בנ\"י נתבטל לפניהם מצד שרשם ומקורם (וכמו\"כ יש קרי\"ס עד רום המעלות שענין גילוי הקו נק' ג\"כ קרי\"ס, סוף<sup data-n=\"5294\">152</sup> ים הוא בחי' עיגול הגדול שלפני הקו והוא בחי' עלמא דאתכסי' וכתי' אז יבקע כשחר אורך<sup data-n=\"5295\">153</sup> הו\"ע בקיעות הקו וכמ\"ש בד\"ה אז ישיר מם<sup data-n=\"5296\">154</sup>, ושרש נש\"י כנ\"ל כו').\n<b>וזהו</b> אז ישיר משה ובנ\"י, בנ\"י הוא הנשמה המלובש בגוף ומשה הוא בחי' שרש ומקור הנשמה, לכן נתבטל לפניהם<sup data-n=\"5297\">155</sup>. דהנה משה הוא הממשיך דעת<sup data-n=\"5298\">156</sup> בנש\"י גם בבחי' זרע בהמה דכתי' וזרעתי את בנ\"י<sup data-n=\"5299\">157</sup> זרע אדם וזרע בהמה שיש נשמות דזרע אדם (הם נשמות דאצי' שיש בהם דעת) ויש נשמות דזרע בהמה<sup data-n=\"5300\">158</sup> (הם נשמות דבי\"ע שאין בהם דעת כמו שבהמה אין לה דעת), ומשה המשיך בחי' דעת בנשמות דזרע בהמה ג\"כ, ובכ\"א יש בחי' משה<sup data-n=\"5301\">159</sup> הוא בחי' הדעת שיש בכ\"א",[["5285","*146","<b>ובנ\"י . . בתוך הים</b>: בשלח יד, כט."],["5286","146","<b>דעלדאת\"כ</b>: ראה גם סה\"מ תרל\"ח ס\"ע קלח ואילך."],["5287","*147","<b>היו</b>: כ\"ה בגוכתי\"ק."],["5288","**147","<b>עלדאת\"כ בעלמדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["5289","147","<b>עלה במח' . . היותר עליונה שבמח'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">לקו\"ת שה\"ש יט, ב</a>."],["5290","148","<b>דים סוף . . דכל דרגין</b>: ראה זהר בשלח נו, א. רע\"מ פינחס רנה, א."],["5291","149","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג."],["5292","150","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב."],["5293","151","<b>נהר . . בינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>: כמ\"ש בזהר פ' אמור [צט, א]."],["5294","152","<b>סוף</b>: אולי תיבה זו מיותרת."],["5295","153","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח."],["5296","154","<b>בד\"ה אז ישיר מם</b>: ראה הנחת כ\"ק אדמו\"ר מהורש\"ב בסה\"מ תר\"ם ח\"א ע' שנ."],["5297","155","<b>נתבטל לפניהם</b>: אוצ\"ל: נתבטל הים לפניהם."],["5298","156","<b>משה הוא הממשיך דעת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370335\" data-slug=\"torah-or\" data-id=\"3901370335\">תו\"א משפטים עה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550111\" data-slug=\"torat-chaim\" data-id=\"2300550111\">תו\"ח משפטים ח\"ב רעז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550144\" data-slug=\"torat-chaim\" data-id=\"2300550144\">רעט, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550145\" data-slug=\"torat-chaim\" data-id=\"2300550145\">רפב, ב</a> ואילך."],["5299","157","<b>וזרעתי את בנ\"י</b>: ירמי' לא, כו [ושם: בית ישראל — ראה לעיל הנחה ד\"ה קדש ישראל לה' ובהערה 47. בדילוג]."],["5300","158","<b>דזרע אדם . . דזרע בהמה</b>: ראה גם לעיל הנחה ד\"ה קדש ישראל לה' ובהערה 48."],["5301","159","<b>ובכ\"א יש בחי' משה</b>: ראה (בנוסף להערה 1 ובהנסמן שם) <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב. ש\"א מא, ב</a> ובהערה 26. לקמן הנחה ד\"ה זכור על יד הערה 62. וראה גם בענין משה שבכאו\"א <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380063\" data-slug=\"likkutei-torah\" data-id=\"4001380063\">לקו\"ת פקודי ה, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540677\" data-slug=\"torat-chaim\" data-id=\"2300540677\">תו\"ח בשלח ח\"א קנו, סע\"ד</a>. וש\"נ."]]],[2001910497,"דכל אדם מברך חונן הדעת<sup data-n=\"5302\">160</sup> והוא בחי' משה שיש בכ\"א. דהנה כתי' כי תקנה עבד עברי<sup data-n=\"5303\">161</sup>, עבד הוא בחי' יעקב עבדו<sup data-n=\"5304\">162</sup> הוא חלק הנפש המלובש בגוף, ועברי הוא בחי' בעבר הנהר כו' תקנה ידוע ענין הקנין הוא מהעלם לידי גילוי<sup data-n=\"5305\">163</sup>, ומשה הוא הממשיך זאת בנש\"י. וזהו מ\"ש ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה<sup data-n=\"5306\">164</sup> כו' ואמרז\"ל אטו יראה מילתא זוטרתא היא<sup data-n=\"5307\">165</sup>, אין לגבי משה מילתא זוטרתא, ולכאו' והלא א' מעמך שקאי על ישראל, ומה תירצו דלגבי משה היא מילתא זוטרתא, אך הוא מפני שבכל ישראל יש בחי' משה. וזהו אז ישיר משה ובנ\"י, דבנ\"י הוא חלק הנפש המלובש בגוף ומשה הוא שורש ומקור הנפש והכל אחד לכן אמר אז ישיר לשון יחיד כו'.",[["5302","160","<b>מברך חונן הדעת</b>: בתפלת שמונה עשרה."],["5303","161","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["5304","162","<b>יעקב עבדו</b>: ישעי' מח, כ [ושם עבדו יעקב]."],["5305","163","<b>הקנין הוא מהעלם לידי גילוי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370339\" data-slug=\"torah-or\" data-id=\"3901370339\">עו, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550239\" data-slug=\"torat-chaim\" data-id=\"2300550239\">תו\"ח שם רעח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550082\" data-slug=\"torat-chaim\" data-id=\"2300550082\">רפד, ב</a>."],["5306","164","<b>ועתה ישראל . . כ\"א ליראה</b>: עקב י, יב."],["5307","165","<b>אטו יראה מילתא זוטרתי היא</b>: ברכות לג, ב."]]],[2001910498,"<h3>זכור את יום השבת</h3>\n<b>ש\"פ יתרו</b>\n<b>זכור</b> את יום השבת<sup data-n=\"5308\">1</sup> לקדשו<sup data-n=\"5309\">2</sup> ששת ימים תעבוד ועשית מלאכתך<sup data-n=\"5310\">3</sup> כו' ויום<sup data-n=\"5311\">4</sup> השביעי שבת לה' אלקיך<sup data-n=\"5312\">5</sup>, הנה ממ\"ש ששת ימים תעבוד משמע שהוא ציווי ובאמת אינו כן<sup data-n=\"5313\">6</sup>, ואי' במדרש תנא רשב\"י אומר אמרה שבת<sup data-n=\"5314\">7</sup> להקב\"ה לכולם יש בן זוג פי' ששת ימי בראשית הם ג' זוגות ולי אין בן זוג א\"ל הקב\"ה כנס\"י יהי' בן זוגך וזהו שא\"ל הקב\"ה לישראל זכרו אותו הדבר שאמרתי לשבת כנס\"י יהי' בן זוגך והוא הדיבור זכור את יום השבת לקדשו, משמע דישראל הם בחי' דכר שמשפיעים בשבת וכן כתי' ושמרו בנ\"י את השבת לעשות את השבת<sup data-n=\"5315\">8</sup> שישראל עושין את השבת, ובאמת אינו כן דהלא שבת מיקדשא וקיימא<sup data-n=\"5316\">9</sup> לכן חותמין מקדש השבת<sup data-n=\"5317\">10</sup> וביו\"ט",[["5308","1","<b>זכור את יום השבת</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5309","2","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח."],["5310","3","<b>ששת ימים . . מלאכתך</b>: יתרו שם, ט. ואתחנן ה, יג. ראה גם לקמן בסיום ההנחה."],["5311","4","<b>מלאכתך כו' ויום</b>: כ\"ה בגוכתי\"ק."],["5312","5","<b>ויום השביעי . . אלקיך</b>: יתרו שם, י. ואתחנן שם, יד."],["5313","6","<b>תעבוד . . ציווי . . אינו כן</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ובהערות 10-11."],["5314","7","<b>במדרש . . אמרה שבת</b>: ראה ב\"ר פי\"א, ח."],["5315","8","<b>ושמרו בנ\"י . . את השבת</b>: תשא לא, טז."],["5316","9","<b>ובאמת . . שבת מיקדשא וקיימא</b>: ביצה יז, א. ראה גם סה\"מ תרל\"א ח\"א ע' קנח. וש\"נ."],["5317","10","<b>חותמין מקדש השבת</b>: נוסח ברכת היום דשבת."]]],[2001910499,"חותמין מקדש ישראל והזמנים<sup data-n=\"5318\">11</sup> ישראל אינהו דקדשינהו לזמנא<sup data-n=\"5319\">12</sup> וכמ\"ש אלה מועדי ה' אשר תקראו אתם<sup data-n=\"5320\">13</sup> אתם כתי'<sup data-n=\"5321\">14</sup> בין בזמנן בין שלא בזמנן<sup data-n=\"5322\">15</sup>, ובגמ' אי' ג\"פ כתי' בפ' אתם<sup data-n=\"5323\">16</sup> אפי' שוגגין כו', וכתי' אקרא לאלקים עליון לאל גומר עלי<sup data-n=\"5324\">17</sup>, ואמרז\"ל אמרו מלה\"ש להקב\"ה מתי הם המועדים א\"ל אני ואתם נסכים<sup data-n=\"5325\">18</sup> למה שב\"ד עושין למטה שהן מעברי' השנה ובזה תלוי המועדים, לשעבר היו<sup data-n=\"5326\">19</sup> בידו של הקב\"ה כמ\"ש עשה ירח למועדים<sup data-n=\"5327\">20</sup> ועכשיו הוא בידו של הקב\"ה<sup data-n=\"5328\">21</sup>, הרי ישראל מקדשין המועדים משא\"כ שבת היא מיקדשי וקיימא, לכן מפרש רבינו (בתו\"א פ' יתרו ד\"ה זכור את יום השבת לקדשו הא') דכל שבת נק' שבת בראשית<sup data-n=\"5329\">22</sup> שהוא למעלה מישראל, וא\"כ צ\"ל מהו\"ע זכור את יום השבת לקדשו, לעשות את השבת. והנה אמרז\"ל קשה לזווגן כקרי\"ס<sup data-n=\"5330\">23</sup>, הרי קרי\"ס הו\"ע זיווג וצ\"ל מהו הזיווג דקרי\"ס.\n<b>והנה</b> אי' במדר' כל פרקמטיא של משה<sup data-n=\"5331\">24</sup> באז, קינטר באז דכתי' ומאז באתי אל פרעה<sup data-n=\"5332\">25</sup> כו' שיבח באז אז ישיר משה<sup data-n=\"5333\">26</sup> ובנ\"י<sup data-n=\"5334\">27</sup> כו'. להבין זה יובן בהקדים משנת\"ל<sup data-n=\"5335\">28</sup> דפעמים מצינו שישראל נתעלו ע\"י שעברו בים, ולפעמים מצינו דהים נתבטל לפני ישראל ונת\"ל דחלק הנפש המלובש בגוף נתעלה ע\"י הים דישראל הם בחי' ארץ<sup data-n=\"5336\">29</sup> וע\"י שעברו בים זכו לגילוי הנבואה שהוא גילוי ההעלם ואדרבה בים זכו למעלה עליונה יותר דכאו\"א מראה באצבע<sup data-n=\"5338\">31</sup> זה אלי<sup data-n=\"5337\">30</sup> כו', אבל לגבי שרש ומקור הנפש נתבטל הים לפניהם דים הוא [מ]<sup data-n=\"5339\">32</sup> בחי' דיבור וישראל עלו במח'<sup data-n=\"5340\">33</sup>,",[["5318","11","<b>מקדש ישראל והזמנים</b>: נוסח ברכת היום דיו\"ט."],["5319","12","<b>ישראל אינהו דקדשינהו לזמנא</b>: ראה ברכות מט, א."],["5320","13","<b>אלה מועדי . . תקראו אתם</b>: אמור כג, לז. במשנה ר\"ה כה, א הובא הכתוב אמור כג, ד. ראה שנויי נוסחאות במשניות שם. או אולי גם כאן הכוונה להכתוב כג, ד. אלא שהובא הכתוב בדילוג."],["5321","14","<b>אתם כתי'</b>: ראה רש\"י ר\"ה שם ד\"ה אתם."],["5322","15","<b>אתם . . בין שלא בזמנן</b>: ראה ר\"ה שם (במשנה)."],["5323","16","<b>ג\"פ כתי' בפ' אתם</b>: אמור כג, ב. ד. לז."],["5324","17","<b>אקרא לאלקים . . גומר עליי</b>: תהלים נז, ג."],["5325","18","<b>אמרו מלה\"ש . . נסכים</b>: ראה שמו\"ר פט\"ו, ב . ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 16."],["5326","19","<b>היו</b>: אולי כ\"ה בגכתי\"ק."],["5327","20","<b>עשה ירח למועדים</b>: תהלים קד, יט."],["5328","21","<b>הקב\"ה</b>: אוצ\"ל: ישראל."],["5329","22","<b>מפרש רבינו (בתו\"א . . שבת בראשית</b>: יתרו סט, ג ואילך. ראה גם לקמן פיסקא ועפ\"ז. לעיל (בחלק המאמרים) בהמאמר כאן הערה 21. נדרים עח, ע\"א ואילך."],["5330","23","<b>קשה לזווגן כקרי\"ס</b>: סוטה ב, א. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רלב. ס\"ע רלד ואילך. מארז\"ל ע' צ. שער האמונה נד, ב ואילך. מאמרי אדה\"א ויקרא ח\"א ע' ערב."],["5331","24","<b>במדר' כל פרקמטיא של משה</b>: ילקוט שמעוני שמות ד, כו [רמז קעד — ובמהדורת ירושלים תשל\"ז רמז קעא]. בשלח בשלח טו, א (רמז רמא)."],["5332","25","<b>ומאז באתי אל פרעה</b>: שמות ה, כג."],["5333","26","<b>אז ישיר משה</b>: בשלח טו, א."],["5334","27","<b>ובנ\"י</b>: בילקוט כאן ליתא. אבל הובא ברמז קעד הנ\"ל [ובמהדורת ירושלים הנ\"ל ליתא]."],["5335","28","<b>משנת\"ל</b>: בהנחה ד\"ה אז ישיר שנדפס לפני הנחה זו על יד הערה 143 ואילך."],["5336","29","<b>דישראל הם בחי' ארץ</b>: מלאכי ג, יב."],["5338","31","<b>דכאו\"א מראה באצבע</b>: ראה שמו\"ר פכ\"ג, טו."],["5337","30","<b>לגילוי הנבואה . . זה אלי</b>: ראה רש\"י שם. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך."],["5339","32","<b>[מ]</b>: כ\"ה בגוכתי\"ק."],["5340","33","<b>וישראל עלו במח'</b>: ראה גם לעיל הנחה ד\"ה הקבצו ושמעו ובהערה 53."]]],[2001910500,"ועוד דאפי' עלמא<sup data-n=\"5342\">35</sup> דאתכסיא<sup data-n=\"5341\">34</sup> ה\"ה בשם עלמין ומח' של ישראל קדמה לכל דבר<sup data-n=\"5343\">36</sup>, וזהו אז ישיר ומשה ובנ\"י, בנ\"י הם חלק הנפש המלובש בגוף ומשה הוא שרש ומקור הנפש<sup data-n=\"5344\">37</sup>, וזהו כי תקנה עבד עברי<sup data-n=\"5345\">38</sup>, עבד הוא חלק הנפש המלובש בגוף ועברי הוא בחי' בעבר הנהר ישבו אבותיכם<sup data-n=\"5346\">39</sup>, ובחי' זו הוא למעלה מים וישראל בעברם בים המשיכו תוספת אורות בים.\n<b>והענין</b> דהנה אי' במד' ע\"פ אז ישיר<sup data-n=\"5347\">40</sup> משה הה\"ד נכון כסאך מאז<sup data-n=\"5348\">41</sup>, אעפ\"י שמעולם אתה לא נתישבה כסאך ולא נודעת בעולמך עד שאמרו בניך שירה, בוימ\"ב הי' בעמידה, אבל בים בישיבה. וענין עמידה וישיבה למעלה<sup data-n=\"5349\">42</sup>, כמו עד\"מ למטה כשאדם מוטרד בעשי' הוא עומד ואח\"כ יושב לנוח, דישיבה הו\"ע מנוחה כמו וישב שלמה על כסא ה'<sup data-n=\"5350\">43</sup> וכתי' גבי' והוא יהי' איש מנוחה<sup data-n=\"5351\">44</sup>, וכן וישב יעקב<sup data-n=\"5352\">45</sup> אמרו במד' ביקש יעקב לישב בשלוה<sup data-n=\"5353\">46</sup>, וכמו\"כ יובן למעלה הנה כתי' ששת ימים עשה<sup data-n=\"5354\">47</sup> הם ששה מדות דכל יומא ויומא עביד עבידתא<sup data-n=\"5355\">48</sup>, וכן נשפלו המוחין ג\"כ כמארז\"ל בעשרה דברי' ברא הקב\"ה<sup data-n=\"5356\">49</sup> את עולמו, בחכ' ובתבונה ובדעת ובכח ובגערה כו', והגם דלא בעמל וביגיעה<sup data-n=\"5357\">50</sup> ברא הקב\"ה את עולמו כ\"א במאמר וברוח פיו מ\"מ הרי דיבורו של הקב\"ה חשיב מעשה<sup data-n=\"5358\">51</sup> ועוד דע\"מ מילין דהדיוטא אינון לאו",[["5342","35","<b>עלמא דאתכסיא</b>: ראה גם סה\"מ תרל\"ח ס\"ע קלח ואילך."],["5341","34","<b>עלמא דאתכסיא</b>: נסמן לעיל הנחה ד\"ה אז ישיר הערה **147."],["5343","36","<b>ומח' של ישראל קדמה לכל דבר</b>: ב\"ר פ\"א, ד."],["5344","37","<b>בנ\"י . . הנפש . . בגוף ומשה . . ומקור הנפש</b>: ראה גם בפיסקא הבאה. לעיל הנחה ד\"ה אז ישיר פיסקא וזהו אז ישיר."],["5345","38","<b>כי תקנה עבד עברי</b>: משפטים כא, ב. ראה גם לעיל שם על יד הערה 161 ואילך."],["5346","39","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב. ראה גם לקמן פיסקא והענין דהנה שרש."],["5347","40","<b>במד' ע\"פ אז ישיר</b>: ראה שמו\"ר רפכ\"ג. הובא גם בסה\"מ תרכ\"ט כאן ע' קמד. וש\"נ."],["5348","41","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["5349","42","<b>וענין עמידה וישיבה למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010200\" data-slug=\"or-hatorah-hb\" data-id=\"8159010200\">אוה\"ת חנוכה כרך ז ע' תתתנז</a> ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קכב. סה\"מ תרכ\"ט כאן ע' קנא. וש\"נ."],["5350","43","<b>וישב שלמה על כסא ה'</b>: דבהי\"א כט, כג."],["5351","44","<b>והוא יהי' איש מנוחה</b>: דבהי\"א כב, ט [ושם: הוא יהי' — אבל כ\"ה גם לקמן סוף פיסקא והענין דהנה כתי'. לעיל (בחלק המאמרים) בהמאמר כאן פ\"ד. סה\"מ תרכ\"ט כאן ע' קנא]."],["5352","45","<b>וישב יעקב</b>: וישב לז, א."],["5353","46","<b>ביקש יעקב לישב בשלוה</b>: ב\"ר פפ\"ד, ג. הובא ברש\"י וישב שם, ב."],["5354","47","<b>ששת ימים עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["5355","48","<b>דכל יומא . . עבידתא</b>: ראה זהר ויגש רה, סע\"א. אמור שם. השמטות לזח\"א רסד, ב."],["5356","49","<b>בעשרה דברי' ברא הקב\"ה</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 89 שמציין לחגיגה — ראה שם יב, א. לקמן בהנחה שם על יד הערה 90. הנחה ד\"ה והמים להם חומה על יד הערה 63. סה\"מ תר\"ם ח\"א ע' שפג. וש\"נ."],["5357","50","<b>דלא בעמל וביגיעה</b>: ראה ב\"ר פ\"ג, ב. פי\"ב, י. סה\"מ תרל\"ב ח\"ב ע' שפז. ע' שפט. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א. סה\"מ עטר\"ת ע' לח."],["5358","51","<b>דיבורו . . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח. אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרס\"ח ע' צט."]]],[2001910501,"אורחא דמלכא לאשתעי במילין דהדיוטא<sup data-n=\"5359\">52</sup>, ואח\"כ ביום השביעי שבת<sup data-n=\"5360\">53</sup> ופירש\"י שיש ללמוד מזה ק\"ו<sup data-n=\"5361\">54</sup> מה הקב\"ה דלא בעמל וביגיעה ברא הקב\"ה את עולמו מ\"מ כתב בעצמו לו<sup data-n=\"5362\">55</sup> שביתה אדם שהוא מעמל ומיגע עאכ\"ו שצריך לשבות דשביתה הו\"ע מנוחה, וזהו ביום השביעי נתעלה וישב על כסא כבודו<sup data-n=\"5363\">56</sup> פי' נתעלה הו\"ע החזרת המוחין למקורן ושרשן, ויש<sup data-n=\"5364\">57</sup> על כסא דשית דרגין לכורסיא ושביעאה עלייהו<sup data-n=\"5365\">58</sup>, שית דרגין הם ששה מדות ושביעאה עלייהו הוא הכסא עצמו וזהו וישב הו\"ע מנוחה, וזהו נכון כסאך מאז ע\"י שאמרו בניך שירה אז ישיר. דהנה ישיר הוא עלאה<sup data-n=\"5366\">59</sup> והו\"ע כלות הנפש לדבקה באוא\"ס, אז הוא המשכה, ז' הוא ז' מדות וא'<sup data-n=\"5367\">60</sup> הוא בחי' אלופו ש\"ע<sup data-n=\"5368\">61</sup>, וזהו שנמשך מבחי' א\"ס אלופו ש\"ע למדות, וענין אז ישיר הו\"ע משה ובנ\"י, בנ\"י הוא חלק הנפש המלובש בגוף ומשה הוא שרש ומקור הנשמה, ופי' משה ובנ\"י הוא בחי' משה שיש בכ\"א<sup data-n=\"5369\">62</sup>, דכאו\"א מברך חונן הדעת<sup data-n=\"5370\">63</sup> והוא בחי' משה שמקשר חלק הנפש המלובש בגוף עם שרש ומקור הנשמה.\n<b>והענין</b> דהנה שרש הנשמה הוא בחי' אז דאמרז\"ל כסה\"כ קדמה לעולם<sup data-n=\"5371\">64</sup> דכתי' נכון כסאך מאז, ומח' של ישראל קדמה לכל דבר א\"כ נק' ג\"כ אז, וזהו כגר כאזרח הארץ<sup data-n=\"5372\">65</sup> אזרח פי' תושב מאז ומקדם וכתי' כל האזרח בישראל<sup data-n=\"5373\">66</sup> א\"כ הרי ישראל נק' אז, דהנה השבירה הי' בז\"ת דשם<sup data-n=\"5375\">68</sup> ס\"ג<sup data-n=\"5374\">67</sup> עולם התיקון הוא שם מ\"ה<sup data-n=\"5376\">69</sup> המברר<sup data-n=\"5378\">71</sup>,",[["5359","52","<b>דע\"מ מילין . . במילין דהדיוטא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a>. אוה\"ת בא כרך ז ע' ב'תרכד. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 170 ואילך. סה\"מ תרכ\"ז ס\"ע רטו ואילך. תרל\"א ח\"א ע' ד."],["5360","53","<b>ביום השביעי שבת</b>: ע\"פ סיום הכתוב תשא שם."],["5361","54","<b>ופירש\"י . . ק\"ו</b>: ראה שם יתרו כ, יא."],["5362","55","<b>לו</b>: אינו ברור כ\"כ בגוכתי\"ק מה כתוב כאן."],["5363","56","<b>ביום השביעי . . כסא כבודו</b>: נוסח ברכת יוצר ד\"ה לא-ל אשר שבת."],["5364","57","<b>ויש</b>: אוצ\"ל: וישב."],["5365","58","<b>דשית דרגין . . עלייהו</b>: זהר תזריע מז, ב. ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 115."],["5366","59","<b>עלאה</b>: אוצ\"ל: העלאה."],["5367","60","<b>ז' . . וא'</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן פ\"ב ובהנסמן שם."],["5368","61","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["5369","62","<b>משה שיש בכ\"א</b>: ראה גם לעיל הנחה ד\"ה אז ישיר ובהערה 159."],["5370","63","<b>מברך חונן הדעת</b>: בתפלת שמונה עשרה."],["5371","64","<b>כסה\"כ קדמה לעולם</b>: ב\"ר פ\"א, ד."],["5372","65","<b>כגר כאזרח הארץ</b>: אמור כד, טז. כב. יהושע ח, לג [בהוספת תיבת: הארץ. בא יב, יט ושם: בגר ובאזרח הארץ. בהעלותך ט, יד ושם: ולגר ולאזרח הארץ]."],["5373","66","<b>כל האזרח בישראל</b>: אמור כג, מב. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270392\" data-slug=\"or-hatorah-hb\" data-id=\"8316270392\">אוה\"ת ויחי ח\"ב ס\"ע שצב</a> ואילך. ע' שפז."],["5375","68","<b>דשם ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["5374","67","<b>השבירה הי' בז\"ת דשם ס\"ג</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"א. שער התיקון ש\"י, פ\"ב. מבוא שערים ש\"ב ח\"א, פ\"א (ובהגה ג). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370436\" data-slug=\"torah-or\" data-id=\"3901370436\">תו\"א מג\"א צז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380841\" data-slug=\"likkutei-torah\" data-id=\"4001380841\">לקו\"ת פ' ראה לא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540330\" data-slug=\"torat-chaim\" data-id=\"2300540330\">תו\"ח בא ח\"א קיז, רע\"ג</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540915\" data-slug=\"torat-chaim\" data-id=\"2300540915\">וארא פה, ג</a>. וש\"נ)."],["5376","69","<b>עולם התיקון הוא שם מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"א ואילך."],["5378","71","<b>מ\"ה המברר</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[2001910502,"והנה שם ס\"ג ומ\"ה<sup data-n=\"5377\">70</sup> ה\"ז ע\"ד ובטובו מחדש בכ\"י תמיד מע\"ב<sup data-n=\"5380\">73</sup> שמתלבש בשמות אלו לצורך הבריאה ובתחילת הבריאה הם ג\"כ מחודשים<sup data-n=\"5379\">72</sup>, אבל שם ע\"ב<sup data-n=\"5381\">74</sup> הוא למעלה משם ס\"ג ומ\"ה והוא בחי' אזרח<sup data-n=\"5382\">75</sup> וזהו בעבר הנהר ישבו אבותיכם נהר בחי' בינה<sup data-n=\"5383\">76</sup> בעבר הנהר בחי' שם ע\"ב שהוא בחכ'<sup data-n=\"5384\">77</sup>, וא\"כ פי' משארז\"ל ישראל עלו במח' הוא כמ\"ש בזהר דמח' ויובלא לא אתפרש לעלמין<sup data-n=\"5385\">78</sup> יובלא בחי' בינה ומח' בחי' חכ'<sup data-n=\"5386\">79</sup>, ומבואר במ\"א פי' עלו במח' הוא מדרי' היותר עליונה במח', היינו בחילוקי שמות פרטים יש שם ע\"ב דע\"ב, ובאמת י\"ל פי' בעבר הנהר הוא בחי' א\"א<sup data-n=\"5387\">80</sup> שלמעלה גם מבחי' אזרח, ולפ\"ז מובן דישראל בעברם בים המשיכו תוס' אורות בים.\n<b>וזהו</b> מ\"ש במדר' ע\"פ לגוזר<sup data-n=\"5389\">82</sup> ים סוף לגזרים כל\"ח<sup data-n=\"5388\">81</sup>, גידל אתכם דוד המלך כו' ולכאו' הלא בפ' בשלח מדבר יותר מענין קרי\"ס, אך הענין דהנה בתורה כתי' ובנ\"י הלכו ביבשה בתוך הים<sup data-n=\"5390\">83</sup> הוא שנתעלו ישראל ע\"י שעברו בים שזכו לנבואה<sup data-n=\"5391\">84</sup>, אבל בתילים כתי' לגוזר ים סוף לגזרים כל\"ח, והעביר ישראל בתוכו כל\"ח<sup data-n=\"5392\">85</sup>, ולכאורה מפני מה מחלק זה לב' כל\"ח, והול\"ל לגוזר כו' לגזרים והעביר כו' כל\"ח, אלא מ\"ש והעביר כו' הוא מעלת הים וכמ\"ש בתורה, ומ\"ש לגוזר ים סוף כו' הוא מעלת ישראל שהים נתבטל לפניהם וזהו כל\"ח שהודיענו מעלת ישראל שגבה מדריגתה כ\"כ שהים נתבטל כו'. וזהו מ\"ש בסדר הגדה אילו קרע לנו את הים<sup data-n=\"5393\">86</sup> ולא העבירנו בתוכו דיינו, ולכאורה מה לנו שקרע לנו כו' מאחר דלא העבירנו כו', ולפי הנ\"ל מובן שהודיע לנו שרש הנשמה שנקרע הים לפני שרש הנשמה, שהוא בחי' אז כו'.",[["5377","70","<b>שם מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["5380","73","<b>ובטובו מחדש . . מע\"ב</b>: ברכת יוצר. ראה גם סה\"מ תר\"ם ח\"א ע' ה. וש\"נ."],["5379","72","<b>שם ס\"ג ומ\"ה . . מחודשים</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערות 57 (שם ס\"ג). 60 (שם מ\"ה)."],["5381","74","<b>שם ע\"ב</b>: ראה זהר תרומה קלב, ב. ועוד. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["5382","75","<b>שם ע\"ב . . אזרח</b>: ראה רמ\"ז לזהר אמור קג, סע\"א. לעיל (בחלק המאמרים) בהמאמר כאן ספ\"ב. וש\"נ."],["5383","76","<b>נהר בחי' בינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>: כמ\"ש בזהר פ' אמור [צט, א]."],["5384","77","<b>שם ע\"ב שהוא בחכ'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["5385","78","<b>דמח' ויובלא . . לעלמין</b>: ראה זהר ח\"ש קכג, א."],["5386","79","<b>ומח' בחי' חכ'</b>: ראה ת\"ז תי\"ט (מא, ב). תס\"ט (קטו, א). פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מחשבה. לקוטי הש\"ס להאריז\"ל סוף ברכות (ה, ב) שם נדפס ד\"ה אל יהרהר (כתובות מו, א). ע\"ח שער אנ\"ך שי\"ט, פ\"ט. מאו\"א מערכת מחשבה סנ\"ט וביאיר נתיב שם."],["5387","80","<b>בעבר הנהר . . א\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>."],["5389","82","<b>לגוזר ים סוף לגזרים</b>: תהלים קלו, יג."],["5388","81","<b>במדר' ע\"פ לגוזר . . כל\"ח</b>: ראה שהש\"ר ד, ד. לעיל הנחה ד\"ז אז ישיר בתחילתו ובהנסמן שם [ושם: ע\"פ כמגדל דוד . . לגוזר]."],["5390","83","<b>ובנ\"י . . בתוך הים</b>: בשלח יד, כט."],["5391","84","<b>שזכו לנבואה</b>: ראה מכילתא ורש\"י בשלח טו, ב. לעיל הנחה ד\"ה אז ישיר בתחילתו ובהנסמן שם."],["5392","85","<b>והעביר ישראל בתוכו כל\"ח</b>: תהלים קלו, יד. ראה גם לעיל (בחלק המאמרים) בהמאמר כאן פ\"ג ובהערה 79."],["5393","86","<b>אילו קרע לנו את הים</b>: ראה גם לעיל שם."]]],[2001910503,"<b>וזהו</b> מ\"ש במדר' נכון כסאך מאז כו' שנודעת בעולמך, דהנה כתי' וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי ה' לא נודעתי להם<sup data-n=\"5394\">87</sup> ומבואר במ\"א הקושי' דמצינו ש' הוי' גבי האבות, והתי' שהי' רק בדרך ידיעה אבל לא בדרך יעוד וחיבור<sup data-n=\"5395\">88</sup>, ובנ\"י ע\"י שיעבוד מצרים ויצי\"מ וקרי\"ס ואמרו שירה כתי' ונועדתי<sup data-n=\"5396\">89</sup> אליך שמה<sup data-n=\"5397\">90</sup>. וזהו משארז\"ל קינטור באז ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה, הנה פרעה אותיות הערף<sup data-n=\"5398\">91</sup> שהוא בחי' אחוריים דא\"א<sup data-n=\"5399\">92</sup> וזהו עבדים היינו לפרעה במצרים בנ\"י בחי' ז\"א<sup data-n=\"5400\">93</sup> עבדים לפרעה בחי' עורף אחורים דא\"א, וזהו שטען משה שפרעה הוא מונע ומעכב שלא יבואו לבחי' אז הוא שרש ומקור הנשמה<sup data-n=\"5401\">94</sup>, דפרעה אמר תכבד העבודה כו' ואל ישעו בדברי שקר<sup data-n=\"5402\">95</sup> שא' לא ידעתי את ה' מי ה'<sup data-n=\"5403\">96</sup> אשר אשמע בקולו שקיבל מבחי' רוממות<sup data-n=\"5404\">97</sup>, וזהו שמונע ומעכב כו' וזהו קינטור באז שא\"א לבוא לבחי' אז, ולכן גבי קרי\"ס כתיב וידעו מצרים כי אני ה'<sup data-n=\"5405\">98</sup> וית\"ל מהו\"ע אני ה'. והענין דהנה כתי' ה' איש מלחמה<sup data-n=\"5406\">99</sup>, והנה פסוק זה לא קאי על קרי\"ס כ\"א על ע\"מ שהביא הקב\"ה על המצרים במצרים<sup data-n=\"5407\">100</sup> וכמו שפירש\"י<sup data-n=\"5408\">101</sup> שנהג עמם תכסיסי מלחמה כעושין מצור על העיר תחילה מקללי'<sup data-n=\"5409\">102</sup> מעיינותיו וזהו מכות דם כו', משא\"כ בקרי\"ס הי' מנוחה וכמ\"ש שמעו עמים ירגזון<sup data-n=\"5410\">103</sup> כו' תפול עליהם אימתה<sup data-n=\"5411\">104</sup> כו' שקיבלו עליהם אימת הקב\"ה, ופי' ה' איש מלחמה, מלחמה בשם הוי' ולכאו' צ\"ל איך שייך מלחמה בשם הוי'.",[["5394","87","<b>וארא . . לא נודעתי להם</b>: וארא ו, ג. ראה גם לעיל שם מאמר ד\"ה הוא אהרן ומשה ובהערה 24."],["5395","88","<b>נודעתי . . יעוד וחיבור</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380313\" data-slug=\"likkutei-torah\" data-id=\"4001380313\">לקו\"ת במדבר א, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380319\" data-slug=\"likkutei-torah\" data-id=\"4001380319\">ב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380394\" data-slug=\"likkutei-torah\" data-id=\"4001380394\">נשא כא, ג</a>. פינחס עז, סע\"א. סידור שחרית לו, ד. אוה\"ת וארא ס\"ע קמז ואילך. ע' ר. סה\"מ תרכ\"ח ע' עד. ע' קנא. תרל\"ח ע' כה. לקמן הנחה ד\"ה וידבר כו' קדושים תהיו על יד הערה 35."],["5396","89","<b>נודעתי . . ונועדתי</b>: ראה גם לקו\"ת במדבר ונשא שם."],["5397","90","<b>ונועדתי אליך שמה</b>: תרומה כה, כב [ושם: לך שם]."],["5398","91","<b>פרעה אותיות הערף</b>: ראה לקו\"ת להאריז\"ל שמות עה\"פ (א, ח) ויקם מלך חדש בתחילתו. שער הפסוקים פ' וישב (לט, א) סט\"ל. סה\"מ תר\"ם ח\"ב ע' תרנה. וש\"נ."],["5399","92","<b>פרעה . . דא\"א</b>: ראה פע\"ח שער חג המצות שכ\"א, פ\"ז. מ\"ח מסכת סדר ליל פסח פ\"ז, מ\"א ואילך. סידור סדר הגדה רצד, ג. מאמרי אדה\"א ויקרא ח\"א ע' תכ. וש\"נ. בהערה שלפנ\"ז."],["5400","93","<b>עבדים היינו . . בנ\"י בחי' ז\"א</b>: נוסח ההגדה. ראה סידור סדר הגדה רצג, ג."],["5401","94","<b>אז . . הנשמה</b>: ראה גם סה\"מ תרכ\"ט כאן ע' קנ."],["5402","95","<b>תכבד העבודה . . שקר</b>: שמות ה, ט."],["5403","96","<b>לא ידעתי . . מי ה'</b>: ראה שמות ה, ב בהיפך הסדר."],["5404","97","<b>שקיבל מבחי' רוממות</b>: ראה גם בסמוך בפיסקא הבא."],["5405","98","<b>וידעו מצרים כי אני ה'</b>: בשלח יד, יח."],["5406","99","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["5407","100","<b>ע\"מ </b> [ עשר מכות]<b> . . במצרים</b>: נוסח הגדה."],["5408","101","<b>וכמו שפירש\"י</b>: ראה וארא ח, יז. ושם מציין: באגדה . . במדרש רבי תנחומא בא ד. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111027\" data-slug=\"likkutei-sichot\" data-id=\"1300111027\">לקו\"ש וארא כרך יא ע' 27</a> ואילך."],["5409","102","<b>כעושין . . מקללי'</b>: אוצ\"ל: כשעושין . . מקלקלי'."],["5410","103","<b>שמעו עמים ירגזון</b>: בשלח טו, יד."],["5411","104","<b>תפול עליהם אימתה</b>: בשלח שם, טז."]]],[2001910504,"<b>והענין</b> דהנה כתי' רם על כל גוים הוי' על השמים כבודו<sup data-n=\"5412\">105</sup> מי כה' אלקינו המגביהי לשבת<sup data-n=\"5413\">106</sup> המשפילי לראות בשמים וארץ<sup data-n=\"5414\">107</sup>, דפרעה טען רם על כל גוים ואינו משפיל א\"ע להשגיח על עלולים השפלים כ\"א על השמים כבודו על מלאכים שכלים נבדלים<sup data-n=\"5415\">108</sup>, אך באמת אינו כן דמגביהי לשבת המשפילי לראות בשמים וארץ דאפילו שמים שגם לדעתם משגיח שם ה\"ז ג\"כ השפלה לגבי כמו הארץ, והנה פרעה מקבל מבחי' רם על כל גוים כו' וכן מקבל גם מש' אלקים דידע מש' אלקים דיוסף א\"ל אלקים יענה את שלום פרעה<sup data-n=\"5416\">109</sup>, אבל מה' לא קיבל וכמ\"ש לא ידעתי את ה' מי ה' אשר אשמע בקולו, דכדי לקבל משם אלקים<sup data-n=\"5417\">110</sup> צריך להיות בבחי' ביטול והוא לא רצה להיות בטל כ\"א בגסות לי יאורי<sup data-n=\"5418\">111</sup> כו', אך ע\"י קרי\"ס וידעו מצרים בבחי' ידיעה כי אני הוי', וי\"ל כמ\"ש במדר' מאני של בו\"ד<sup data-n=\"5419\">112</sup> אתה יודע אני של הקב\"ה ומה פרעה שא' אני פרעה<sup data-n=\"5420\">113</sup> זכה לכל הכבוד הזה לכשיבוא אני של הקב\"ה עאכו\"כ, דהנה כתי' אני ראשון ואני אחרון<sup data-n=\"5421\">114</sup> ומבלעדי אין אלקים אני אחרון בחי' מל' שם אלקים<sup data-n=\"5423\">116</sup> וזהו אני הוי', דהוי' ואלקים כולא חד<sup data-n=\"5424\">117</sup>, ועוי\"ל דאני ראשון הוא בחי' רוממות הכתר<sup data-n=\"5422\">115</sup>, וזהו אני הוי' דבחי' רוממות הכתר והוי' כולא חד, ושניהם אמת דש' הוי' מחבר ב' בחי' אני לכן משם אורידך נאום הוי'<sup data-n=\"5425\">118</sup>, וזהו דכתיב על לע\"ל ראו עתה כי אני אני הוא<sup data-n=\"5426\">119</sup> כו' חיבור ב' בחי' אני ע\"י ש' הוי', וזהו מ\"ש בקרי\"ס אני הוי' בחי' הוי' שמחבר ב' בחי' אני, ועיקר הגילוי יהי' לע\"ל וצ\"ל דבקרי\"ס הי' הארה מבחי' זו, ולכן וידעו מצרים כו', וזהו ע\"ד ההפרש בין דוד לשלמה, דגבי דוד כתי' איש מלחמה<sup data-n=\"5427\">120</sup> לכן לא בנה בהמ\"ק<sup data-n=\"5428\">121</sup>, אבל שלמה הי' איש מנוחה וכמ\"ש והוא יהי' איש מנוחה לכן באו לשמוע חכמתו<sup data-n=\"5429\">122</sup> שנתבטלו לפניו.\n<b>ועפ\"ז</b> יובן מה שקרי\"ס נק' בשם זיווג, דהנה נת\"ל<sup data-n=\"5430\">123</sup> דגבי תורה כתי' תורה צוה לנו משה מורשה<sup data-n=\"5431\">124</sup> כו' שכנס\"י משפיעים בתורה הגם דאורייתא מחכ'",[["5412","105","<b>רם . . על השמים כבודו</b>: תהלים קיג, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a>. סידור שער תפלת ר\"ה רלז, ב ואילך. מאמרי אדה\"א דברים ח\"ג ס\"ע א'לג ואילך. וש\"נ."],["5413","106","<b>מי כה' . . המגביהי לשבת</b>: תהלים קיג, ה."],["5414","107","<b>המשפילי . . וארץ</b>: תהלים שם, ו [ושם: ובארץ]."],["5415","108","<b>מלאכים שכלים נבדלים</b>: ראה מו\"נ ח\"ב פ\"ב-פ\"ו. וראה שם ח\"א פמ\"ט. סה\"מ תר\"ם ח\"א ע' י. וש\"נ."],["5416","109","<b>אלקים . . שלום פרעה</b>: מקץ מא, טז."],["5417","110","<b>אלקים</b>: אוצ\"ל: הוי'."],["5418","111","<b>לי יאורי</b>: יחזקאל כט, ג."],["5419","112","<b>במדר' מאני של בו\"ד</b>: ראה ב\"ר פ\"צ, ב."],["5420","113","<b>אני פרעה</b>: מקץ מא, מד."],["5421","114","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["5423","116","<b>מל' שם אלקים</b>: ראה זהר בראשית כב, א. אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540393\" data-slug=\"torat-chaim\" data-id=\"2300540393\">תו\"ח וארא ח\"א עה, ב</a> הערה 202."],["5424","117","<b>דהוי' ואלקים כולא חד</b>: ראה זהר בהקדמה יב, א. וארא כו, ב. תרומה קסא, א ואילך. רע\"מ ואתחנן רסד, א. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540095\" data-slug=\"torat-chaim\" data-id=\"2300540095\">תו\"ח וארא ח\"א ס, א</a>. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ."],["5422","115","<b>אני . . מל' . . הכתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380503\" data-slug=\"likkutei-torah\" data-id=\"4001380503\">לקו\"ת שלח מז, ד</a>."],["5425","118","<b>משם אורידך נאום הוי'</b>: עובדי' א, ד."],["5426","119","<b>ראו עתה . . אני הוא</b>: האזינו לב, לט."],["5427","120","<b>דגבי דוד כתי' איש מלחמה</b>: שמו\"ב יז, ח. דבהי\"א כח, ג."],["5428","121","<b>לכן לא בנה בהמ\"ק</b>: דבהי\"א כב, ח."],["5429","122","<b>לכן באו לשמוע חכמתו</b>: מלכים-א ה, יד."],["5430","123","<b>נת\"ל</b>: בהנחה ד\"ה אז ישיר על יד הערה 43 ואילך."],["5431","124","<b>תורה צוה לנו משה מורשה</b>: ברכה לג, ד."]]],[2001910505,"נפקת<sup data-n=\"5432\">125</sup> אך אמרז\"ל בראשית בשביל התורה<sup data-n=\"5433\">126</sup> שנק' ראשית וכתי' ה' קנני ראשית דרכו<sup data-n=\"5434\">127</sup>, וישראל הם לי ראש<sup data-n=\"5435\">128</sup> אותיות אשר<sup data-n=\"5436\">129</sup> תענוג<sup data-n=\"5437\">130</sup> העליון בחי' שעשועים, והם משפיעים בתורה. וכמו\"כ יובן בשבת שהוא מיקדשא וקיימא משא\"כ יו\"ט ישראל אינהו דקדשינא לזמנא, דיו\"ט בעצם הוא מוחין דאימא וכתי' מקרא קודש<sup data-n=\"5439\">132</sup> שישראל ממשיכים בחי' קדש במוחין דאי' והיינו בחי' נה\"י דאבא שמתלבש במוחין דאי', אבל שבת הוא מקדשי וקיימא שהוא עצם מוחין דאבא<sup data-n=\"5438\">131</sup> ונק' שבת בראשית ופי' הרשב\"א דו' יומי המעשה ושבת הם בחי' ז' ימי ההיקף<sup data-n=\"5440\">133</sup>, והרא\"ש פי' דיו\"ט נק' ג\"כ שבת<sup data-n=\"5441\">134</sup> לכן שבת נק' שבת בראשית אבל מ\"מ נק' שבת בראשית שמקבל מבחי' ראש שישראל משפיעים בשבת. ומ\"מ ניחא מה שפי' רבינו ז\"ל דשבת בראשית למעלה מישראל, דהנה נת\"ל<sup data-n=\"5442\">135</sup> גבי מצות דכתי' וזכרתם את כל מצות הוי'<sup data-n=\"5443\">136</sup> כו' למען תזכרו ועשיתם את כל מצותי<sup data-n=\"5444\">137</sup>, שבחי' מצות הוי' הם בחי' רמ\"ח פקודין רמ\"ח אברי' דמלכא<sup data-n=\"5445\">138</sup> והם משפיעים בישראל ועי\"ז חלק<sup data-n=\"5446\">*139</sup> הנפש המלובש בגוף עם שרש ומקור הנפש ומשפיעים במצות, וכמו\"כ יובן בשבת דעצם מצות שביתת שבת למעלה מישראל אבל מ\"ע ומל\"ת שיש בשבת ישראל ממשיכים אוא\"ס במצות. וכמו\"כ יובן בקרי\"ס דאיך שיפורש ים סוף דאם נא' שהוא בחי' סופא דכל דרגין<sup data-n=\"5447\">139</sup> וישראל בחי' ז\"א<sup data-n=\"5448\">140</sup> הרי ישראל למעלה מהים ואפי' נא' שהוא בחי' ים החכמה<sup data-n=\"5449\">141</sup>, ה\"ה בחי' ראשית וישראל הם בחי' ראש א\"כ משפיעים בבחי' ים. וזהו זכור את יום השבת לקדשו היינו להמשיך בחי' עונג בחכ' ועז\"א ששת ימים תעבוד הוא עבודת הבירורים שעי\"ז ממשיכים בחי' עונג, וזהו זכור את יום דהנה יש ליל שבתא ויום השבת<sup data-n=\"5450\">142</sup> וצריכים להמשיך גם בבחי' יו\"ם השבת כו'.",[["5432","125","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["5433","126","<b>בראשית בשביל התורה</b>: בראשית א, א. ראה רש\"י שם. לקו\"ש נח כרך ג ע' 755 בהערה."],["5434","127","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["5435","128","<b>וישראל הם לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["5436","129","<b>ראש אותיות אשר</b>: ראה זהר בראשית טו, סע\"א. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ב. סה\"מ תר\"ם ח\"א ע' קסג. וש\"נ."],["5437","130","<b>אשר תענוג</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות יח, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370238\" data-slug=\"torah-or\" data-id=\"3901370238\">ויצא כג, ג</a>. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."],["5439","132","<b>מקרא קדש</b>: בא יב, טז. ועוד."],["5438","131","<b>דיו\"ט . . מוחין דאימא . . שבת . . מוחין דאבא</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. סה\"מ תר\"ם ח\"א ס\"ע קפז ואילך. וש\"נ."],["5440","133","<b>ופי' הרשב\"א . . ז' ימי ההיקף</b>: בשו\"ת ח\"א ס\"ט."],["5441","134","<b>והרא\"ש פי' . . שבת</b>: לנדרים עח, ריש ע\"ב."],["5442","135","<b>נת\"ל</b>: בהנחה ד\"ה אז ישיר על יד הערה 135."],["5443","136","<b>וזכרתם את כל מצות הוי'</b>: שלח טו, לט."],["5444","137","<b>למען תזכרו . . מצותי</b>: שלח שם, מ."],["5445","138","<b>רמ\"ח פקודין רמ\"ח אברי' דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5446","*139","<b>ועי\"ז חלק</b>: כ\"ה בגוכתי\"ק."],["5447","139","<b>ים סוף . . דכל דרגין</b>: ראה זהר בשלח נו, א. רע\"מ פינחס רנה, א."],["5448","140","<b>וישראל בחי' ז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a>. מאמרי אדה\"א דברים ח\"ד ע' א'שב ואילך."],["5449","141","<b>מהים . . ים החכ'</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן פ\"ו הערה 167."],["5450","142","<b>ליל שבתא ויום השבת</b>: זהר בהקדמה ה, ב."]]],[2001910506,"<h3>ועבדתם את ה' אלקיכם</h3>\n<b>ש\"פ משפטים</b>\n<b>ועבדתם</b> את ה' אלקיכם<sup data-n=\"5451\">1</sup> וברך את לחמך ואת מימך והסרתי מחלה מקרבך<sup data-n=\"5452\">2</sup>, וארז\"ל ק\"ש ותפלה<sup data-n=\"5453\">3</sup>, וכן אמרז\"ל ע\"פ לעבדו בכל לבבכם<sup data-n=\"5454\">4</sup> איזה עבודה שבלב זו תפלה<sup data-n=\"5455\">5</sup>. הרי ענין עבודה הוא ק\"ש ותפלה וצ\"ל זה. והנה צ\"ל בפסוק זה מ\"ש תחילה ועבדתם את ה' אלקיכם ל' נסתר ואח\"כ והסרתי מחלה מקרבך ל' נוכח<sup data-n=\"5456\">6</sup> כמדבר בעדו, וגם צ\"ל מי אומר פסוק זה אם משה אמרו הרי תחילת הפ' הוא הנה אנכי שולח מלאך לפניך<sup data-n=\"5457\">7</sup>, אלא דהוא דיבור הקב\"ה אל משה וא\"כ הול\"ל והייתם לי עבדים וכמ\"ש כן במ\"א<sup data-n=\"5458\">8</sup> וגם הול\"ל וברכתי את לחמך כו' כמו והסרתי כו', אלא צ\"ל כמ\"ש הרמב\"ן בהקדמתו לפי' החומש<sup data-n=\"5459\">9</sup> שמשה כ' את התורה לא כמו שארי הנביאים כמו יחזקאל כ' ויהי דבר ה' אלי לאמר<sup data-n=\"5460\">10</sup> אבל כ' בדרך שלישי המספר כמו וידבר ה' אל משה<sup data-n=\"5461\">11</sup>, וענין שלישי המספר הוא בחי' א\"ס עצמות המאציל<sup data-n=\"5462\">12</sup> שמספר דבר ה' שדיבר אל משה, זהו פי' שלישי המדבר שכ' הרמב\"ן, וכמו\"כ יובן כאן מ\"ש ועבדתם הו\"ע שלישי המספר, וע\"ד מ\"ש בכל סיום פ' אני ה' ולכאו' והלא שם ה' אינו ידוע<sup data-n=\"5463\">13</sup> ומה שייך לאמר אני ה', דאני שייך על דבר הידוע אומר אני זה משא\"כ שם הוי' כו', והענין דאני קאי על בחי' א\"ס עצומ\"ה והוא כח<sup data-n=\"5464\">14</sup> המספר וא\"ס שגור בפי כל אפי' בתינוקת<sup data-n=\"5465\">15</sup>, הו\"ע אני ראשון ואני אחרון<sup data-n=\"5466\">16</sup>, וזהו אני הוי' שבחי' אני ראשון והוי' כולא חד<sup data-n=\"5467\">17</sup>, וכמו\"כ מ\"ש ועבדתם כו' הו\"ע שלישי המספר.",[["5451","1","<b>ועבדתם את ה' אלקיכם</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5452","2","<b>ועבדתם . . מחלה מקרבך</b>: משפטים כג, כה."],["5453","3","<b>ק\"ש ותפלה</b>: ב\"ק צב, ב."],["5454","4","<b>לעבדו בכל לבבכם</b>: עקב יא, יג [ושם: ולעבדו]."],["5455","5","<b>איזה עבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["5456","6","<b>תחילה ועבדתם . . ל' נסתר . . ל' נוכח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010164\" data-slug=\"or-hatorah-hb\" data-id=\"8159010164\">אוה\"ת</a> משפטים כאן ע' א'ריט. ע' א'רלט."],["5457","7","<b>הנה אנכי . . לפניך</b>: משפטים כג, כ."],["5458","8","<b>והייתם לי עבדים . . במ\"א</b>: ראה בהר כה, מב. נה."],["5459","9","<b>הרמב\"ן בהקדמתו לפי' החומש</b>: ראה פתיחת הרמב\"ן על התורה. לקמן הנחה ד\"ה וברך את לחמך בסופה. (לעיל בחלק המאמרים) בהמאמר כאן הערה 8."],["5460","10","<b>ויהי דבר . . לאמר</b>: ראה לעיל שם הערות 12-13."],["5461","11","<b>וידבר ה' אל משה</b>: וארא ו, י."],["5462","12","<b>שלישי המספר . . א\"ס עצמות המאציל</b>: ראה גם אוה\"ת יתרו ע' תשעא. ובשם אדה\"ז בפלח הרמון יתרו ע' ריז. אמור ע' רל וע' רלב."],["5463","13","<b>אני הוי' . . אינו ידוע</b>: לך טו, ז. ועוד. ראה גם סה\"מ תרל\"ח ע' שלב. וש\"נ."],["5464","14","<b>כח</b>: תיבה זו איננה ברורה בגוכתי\"ק."],["5465","15","<b>וא\"ס שגור . . אפי' בתינוקת</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן בשולי הגליון א. וש\"נ."],["5466","16","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["5467","17","<b>אני . . והוי' כולא חד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה זכור ובהערה 100."]]],[2001910507,"<b>וענין</b> העבודה בגמ'<sup data-n=\"5468\">18</sup> ובפסיקתא<sup data-n=\"5469\">19</sup> משמע דעבודה צורך גבוה<sup data-n=\"5470\">20</sup>, ובהרבה מדרשים משמע דעבודה אינו צורך גבוה דמה איכפת לי'<sup data-n=\"5471\">21</sup> כו' והעה\"ק פי' ע\"פ זה ועבדתם כו' דעבודה צורך גבוה<sup data-n=\"5472\">22</sup>, שע\"י העבודה נמשך תוס' אורות למעלה וכמארז\"ל ע\"פ צור ילדך תשי<sup data-n=\"5473\">23</sup> יו\"ד<sup data-n=\"5475\">25</sup> זעירא<sup data-n=\"5474\">24</sup> דבזמן דאין ישראל ערש\"מ כביכול מתישין כח של מעלה, ובזמן שישראל עושין רש\"מ מוסיפין כח בגבורה של מעלה וזהו ועתה יגדל נא כח אד'<sup data-n=\"5476\">26</sup> ביו\"ד רבתי<sup data-n=\"5477\">27</sup>, וכמשארז\"ל דמשה כשעלה למרום<sup data-n=\"5478\">28</sup> לקבל תורה א\"ל וכי אין שלום בעירך א\"ל וכי דרך התלמיד ליתן שלום לרבו א\"ל הי' לך לעזרני מיד אמר ועתה יגדל נא כח אד', הרי מוסיפין כו', ועל ל' הקבלה<sup data-n=\"5479\">29</sup> יו\"ד רבתי בחי' מו\"ס דכתר שהוא למעלה מסדר השתל' ובזמן שישראל ערש\"מ נמשך מבחי' מו\"ס, אבל בזמן שאין ישראל ערש\"מ נמשך מיו\"ד זעירא בחי' ח\"ת אבל אורות דלמעלה מאצי' אינו מאיר. אך צ\"ל איך שייך עבודה למעלה, דלמטה שייך שהעבד משרת רבו דהרב חסר והעבד משלים חסרונו אבל א\"ס דאנת שלימותא דכולא<sup data-n=\"5480\">30</sup> כלום חסר מה שייך עבודה.\n<b>והענין</b> דאמרז\"ל גדולים מעשה צדיקים<sup data-n=\"5481\">31</sup> ממעשה שמים וארץ דמעשה שו\"א כתי' אף ידי יסדה ארץ<sup data-n=\"5482\">32</sup> וימיני טפחה שמים אבל מעשה צדיקים מקדש אד' כוננו ידיך<sup data-n=\"5483\">33</sup>, והענין דכללות כל המצות נק' בשם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"5484\">34</sup> כי",[["5468","18","<b>בגמ'</b>: שבת פט, א הועתק בסמוך בפנים."],["5469","19","<b>ובפסיקתא</b>: ראה פסיקתא דר\"כ פסקא סליחות (פסקא כו)."],["5470","20","<b>דעבודה צורך גבוה</b>: ראה עבודת הקודש בהקדמה. חלק העבודה פ\"א ואילך. סה\"מ תר\"ם ח\"ב ע' תשכב. וש\"נ. עבודת הקודש דבסמוך בפנים."],["5471","21","<b>ובהרבה מדרשים . . דמה איכפת לי'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן. וש\"נ."],["5472","22","<b>והעה\"ק פי' . . ועבדתם . . דעבודה צורך גבוה</b>: חלק העבודה פט\"ו [קה, א]."],["5473","23","<b>צור ילדך תשי</b>: האזינו לב, יח. ראה פסיקתא שם. ילקוט שמעוני האזינו לב, יח רמז תתקמה. ועוד."],["5475","25","<b>יו\"ד זעירא . . ביו\"ד רבתי</b>: ראה גם תו\"ח סנהדרין דמ\"ו בד\"ה קלני הועתק באוה\"ת איוב שם. הובא גם (ברשימות על איכה ע' 12, נדפס) באוה\"ת איכה כרך ב ע' א'מא."],["5474","24","<b>תשי יו\"ד זעירא</b>: מסורה קטנה האזינו שם. ראה אנציקלפדי' תלמודית חכ\"א מערכת יו\"ד ע' קלו הערה 80. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600679\" data-slug=\"or-hatorah-hb\" data-id=\"8316600679\">אוה\"ת איוב כרך א ע' תרעט</a> ואילך (מג\"א ע' ב'שצז ואילך. ובמהדורת תש\"נ ע' ריג ואילך). סה\"מ תרל\"ח ע' תעד."],["5476","26","<b>ועתה יגדל נא כח אד'</b>: שלח יד, יז."],["5477","27","<b>יגדל . . ביו\"ד רבתי</b>: מסורה ריש בראשית. ראה אנציקלפדי' שם הערה 76. אוה\"ת איוב שם."],["5478","28","<b>דמשה כשעלה למרום</b>: ראה שבת פט, א."],["5479","29","<b>ועל ל' הקבלה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 43."],["5480","30","<b>דאנת שלימותא דכולא</b>: ראה ת\"ז בהקדמה יז, ב."],["5481","31","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א."],["5482","32","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["5483","33","<b>מקדש אד' כוננו ידיך</b>: בשלח טו, יז."],["5484","34","<b>כל המצות . . צדקה . . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. סה\"מ תרל\"ח ע' שמט. וש\"נ. תר\"ם ח\"א ע' צח. וש\"נ. ח\"ב ע' תפה. וש\"נ. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 51. ד\"ה [נקדישך] וביאור הענין על יד הערה 51. ד\"ה כי תבואו וכו' ושבתה הארץ [ובהנחה שם] בסופם. לקמן הנחה ד\"ה וידבר כו' קדושים תהיו על יד הערה 53."]]],[2001910508,"נשמור לעשות כל המצות<sup data-n=\"5485\">35</sup> הזאת, והעושה צדקה נק' צדיק<sup data-n=\"5486\">36</sup> שממשיך צדקה, והנה כתי' בראשית ברא אלקים<sup data-n=\"5487\">37</sup> ובכל וימ\"ב לא נז' שם הוי' כ\"א שם אלקים רק לאחר השבת כתי' ביום עשות הוי' אלקים<sup data-n=\"5488\">38</sup> ארץ ושמים, והענין דשם הוי' הוא שמו הגדול<sup data-n=\"5489\">39</sup> שלמעלה מהשתלשלות והוא משארז\"ל עד שלא נבה\"ע הי' הוא ושמו לבדו<sup data-n=\"5490\">40</sup> והוא בחי' סוכ\"ע<sup data-n=\"5491\">41</sup> שהרי הוא קודם שנבה\"ע, והנה כתי' וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי הוי' לא נודעתי להם<sup data-n=\"5492\">42</sup>, דגבי אבות הי' גילוי שם שדי שאמר לעולמו די<sup data-n=\"5493\">43</sup>, והוא מקור הגבול מן הארץ לרקיע מהלך ת\"ק שנה<sup data-n=\"5494\">44</sup> בין כל רקיע מהלך ת\"ק שנה כו' ואפי' עולמות עליונים הם מוגבלים ואפי' ג\"ע שהוא בד\"כ ג\"ר<sup data-n=\"5495\">45</sup> ה\"ז הגבלה דהשגה הוא הגבלה, וכדי שיהי' גבול מא\"ס הבבע\"ג דאינו בערך<sup data-n=\"5496\">46</sup> יותר משאין ערוך אחד לגבי אלף אלפים ורבוא רבבות שהם מסוג אחד וגם הם בערך זל\"ז הגם דעצם המספר אינו בערך מ\"מ ה\"ז חלק א' מאלף אלפים ורבוא רבבות אבל לגבי בלי מספר הרי אלף אלפים ורבוא רבבות, ואחד, בהשואה אחת, וכדי שיתהווה הגבול מבבע\"ג, הוא ע\"י שם אלקים שהוא מדת הצמצום<sup data-n=\"5497\">47</sup>, וזהו במע\"ב כתי' שם אלקים דוימ\"ב הוא בבחי' דיבורו של הקב\"ה שחשיב מעשה<sup data-n=\"5498\">48</sup> לכן כתי' שם אלקים אבל לאחר השבת דכתיב ויברך את יום השביעי ויקדש אותו<sup data-n=\"5499\">49</sup> והו\"ע העלאת העולמות אז כתי' ביום עשות הוי' אלקים ארץ ושמים, דגבי שבת כתי' סגור יהי' ששת ימי המעשה וביום השבת יפתח, י'מי ה'מעשה ו'ביום ה'שבת ר\"ת הוי'<sup data-n=\"5500\">50</sup> דבשבת נמשך בחי' ענג העליון ומאיר בחי' הוי', וזה גדולים מעשה צדיקים",[["5485","35","<b>כל המצות</b>: בואתחנן שם: את כל המצוה. ראה גם לקמן הנחה ד\"ה וידבר כו' קדושים תהיו על יד הערה 54."],["5486","36","<b>והעושה צדקה נק' צדיק</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 52."],["5487","37","<b>בראשית ברא אלקים</b>: בראשית א, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381257\" data-slug=\"likkutei-torah\" data-id=\"4001381257\">לקו\"ת שה\"ש לב, א</a>. סידור שער התפלה כז, א. מאמרי אדה\"ז תקס\"ט ס\"ע לה ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550323\" data-slug=\"torat-chaim\" data-id=\"2300550323\">תו\"ח יתרו ח\"ב רסו, ב</a> ואילך ובהנסמן שם. (לעיל בחלק המאמרים) מאמר ד\"ה ראה קראתי בשם ספ\"ב ואילך."],["5488","38","<b>ביום עשות הוי' אלקים</b>: בראשית ב, ד."],["5489","39","<b>דשם הוי' הוא שמו הגדול</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370225\" data-slug=\"torah-or\" data-id=\"3901370225\">תו\"א שמות נ, רע\"א</a>. לקו\"ת פ' ראה נ, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470011\" data-slug=\"or-hatorah-hb\" data-id=\"8316470011\">אוה\"ת שמות ע' יא</a>. כרך ז שמות ע' ב'תעט. ע' ב'תפג. סה\"מ תר\"ם ח\"א ע' רכו ובהנסמן שם."],["5490","40","<b>עד שלא . . ושמו לבדו</b>: ראה פדר\"א פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540053\" data-slug=\"torat-chaim\" data-id=\"2300540053\">תו\"ח וארא ח\"א נג, ב</a> הערה 6."],["5491","41","<b>סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["5492","42","<b>וארא . . לא נודעתי להם</b>: וארא ו, ג."],["5493","43","<b>שדי שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה הוא אהרן ומשה על יד הערה 80."],["5494","44","<b>מן הארץ לרקיע . . ת\"ק שנה</b>: ראה חגיגה יג, א. (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 23 ואילך. ולקמן בהנחה שם על יד הערה 20 ואילך."],["5495","45","<b>ג\"ע . . ג\"ר</b>: ראה ביאוה\"ז אחרי עה, א. ולהצ\"צ שם כרך א ע' שנג ואילך. סה\"מ תר\"ם ח\"ב ע' תקי. וש\"נ."],["5496","46","<b>גבול מא\"ס הבבע\"ג דאינו בערך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381282\" data-slug=\"likkutei-torah\" data-id=\"4001381282\">לקו\"ת שה\"ש לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381253\" data-slug=\"likkutei-torah\" data-id=\"4001381253\">שערי אורה לא, א</a> ובהערה 23. סה\"מ תר\"ם ח\"ב ע' תשכז. וש\"נ."],["5497","47","<b>שם אלקים . . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."],["5498","48","<b>דיבורו . . שחשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח. אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרס\"ח ע' צט."],["5499","49","<b>ויברך . . ויקדש אותו</b>: בראשית ב, ג [בדילוג]."],["5500","50","<b>סגור יהי' . . ר\"ת הוי'</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערות 73-74."]]],[2001910509,"ממעשה שו\"א דמעשה שו\"א כתי' אף ידי יסדה ארץ וימיני טפחה שמים, ידי יד כהה<sup data-n=\"5501\">51</sup> וכמ\"ש נטה ימינו ברא שמים<sup data-n=\"5502\">52</sup> נטה שמאלו וברא ארץ לכן בארץ העלם והסתר אלקות, ובשמים שנברא ביד מאיר<sup data-n=\"5503\">53</sup> בו גילוי אלקות יותר מבארץ, אך מהשמים אינו נמשך בהארץ וכן הי' בתחילת הבריאה שמשמים לא יומשך בארץ וכמ\"ש השמים שמים לה'<sup data-n=\"5504\">54</sup> והארץ נתן לבני אדם אבל מעשה צדיקים כתי' מקדש א\"ד כוננו ידיך ב' ידות בחד מעשה שע\"י קיום תומ\"צ בנין המקדש שהוא ג\"כ מצוה<sup data-n=\"5505\">55</sup> ממשיכים מבחי' שמים בארץ.\n<b>וזהו</b> ועבדתם את הוי' אלקיכם שענין העבודה הוא להמשיך שם הוי' הגם דהוי' הוא למעלה מסדר השתל' מ\"מ הוא רק שם בלבד, ואף דהוי' הוא בחי' סוכ\"ע<sup data-n=\"5506\">56</sup>, מ\"מ לגבי' גם סוכ\"ע אינו תופס מקום כלל לכן תחילת שם הוי' ביו\"ד שכדי שיומשך שם הוי' צ\"ל צמצום<sup data-n=\"5507\">57</sup>, לכן צדיקים ע\"י עבודתם ממשיכים שם הוי' מחדש, וענין אלקיכם דיש אלקיך וכמ\"ש בק\"ש ואהבת את הוי' אלקיך<sup data-n=\"5508\">58</sup> שהוי' יהי' אלקיך אלוקה שלך כמו\"כ הוי' יהי' אלקיכם, והגם שלאחר השבת כתי' ביום עשות הוי' אלקים ארץ ושמים הרי נמשך שם הוי', אך בגלות מצרים קוב\"ה סליק לעילא ולעילא<sup data-n=\"5509\">59</sup> לכן צריכים להמשיך שם הוי' שיהי' אלקיכם, ומ\"ש א\"ת הוי' כו' הם אותיות מא' עד ת'<sup data-n=\"5510\">60</sup> בחי' דיבור בע\"מ נברא העולם<sup data-n=\"5511\">61</sup> והוא מקור העולם, וזהו את הוי' דכתי' יראו את הוי' כל קדושיו<sup data-n=\"5512\">62</sup> וכתי' יראו מהוי' כל הארץ<sup data-n=\"5513\">63</sup>, כשכל הארץ היא יראה מהוי' בחי' יר\"ת ויראו את הוי' הוא בחי' יר\"ע<sup data-n=\"5514\">64</sup> לכן רב<sup data-n=\"5515\">65</sup> קדושיו כו', דאת הוי' הוא שטפל ובטל לה' וכמו את בשרו הטפל לבשרו<sup data-n=\"5516\">66</sup>, כמו\"כ כאן מ\"ש את הוי' הוא בחי' יר\"ע.",[["5501","51","<b>ידי יד כהה</b>: ראה מנחות לו, סע\"ב."],["5502","52","<b>נטה ימינו ברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a> בפנים. סה\"מ תרל\"ג ח\"ב ע' שסה ואילך."],["5503","53","<b>ביד מאיר</b>: אוצ\"ל: ביד ימין מאיר."],["5504","54","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["5505","55","<b>בנין המקדש שהוא ג\"כ מצוה</b>: סהמ\"צ להרמב\"ם מ\"ע כ. רמב\"ם הל' בית הבחירה פ\"א, ה\"א."],["5506","56","<b>דהוי' . . סוכ\"ע</b>: ראה פיסקא שלפנ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380613\" data-slug=\"likkutei-torah\" data-id=\"4001380613\">לקו\"ת בלק עג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380615\" data-slug=\"likkutei-torah\" data-id=\"4001380615\">עד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540173\" data-slug=\"torat-chaim\" data-id=\"2300540173\">תו\"ח וארא ח\"א עג, ב</a>. וש\"נ."],["5507","57","<b>שיומשך שם הוי' צ\"ל צמצום</b>: ראה לקו\"ת שמע\"צ צב, ד. סה\"מ תרכ\"ט ע' קכו. וש\"נ."],["5508","58","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370368\" data-slug=\"torah-or\" data-id=\"3901370368\">תו\"א תצוה פב, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381297\" data-slug=\"likkutei-torah\" data-id=\"4001381297\">לקו\"ת שה\"ש מב, ב</a>."],["5509","59","<b>קוב\"ה סליק לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א קונטרסים ע' שסג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540232\" data-slug=\"torat-chaim\" data-id=\"2300540232\">תו\"ח שמות ח\"א לט, סע\"א</a> ואילך ובהערה 72. סה\"מ תר\"ם ח\"א ע' שיב. וש\"נ."],["5510","60","<b>את . . אותיות מא' עד ת'</b>: ראה זהר בראשית כט, ב. רקאנטי בראשית דף ב, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380774\" data-slug=\"likkutei-torah\" data-id=\"4001380774\">לקו\"ת עקב טו, א</a>. מאמרי אדה\"א שמות ח\"ב ע' שלז. וש\"נ."],["5511","61","<b>בע\"מ נברא העולם</b>: אבות רפ\"ה."],["5512","62","<b>יראו את הוי' כל קדושיו</b>: תהלים לד, י [בהוספת תיבת: כל — ראה גם סה\"מ תרכ\"ט ע' שלא]."],["5513","63","<b>יראו מהוי' כל הארץ</b>: תהלים לג, ח."],["5514","64","<b>יראה מהוי' בחי' יר\"ת ויראו את הוי' . . יר\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380361\" data-slug=\"likkutei-torah\" data-id=\"4001380361\">לקו\"ת במדבר יג, ב</a>. לקמן הנחה ד\"ה והמים להם חומה ובהערה"],["5515","65","<b>רב</b>: אוצ\"ל: רק."],["5516","66","<b>את בשרו הטפל לבשרו</b>: משפטים כא, כח. ב\"ק מא, ב."]]],[2001910510,"<b>והנה</b> מהו העבודה זה משארז\"ל זו ק\"ש ותפלה, דק\"ש הוא העלאה<sup data-n=\"5517\">67</sup> ותפלה הוא ל' התחברות ל' התופל כלי חרס<sup data-n=\"5518\">68</sup>, וכתי' וסולם מוצב ארצה<sup data-n=\"5519\">69</sup> וראשו מגיע השמים<sup data-n=\"5520\">70</sup> ובסולם עולים מלמטלמ\"ע, וגם מלמעלמ\"ט, וזהו ארוממך אלקי המלך<sup data-n=\"5521\">71</sup>, אלקי הוא בחי' שם אלקים המלך הוא בחי' מלכותך מל' כל העולמים<sup data-n=\"5522\">72</sup> שבחי' הוא<sup data-n=\"5523\">73</sup> מקור כל עולמים העלם והסתר<sup data-n=\"5524\">74</sup>, וצריכים לרומם לבחי' מל' בבחי' א\"ס עצומ\"ה, וכמו\"כ ענין התפלה שהוא בירור הנה\"ב דתפילין<sup data-n=\"5525\">75</sup> כנגד תמידין תקנו<sup data-n=\"5526\">76</sup> שהעיקר הוא העלאת הנה\"ב<sup data-n=\"5527\">77</sup>, וזהו ועבדתם את הוי' אלקיכם שע\"י הביטול לבחי' הוי' ממשיכים שם הוי', והעיקר הוא ע\"י שם הוי' שבנפש<sup data-n=\"5528\">78</sup> והוא ק\"ש ותפלה הם רצוא ושוב<sup data-n=\"5529\">79</sup>, ק\"ש הוא רצוא דאם רץ לבך<sup data-n=\"5530\">80</sup>, וזהו ואהבת שרשו אבה<sup data-n=\"5531\">81</sup> ל' רצון ותשוקה לאלקות, ותפלה הוא שוב וכמ\"ש ברוך אתה הוי' ומה שייכות התפלה ליר\"ע הוא [דעיקר] שם הוי' הוא יו\"ד<sup data-n=\"5532\">82</sup> בחי' חכ'<sup data-n=\"5533\">83</sup> והוא בחי' יר\"ע, וה' ראשונה הוא ק\"ש העלאה ובק\"ש יש תורה ג\"כ והיו הדברים האלה<sup data-n=\"5534\">84</sup> הוא בחי' ו' דכתי' הקל קול יעקב<sup data-n=\"5535\">85</sup> קלא קדמאה חסר ו' הוא קול דתפלה וקלא בתראה מלא ו' הוא קול דתורה והו\"ע שיתא סדרי משנה<sup data-n=\"5536\">86</sup> בחי' ששה מדות<sup data-n=\"5537\">87</sup>,",[["5517","67","<b>דק\"ש הוא העלאה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקסט ואילך. בסמוך הערה 79."],["5518","68","<b>ותפלה . . התופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה פ\"א. וש\"נ."],["5519","69","<b>וסולם מוצב ארצה</b>: ויצא כח, יב [ושם: והנה סולם. ראה גם מאמרי אדה\"א במדבר ח\"ב ס\"ע תו. ע' תמב. קונטרסים ע' תקפ]."],["5520","70","<b>השמים</b>: בויצא שם: השמימה."],["5521","71","<b>ארוממך אלקי המלך</b>: תהלים קמה, א. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370183\" data-slug=\"torah-or\" data-id=\"3901370183\">תו\"א מקץ מ, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">מא, סע\"א</a> ואילך."],["5522","72","<b>מלכותך מל' כל העולמים</b>: תהלים שם, יג [ושם: עולמים]."],["5523","73","<b>שבחי' הוא</b>: אוצ\"ל: שבחי' מל' הוא."],["5524","74","<b>עולמים העלם והסתר</b>: ראה ספר הבהיר ס\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541025\" data-slug=\"torat-chaim\" data-id=\"2300541025\">תו\"ח שמות ח\"א יח, ד</a> הערה 783."],["5525","75","<b>דתפילין</b>: אוצ\"ל: דתפלה."],["5526","76","<b>דתפלה כנגד תמידין תקנו</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["5527","77","<b>שהעיקר הוא העלאת הנה\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">לקו\"ת האזינו עד, ג</a>."],["5528","78","<b>שם הוי' שבנפש</b>: ראה גם בענין שם ה' שבנפש <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>. סה\"מ תר\"ם ח\"א ע' ט. וש\"נ."],["5529","79","<b>ק\"ש ותפלה הם רצוא ושוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370005\" data-slug=\"torah-or\" data-id=\"3901370005\">תו\"א בראשית א, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381316\" data-slug=\"likkutei-torah\" data-id=\"4001381316\">לקו\"ת שה\"ש מז, א</a>. שער האמונה עז, ב. מאמרי אדה\"א שמות ח\"ב ס\"ע שכח ואילך. וש\"נ."],["5530","80","<b>דאם רץ לבך</b>: ס\"י פ\"א, מ\"ח."],["5531","81","<b>ואהבת שרשו אבה</b>: ראה ס' שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב [צב, רע\"א — ובמהדורת אותיות מרובעות (תשס\"ג) צד, א]. מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540947\" data-slug=\"torat-chaim\" data-id=\"2300540947\">תו\"ח בשלח ח\"א קצט, ב</a>. וש\"נ."],["5532","82","<b></b> [דעיקר]<b> שם הוי' הוא יו\"ד</b>: ראה גם סה\"מ תרל\"ח ע' כו. וש\"נ."],["5533","83","<b>יו\"ד בחי' חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["5534","84","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["5535","85","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. מאמרי אדה\"א בראשית ע' שמח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680453\" data-slug=\"torat-chaim\" data-id=\"2300680453\">תו\"ח מקץ רכז, ב</a> ובהערות 32-4."],["5536","86","<b>שיתא סדרי משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111064\" data-slug=\"likkutei-sichot\" data-id=\"1300111064\">לקו\"ש בשלח כרך יא ע' 56</a> הערה 13."],["5537","87","<b>שיתא . . ששה מדות</b>: ראה ת\"ז בהקדמה ה, א. תכ\"א מג, ב ובכסא מלך שם אות ר. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550336\" data-slug=\"torat-chaim\" data-id=\"2300550336\">תו\"ח תצוה ח\"ב שסב, ד</a> ובהערה 70 [ושם נדפס אות ב. וצ\"ל: אות ר]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380834\" data-slug=\"likkutei-torah\" data-id=\"4001380834\">לקו\"ת פ' ראה כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">שה\"ש יט, ב</a>."]]],[2001910511,"וה' אחרונה הוא דיבור בתורה ודברת בם<sup data-n=\"5538\">88</sup> ועי\"ז ממשיכים בחי' שם הוי' למעלה.\n<b>ועל</b> ל' הקבלה הוא להמשיך מוחין לז\"א וט\"ס למל', דז\"א נאצל בסוד שרש רק ששה מדות<sup data-n=\"5539\">89</sup> ומל' נאצל רק נקודה חדא<sup data-n=\"5540\">90</sup>, וזהו ויהיו חיי שרה<sup data-n=\"5541\">91</sup> מאה שנה ועשרים שנה ושבע שנים, עשרים הוא בחי' חו\"ב שנאצלו בעשר ספירות ושבע הוא בחי' זו\"ן בכלל, והנה קטן אינו מוליד<sup data-n=\"5542\">92</sup> שעדיין לא נשלמו המוחין בשלימות וכדי שיהי' גילוי מבחי' ז\"א למטה צריכים להמשיך מוחין לז\"א וזהו\"ע הקב\"ה מניח תפילין<sup data-n=\"5543\">93</sup> הקב\"ה ז\"א<sup data-n=\"5544\">94</sup> מניח תפילין המשכות מוחין לז\"א, ומל' שנאצל נקודה חדא א\"א להיות הגילוי למטה וצריכים להמשיך ט\"ס למל'. ושרש ההפרש בין הוי' לאלקים הו\"ע אורות וכלים<sup data-n=\"5545\">95</sup>, כלים הם בחי' ש' אלקים שם אל בחסד<sup data-n=\"5546\">96</sup> שם אלקים בגבורה<sup data-n=\"5547\">97</sup>, וענין הכלים הוא שמגבילים האור<sup data-n=\"5548\">98</sup>, ולפ\"ד הע\"ח הם גבול ממש<sup data-n=\"5549\">99</sup> וזהו מ\"ש בפרקי היכלות שיעור קומה של יוצר בראשית רל\"ו אלפים רבוא רבבות אלפים פרסאות<sup data-n=\"5550\">100</sup> ואף שהמספר הוא מספר של מעלה מ\"מ ה\"ז הגבלה, ואף לפ\"ד הפרד\"ס שהכלים אינם גבול<sup data-n=\"5551\">101</sup> מ\"מ הם מקור הגבול, הוא בחי' שם אלקים, ושם הוי' הו\"ע האורות דכל הע\"ס, ומ\"ש דש' הוי' בת\"ת<sup data-n=\"5552\">102</sup> היינו שבת\"ת גם הכלי שם הוי'<sup data-n=\"5553\">103</sup> שהוא",[["5538","88","<b>ודברת בם</b>: ואתחנן ו, ז. ראה ספרי ופרש\"י שם. יומא יט, ב ובפרש\"י שם ד\"ה בם (הב'). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071278\" data-slug=\"likkutei-sichot\" data-id=\"1300071278\">לקו\"ש פסח כרך ז ע' 266</a> הערה 2. פקודי כרך טז ע' 462 ואילך ובהערות שם."],["5539","89","<b>ז\"א . . ששה מדות</b>: ראה ע\"ח שער המלכים שי\"א, פ\"ה. שער המוחין ש\"כ, פ\"א. שער מיעוט הירח של\"ו, פ\"א."],["5540","90","<b>ומל' . . נקודה חדא</b>: ראה ע\"ח שער המלכים שם. שער מיעוט הירח שם, פ\"א. פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380121\" data-slug=\"likkutei-torah\" data-id=\"4001380121\">לקו\"ת צו יא, ב</a>."],["5541","91","<b>ויהיו חיי שרה</b>: ח\"ש כג, א. ראה זהר שם קכג, א. ביאוה\"ז ח\"ש קלא, ב ואילך."],["5542","92","<b>קטן אינו מוליד</b>: ראה סנהדרין סח, ב ואילך. סה\"מ תר\"ם ח\"א ע' קסז. וש\"נ."],["5543","93","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' ובהערה 126."],["5544","94","<b>הקב\"ה ז\"א</b>: ראה ע\"ח שער הכללים פי\"ב. לקוטי הש\"ס להאריז\"ל ברכות ו, א (ה, א בדפי הספר)."],["5545","95","<b>ההפרש בין הוי' לאלקים הו\"ע אורות וכלים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370269\" data-slug=\"torah-or\" data-id=\"3901370269\">תו\"א בא ס, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540245\" data-slug=\"torat-chaim\" data-id=\"2300540245\">תו\"ח בא ח\"א קיג, ב</a> ואילך. סה\"מ תרמ\"ג ע' עה ואילך."],["5546","96","<b>שם אל בחסד</b>: ראה זהר אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["5547","97","<b>שם אלקים בגבורה</b>: ראה זהר יתרו פג, ב. הנסמן בתו\"ח שם הערה 41."],["5548","98","<b>הכלים הוא שמגבילים האור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו\"ת אחרי כח, ג</a>. ביאוה\"ז בשלח מ, א. בלק ק, ב."],["5549","99","<b>ולפ\"ד הע\"ח הם גבול ממש</b>: ראה שם שער דרושי אבי\"ע שמ\"ב, פ\"ב. סה\"מ תר\"ם ח\"ב ע' תרמח ובהנסמן שם."],["5550","100","<b>בפרקי היכלות . . אלפים פרסאות</b>: ראה גם סה\"מ תרל\"ח ע' ז ובהערות שם. (לעיל בחלק המאמרים) בהמאמר כאן בסופו."],["5551","101","<b>לפ\"ד הפרד\"ס שהכלים אינם גבול</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערות 136-137."],["5552","102","<b>דש' הוי' בת\"ת</b>: ראה זהר ויקרא יא, א. ע\"ח שער השמות שער מ\"ד, פ\"ג. פ\"ו. סידור שער המועדים ריז, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670419\" data-slug=\"torat-chaim\" data-id=\"2300670419\">תו\"ח בראשית מא, א</a> הערה 7."],["5553","103","<b>שבת\"ת גם הכלי שם הוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370042\" data-slug=\"torah-or\" data-id=\"3901370042\">תו\"א נח י, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> ואילך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשפד."]]],[2001910512,"מחבר חו\"ג<sup data-n=\"5554\">104</sup> ושרשו למעלה מעלה דת\"ת עולה עד הכתר<sup data-n=\"5555\">105</sup> לכן גם הכלי שם הוי' אבל האורות דכל הע\"ס הם הוי'. וזהו ועבדתם את הוי' אלקיכם, ענין העבודה הוא להיות יחוד הוי' אלקים המשכות אורות בכלים והוא ע\"י ק\"ש ותפלה כו'.",[["5554","104","<b>שבת\"ת . . שהוא מחבר חו\"ג</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. (לעיל בחלק המאמרים) מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 49. סה\"מ תר\"ם ח\"א ע' רלא-רלג."],["5555","105","<b>דת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."]]],[2001910513,"<h3>וברך את לחמך</h3>\n<b>ש\"פ תרומה</b>\n<b>וברך</b> את לחמך<sup data-n=\"5556\">1</sup> ואת מימיך והסירותי<sup data-n=\"5557\">2</sup> מחלה מקרבך, לחמך קאי על בחי' תורה<sup data-n=\"5558\">3</sup> כמ\"ש<sup data-n=\"5559\">4</sup> לכו לחמו בלחמי<sup data-n=\"5560\">5</sup>, כתי'<sup data-n=\"5561\">6</sup> ותורתך בתוך מעי<sup data-n=\"5562\">7</sup>, והוא לחם למטה לנפש האדם וגם לחם למעלה, וצ\"ל איך שייך לחם למעלה. והענין דהנה המאכל פעולתו לחבר הנשמה עם הגוף ולולא המאכל יכול להיות שיפרד הנשמה מהגוף, וכמו\"כ יובן למעלה דהנה למעלה איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"5563\">8</sup>, גרמוהי הם המדות<sup data-n=\"5564\">9</sup> העליונות לך ה' הגדולה והגבורה<sup data-n=\"5565\">10</sup> כו' וכדי שיהי' איהו וגרמוהי כו' דכולא לאחזאה איך מתנהג עלמין אבל לאו דאית לך צדק ידיעה כו' ולא מכל אמ\"כ<sup data-n=\"5566\">11</sup> וכדי שיומשך אוא\"ס במצות<sup data-n=\"5567\">12</sup> הוא ע\"י איהו וחיוהי, שהוא בחי' חכ' ע\"ש והחכ' תחי'<sup data-n=\"5568\">13</sup> ומשם נמשך במדות וזהו שהתורה נק' לחם דאורייתא מחכ' נפקת<sup data-n=\"5569\">14</sup> והוא דראשית הגילוי בחכ' אבל [עצם: התפשטות]<sup data-n=\"5570\">15</sup> התורה הו\"ע כשר פסול טמא טהור כו' ששה מדות ואורייתא וקוב\"ה כולא חד<sup data-n=\"5571\">16</sup> וע\"י התורה נמשך מחכ' במדות, ומבינה נמשך",[["5556","1","<b>וברך את לחמך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5557","2","<b>וברך את לחמך ואת מימיך והסירותי</b>: משפטים כג, כה."],["5558","3","<b>לחמך . . תורה</b>: ראה שבת קכ, א. לקו\"ש בהעלותך כרך ד ע' 1038 הערה 26. <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a> ובמ\"מ הגהות והע\"ק לשם. סה\"מ תרכ\"ז ע' קמט. וש\"נ. תרל\"ג ח\"ב כאן ע' תלה. וש\"נ."],["5559","4","<b>כמ\"ש</b>: תיבה זו איננה ברורה בהצילום."],["5560","5","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה זח\"א בהשמטות רס, א."],["5561","6","<b>כתי'</b>: אולי צ\"ל: וכתי'."],["5562","7","<b>ותורתך בתוך מעי</b>: תהלים מ, ט. ראה תניא שם."],["5563","8","<b>איהו וחיוהי . . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["5564","9","<b>גרמוהי הם המדות</b>: ראה סה\"מ תרמ\"ג ע' עז: ”כן פי' בע\"ח ובאגה\"ק ד\"ה איהו וחיוהי\" רס\"כ. סה\"מ תר\"ם ח\"א ע' מג. וש\"נ."],["5565","10","<b>לך ה' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["5566","11","<b>דכולא לאחזאה . . מכל אמ\"כ</b>: ראה ת\"ז בהקדמה יז, ב."],["5567","12","<b>במצות</b>: אולי צ\"ל: במדות."],["5568","13","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 10]."],["5569","14","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["5570","15","<b></b> [עצם: התפשטות]<b></b>: כ\"ה בגוכתי\"ק."],["5571","16","<b>ואורייתא וקוב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."]]],[2001910514,"ג\"כ<sup data-n=\"5572\">17</sup> במדות דמובן מענין הנדרים<sup data-n=\"5573\">18</sup> דבינה היא חיי המדות, דחו\"ב הם תרדל\"מ<sup data-n=\"5574\">19</sup>, ובכלל חיוהי הוא מוחין<sup data-n=\"5575\">20</sup> ומשם נמשך בבחי' גרמוהי וה\"ז כמו עד\"מ הנשמה שמחי' את הגוף עיקר משכנה במוחין<sup data-n=\"5576\">21</sup> ומשם מתפשטת בכל האברים כמו\"כ עיקר השראת אוא\"ס במוחין ומשם נמשך במדות, וכן התורה היא לחם למטה לנה\"א להתקשר באלקות דישראל מתקשראן באורייתא<sup data-n=\"5577\">22</sup> ואורייתא בקוב\"ה, וכן היא לחם לנה\"ב כמ\"ש אם רעב שונאך<sup data-n=\"5578\">23</sup> האכילהו לחם, שלמה קרא להיצה\"ר שונא<sup data-n=\"5579\">24</sup> והאכילהו לחם לחמה של תורה<sup data-n=\"5580\">25</sup>, או כמו שפירש\"י מלחמתה של תורה<sup data-n=\"5581\">26</sup> הטריחהו בדברי תורה דכשיטריחו בד\"ת לא יהי' לו זמן להסית, ובסיום הפסוק<sup data-n=\"5582\">27</sup> כתי' וה' ישלם לך<sup data-n=\"5583\">28</sup> ואמרז\"ל ישלימנו עמך<sup data-n=\"5584\">29</sup>, שהנה\"ב יהי' לו ג\"כ אהבה לה', וזהו שתורה נק' לחמך, וברך לחמך שהלחם צריך ברכה.\n<b>והענין</b> דהנה כתי' מי האיש החכם ויבן את זאת ואמרז\"ל דבר זה נשאלו חכמים ונביאים ולא פירשוהו עד שפירשה הקב\"ה בעצמו על מה אבדה הארץ<sup data-n=\"5586\">31</sup> על עזבם את תורתי<sup data-n=\"5587\">32</sup> ואר\"י אמר רב על שאין מברכין בתורה תחילה (נדרים פ\"א ע\"א<sup data-n=\"5585\">30</sup>), ולכאורה צ\"ל וכי מפני חטא קל כזה יהי' עונש מר כ\"כ<sup data-n=\"5588\">33</sup>. והענין דהנה תורה נק' זאת וכמ\"ש זאת חוקת התורה<sup data-n=\"5590\">35</sup> ותרגם דא גזרת אורייתא, ואמרז\"ל יבא זה ויקבל זאת מזה<sup data-n=\"5591\">36</sup> לעם זו, יבא זה זה משה ויקבל זאת זו תורה, ופעמים כתי' וזאת<sup data-n=\"5589\">34</sup> התורה<sup data-n=\"5592\">37</sup> כמו וזאת המצוה<sup data-n=\"5593\">38</sup>, וענין ו' הוא מורה על המשכה ממדרי' גבוה וכמ\"ש בזהר ונתתם לי אות אמת<sup data-n=\"5594\">39</sup> דא אות ו', ואמת הו\"ע אני",[["5572","17","<b>ג\"כ</b>: תיבה זו איננה ברורה בהצילום."],["5573","18","<b>דמובן מענין הנדרים</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 14 ואילך ובהנסמן שם."],["5574","19","<b>דחו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["5575","20","<b>חיוהי הוא מוחין</b>: ראה גם סה\"מ תרל\"ח ע' יד. וש\"נ. תר\"ם ח\"א ע' תכד. וש\"נ."],["5576","21","<b>הנשמה . . עיקר משכנה במוחין</b>: ראה רבינו יונה לברכות יד, סע\"ב ד\"ה הרוצה. שו\"ע הל' תפילין סכ\"ה, ס\"ה. ובשו\"ע אדה\"ז שם סי\"א. תניא פנ\"א. מאמרי אדה\"א דברים ח\"ג ע' תתסו. וש\"נ. שמות ח\"ב ע' תקמג ואילך. ש\"א י, ב הערה 31."],["5577","22","<b>דישראל מתקשראן באורייתא</b>: ראה זהר אחרי עג, א."],["5578","23","<b>אם רעב שונאך</b>: משלי כה, כא."],["5579","24","<b>להיצה\"ר שונא</b>: סוכה נב, א."],["5580","25","<b>לחמה של תורה</b>: רש\"י משלי שם."],["5581","26","<b>שפירש\"י מלחמתה של תורה</b>: סוכה שם ד\"ה האכילהו לחם."],["5582","27","<b>ובסיום הפסוק</b>: כי גחלים — הובא בסוכה שם."],["5583","28","<b>וה' ישלם לך</b>: משלי כה, כב."],["5584","29","<b>ישלימנו עמך</b>: ראה סוכה שם."],["5586","31","<b>על מה אבדה הארץ</b>: ירמי' שם."],["5587","32","<b>על עזבם את תורתי</b>: ירמי' שם, יב."],["5585","30","<b>מי האיש החכם . . נדרים פ\"א ע\"א</b>: ירמי' ט, יא. ראה שם."],["5588","33","<b>חטא קל כזה . . עונש מר כ\"כ</b>: ראה גם פי' הרי\"ף לע\"י נדרים שם."],["5590","35","<b>זאת חוקת התורה</b>: חוקת יט, ב."],["5591","36","<b>יבא זה ויקבל זאת מזה</b>: ראה מנחות נג, ב."],["5589","34","<b>תורה נק' זאת . . וזאת</b>: ראה גם הנסמן בסה\"מ תרל\"ג כאן ע' תלז."],["5592","37","<b>וזאת התורה</b>: ואתחנן ד, מד."],["5593","38","<b>וזאת המצוה</b>: ואתחנן ו, א."],["5594","39","<b>ונתתם לי אות אמת</b>: יהושע ב, יב. זהר ויקרא ב, א. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' ח ואילך. ביאורי הזהר להצ\"צ כרך א ע' שיג ואילך."]]]]});
